INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "语义：名字是别人给的称呼，生病不会使人失去名字。"}, {"text": "劳动力", "is_correct": true, "explanation": "劳动力指人所具有的劳动能力，生病后失去它，语义通顺。"}, {"text": "皮肤", "is_correct": false, "explanation": "搭配：皮肤是身体的一部分，不能说“生病以后失去皮肤”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人身上的东西，生病不会使人失去天气。"}], "explanations": {"名字": "语义：名字是别人给的称呼，生病不会使人失去名字。", "劳动力": "劳动力指人所具有的劳动能力，生病后失去它，语义通顺。", "皮肤": "搭配：皮肤是身体的一部分，不能说“生病以后失去皮肤”。", "天气": "语义：天气不是人身上的东西，生病不会使人失去天气。"}, "sentence_index": 0, "correct_answer": "劳动力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的劳动力有五十公斤。", "explanation": "这里应该用〈体重〉。“劳动力”指能从事劳动的人或其劳动能力，不能用来说重量，说人的重量要用〈体重〉。"}, {"text": "他用劳动力推开了门。", "explanation": "这里应该用〈力气〉。“劳动力”指人的劳动能力或劳动人员，不能用来表示用身体的力量做动作，用力推门要说〈力气〉。"}, {"text": "他失去了一只劳动力。", "explanation": "这里应该用〈一部分〉。“只”用于动物或成对器官中的一个，不能修饰抽象的劳动能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脚步", "is_correct": false, "explanation": "搭配：“没有”后接的应是可以缺少的人或物，“脚步”是动作，不能这样用。"}, {"text": "劳动力", "is_correct": true, "explanation": "劳动力指能干活的能力，手受伤后暂时没有它，语义吻合。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶与手受伤、干活的语境无关。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”是人本来就有的属性，不能用“没有”来表示暂时缺少。"}], "explanations": {"脚步": "搭配：“没有”后接的应是可以缺少的人或物，“脚步”是动作，不能这样用。", "劳动力": "劳动力指能干活的能力，手受伤后暂时没有它，语义吻合。", "树叶": "语义：树叶与手受伤、干活的语境无关。", "年龄": "搭配：“年龄”是人本来就有的属性，不能用“没有”来表示暂时缺少。"}, "sentence_index": 6, "correct_answer": "劳动力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的劳动力很强，能解决难题。", "explanation": "这里应该用〈能力〉。“劳动力”指能从事体力劳动的能力，不能用来形容解决难题这类脑力工作。"}, {"text": "他的劳动力很差，看不清字。", "explanation": "这里应该用〈视力〉。“劳动力”指能从事体力劳动的能力，不用来说眼睛看东西的能力。"}, {"text": "他失去了一台劳动力。", "explanation": "这里应该用〈一部分〉。“台”用于机器等器械，不能修饰抽象的劳动能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "女儿病好以后，劳动力就恢复了一根。", "corrected_sentence": "女儿病好以后，劳动力就恢复了一部分。", "error_description": "量词错误：“劳动力”（能力义）前应用〈一部分〉，“根”用于细长的东西，不能修饰劳动能力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的手受伤以后，失去了一根劳动力。", "corrected_sentence": "他的手受伤以后，失去了一部分劳动力。", "error_description": "量词错误：“劳动力”前应用〈一部分〉，“根”用于细长的物体，不能修饰劳动能力。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93371, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93371, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93371, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "严肃是脸上不笑，认真又很安静。", "primary_collocate": null, "pronunciation": "yán sù", "ipa": "iɛn˧˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "老师脸上一点笑容也没有，样子很严肃。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在那里，一句话也不说，表情很严肃。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸看起来很严肃，我不敢大声说话。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她今天脸色很严肃，大家都很安静。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生的样子很严肃，没有笑。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照相的时候，他总是很严肃，不笑。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长走进教室，脸很严肃，大家不说话了。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么这么严肃？笑一笑吧。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他平时很严肃，很少开玩笑。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子看到他严肃的脸，一下子安静了。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "严肃了", "label": "体标"}, {"form": "严肃地", "label": "状语形式"}, {"form": "嚴肅", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人的脸色、表情不笑、认真而安静", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59765317-1277-4541-a33b-efb6288b49af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93371, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严肃", "is_correct": true, "explanation": "正确：“严肃”指脸上不笑、神情认真，与“一点笑容也没有”相合。"}, {"text": "和蔼", "is_correct": false, "explanation": "语义：“和蔼”指态度亲切、常带笑容，与“一点笑容也没有”相矛盾。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”指人爱说爱笑、有生气，与“一点笑容也没有”相矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面、气氛，不用来形容人的“样子”。"}], "explanations": {"严肃": "正确：“严肃”指脸上不笑、神情认真，与“一点笑容也没有”相合。", "和蔼": "语义：“和蔼”指态度亲切、常带笑容，与“一点笑容也没有”相矛盾。", "活泼": "语义：“活泼”指人爱说爱笑、有生气，与“一点笑容也没有”相矛盾。", "热闹": "搭配：“热闹”形容场面、气氛，不用来形容人的“样子”。"}, "sentence_index": 0, "correct_answer": "严肃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的病情很严肃，需要马上去医院。", "explanation": "这里应该用〈严重〉。严重指程度深、情况危险，病情、后果要用严重；严肃指人的神情或气氛庄重。"}, {"text": "他的牙齿很严肃，每天都刷。", "explanation": "这里应该用〈洁白〉。洁白指颜色纯白、干净，形容牙齿、衣服等；严肃指神情不笑、庄重，不能形容牙齿。"}, {"text": "这块布料很严肃，穿起来很舒服。", "explanation": "这里应该用〈柔软〉。柔软指质地软，形容布料；严肃指神情或气氛庄重，不能形容布料的质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严肃", "is_correct": true, "explanation": "正确：“严肃”指脸上不笑、神情认真，与“大家不说话了”的场面相合。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”形容声音或场面，不用来形容人的“脸”。"}, {"text": "欢快", "is_correct": false, "explanation": "语义：“欢快”指愉快、有生气，与“大家不说话了”的场面相矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音杂乱，不用来形容人的“脸”。"}], "explanations": {"严肃": "正确：“严肃”指脸上不笑、神情认真，与“大家不说话了”的场面相合。", "吵闹": "搭配：“吵闹”形容声音或场面，不用来形容人的“脸”。", "欢快": "语义：“欢快”指愉快、有生气，与“大家不说话了”的场面相矛盾。", "嘈杂": "搭配：“嘈杂”形容声音杂乱，不用来形容人的“脸”。"}, "sentence_index": 6, "correct_answer": "严肃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "球迷们看到冠军，都非常严肃。", "explanation": "这里应该用〈兴奋〉。兴奋指情绪激动、高涨，形容球迷庆祝；严肃指神情不笑、庄重安静，不能形容欢呼的场面。"}, {"text": "这个小女孩很严肃，一进教室就笑个不停。", "explanation": "这里应该用〈活泼〉。活泼指爱说爱笑、动作灵活，形容小孩的性格；严肃指神情不笑、庄重，与一进门就笑个不停相矛盾。"}, {"text": "今天天气很严肃，适合出去玩。", "explanation": "这里应该用〈晴朗〉。晴朗指天空明亮、没有云，形容天气；严肃指人的神情或气氛庄重，不能形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师严肃的说：“大家安静。”", "corrected_sentence": "老师严肃地说：“大家安静。”", "error_description": "结构助词错误：“严肃”修饰动词“说”、作状语时应用“地”，说“严肃地说”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家一下子严肃起了来。", "corrected_sentence": "大家一下子严肃起来了。", "error_description": "补语错误：“起来”是补语，应紧接在“严肃”后面，说“严肃起来了”，不能在“起”和“来”之间插入“了”。错误形式：严肃起了来；正确形式：严肃起来了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93372, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻松", "is_correct": true, "explanation": "反义：“严肃”指神情或气氛庄重认真，“轻松”指不紧张、不拘束，二者相对。"}, {"text": "清晰", "is_correct": false, "explanation": "无关：“清晰”形容看得、听得分明，与“严肃”的神情、气氛没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "无关：“宽敞”形容空间大，与“严肃”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线充足，与“严肃”没有反义关系。"}], "correct_answer": "轻松", "explanations": {"轻松": "反义：“严肃”指神情或气氛庄重认真，“轻松”指不紧张、不拘束，二者相对。", "清晰": "无关：“清晰”形容看得、听得分明，与“严肃”的神情、气氛没有反义关系。", "宽敞": "无关：“宽敞”形容空间大，与“严肃”没有反义关系。", "明亮": "无关：“明亮”形容光线充足，与“严肃”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93372, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻松", "is_correct": true, "explanation": "反义：“严肃”指神情或气氛庄重认真，“轻松”指不紧张、不拘束，二者相对。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”形容质地，与“严肃”没有反义关系。"}, {"text": "湿润", "is_correct": false, "explanation": "无关：“湿润”形容含水分适度，与“严肃”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：“迅速”形容速度快，与“严肃”没有反义关系。"}], "correct_answer": "轻松", "explanations": {"轻松": "反义：“严肃”指神情或气氛庄重认真，“轻松”指不紧张、不拘束，二者相对。", "柔软": "无关：“柔软”形容质地，与“严肃”没有反义关系。", "湿润": "无关：“湿润”形容含水分适度，与“严肃”没有反义关系。", "迅速": "无关：“迅速”形容速度快，与“严肃”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93372, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "气氛、话题或态度庄重认真，不随便，不轻松。", "primary_collocate": null, "pronunciation": "yán sù", "ipa": "iɛn˧˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "会议室里的气氛很严肃，没有人笑。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一个严肃的问题，请大家认真想。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说话很严肃，不像平时那样轻松。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会的时候，大家讨论得很严肃。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事很重要，我们要严肃对待。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的语气很严肃，不像在开玩笑。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院里的气氛严肃，没有人大声说话。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长讲话时，会场十分严肃。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个话题太严肃了，我们换一个吧。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板的态度很严肃，我知道事情不简单。", "target_word": "严肃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "严肃了", "label": "体标"}, {"form": "严肃性", "label": "复合"}, {"form": "嚴肅", "label": "繁体"}], "register": "中性", "sense_fingerprint": "气氛、话题、态度庄重认真，不随便", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59765317-1277-4541-a33b-efb6288b49af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严肃", "is_correct": true, "explanation": "正确：“严肃”指气氛庄重认真，与“会议室里的气氛很严肃”相合。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指场面红火、有人说笑，与“没有人笑”相矛盾。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：“欢乐”指快乐的气氛，与“没有人笑”相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或建筑的体形，不用来形容“气氛”。"}], "explanations": {"严肃": "正确：“严肃”指气氛庄重认真，与“会议室里的气氛很严肃”相合。", "热闹": "语义：“热闹”指场面红火、有人说笑，与“没有人笑”相矛盾。", "欢乐": "语义：“欢乐”指快乐的气氛，与“没有人笑”相矛盾。", "高大": "搭配：“高大”形容人或建筑的体形，不用来形容“气氛”。"}, "sentence_index": 0, "correct_answer": "严肃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的伤势很严肃，医生让他马上住院。", "explanation": "这里应该用〈严重〉。严重指程度深、情况危险，伤势要用严重；严肃指人的神情或气氛庄重。"}, {"text": "这道菜的味道很严肃，大家都夸好吃。", "explanation": "这里应该用〈鲜美〉。鲜美指味道鲜、好吃，形容食物；严肃指神情或气氛庄重认真，不能形容味道。"}, {"text": "这盏灯的光线很严肃，大家都很喜欢。", "explanation": "这里应该用〈柔和〉。柔和指光线不刺眼、温和，形容光线；严肃指神情或气氛庄重认真，不能形容光线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严肃", "is_correct": true, "explanation": "正确：“严肃”指气氛庄重认真，与“没有人大声说话”的场面相合。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”指声音大、场面乱，与“没有人大声说话”相矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”指声音杂乱，与“没有人大声说话”相矛盾。"}, {"text": "闹哄哄", "is_correct": false, "explanation": "语域：“闹哄哄”口语色彩较重，不用于法院这样庄重的场合，且与“没有人大声说话”相矛盾。"}], "explanations": {"严肃": "正确：“严肃”指气氛庄重认真，与“没有人大声说话”的场面相合。", "吵闹": "语义：“吵闹”指声音大、场面乱，与“没有人大声说话”相矛盾。", "嘈杂": "语义：“嘈杂”指声音杂乱，与“没有人大声说话”相矛盾。", "闹哄哄": "语域：“闹哄哄”口语色彩较重，不用于法院这样庄重的场合，且与“没有人大声说话”相矛盾。"}, "sentence_index": 6, "correct_answer": "严肃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的冬天很严肃，大家都不愿意出门。", "explanation": "这里应该用〈严寒〉。严寒指气温极低，天气要用严寒；严肃指人的神情或气氛庄重。"}, {"text": "这个小区的防守很严肃，外人根本进不去。", "explanation": "这里应该用〈严密〉。严密指周密、不留空隙，防守要用严密；严肃不用于描述防守。"}, {"text": "这家餐厅的卫生标准很严肃，大家都很放心。", "explanation": "这里应该用〈严格〉。严格指标准、规定要求高；严肃指神情或气氛庄重，不用于标准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次的问题我们必须严肃得对待。", "corrected_sentence": "这次的问题我们必须严肃对待。", "error_description": "结构助词错误：“严肃”作状语修饰动词“对待”时，可直接说“严肃对待”，此处不能用“得”。错误形式：严肃得对待；正确形式：严肃对待。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她严肃的问了我一个问题。", "corrected_sentence": "她严肃地问了我一个问题。", "error_description": "结构助词错误：“严肃”修饰动词“问”、作状语时应用“地”，说“严肃地问”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
