INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93377, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "隧道是在山里或地下挖出来的长路。", "primary_collocate": null, "pronunciation": "suì dào", "ipa": "swei˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "开车进隧道前，请先打开车灯。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条隧道把两座山连在了一起。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在山里挖了一年才挖通隧道。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隧道里很安静，只听见车声。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我最怕坐车穿过隧道。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从隧道出来，天一下子亮了。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是全国最长的公路隧道。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隧道太长，里面不能停车。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了隧道，翻山不用再走一个小时。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着手电筒走进了黑黑的隧道。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "公路隧道", "label": "复合"}, {"form": "隧道口", "label": "复合"}], "register": "中性", "sense_fingerprint": "山里或地下挖出来的长路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e49e6890-ab2b-4fe2-b804-aada486c92c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93377, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隧道", "is_correct": true, "explanation": "隧道指山里或地下挖出来的长路，即目标词。"}, {"text": "随到", "is_correct": false, "explanation": "suí（第二声）与 suì（第四声）声母韵母相同，只差声调，意思是随到。"}, {"text": "睡到", "is_correct": false, "explanation": "shuì 与 suì 声母不同（sh 与 s），声调相同，意思是睡到。"}, {"text": "醉到", "is_correct": false, "explanation": "zuì 与 suì 声母不同（z 与 s），声调相同，意思是醉到。"}], "explanations": {"隧道": "隧道指山里或地下挖出来的长路，即目标词。", "随到": "suí（第二声）与 suì（第四声）声母韵母相同，只差声调，意思是随到。", "睡到": "shuì 与 suì 声母不同（sh 与 s），声调相同，意思是睡到。", "醉到": "zuì 与 suì 声母不同（z 与 s），声调相同，意思是醉到。"}, "sentence_index": null, "correct_answer": "隧道"}, "level_3": {"options": [{"text": "隧道", "is_correct": true, "explanation": "隧道是山里或地下挖出的长路，开车可以驶入，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是开车能驶入的地方，句子不通。"}, {"text": "石头", "is_correct": false, "explanation": "配价：「进」要求可以进入的处所，石头不能作为「进」的处所宾语。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影不是可以开车驶入的地方，句子不通。"}], "explanations": {"隧道": "隧道是山里或地下挖出的长路，开车可以驶入，符合句意。", "厨房": "语义：厨房不是开车能驶入的地方，句子不通。", "石头": "配价：「进」要求可以进入的处所，石头不能作为「进」的处所宾语。", "电影": "语义：电影不是可以开车驶入的地方，句子不通。"}, "sentence_index": 0, "correct_answer": "隧道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条隧道很重，我们推了好久。", "explanation": "这里应该用〈大门〉。隧道是固定的长路，不能像大门一样被推动。"}, {"text": "我每天坐隧道上班。", "explanation": "这里应该用〈地铁〉。隧道是通道，本身不是交通工具，不能说「坐隧道」。"}, {"text": "汽车在山路上快速地跑，隧道也在山路上快速地跑。", "explanation": "这里应该用〈车辆〉。隧道是固定的长路，不会跑，不能说「快速地跑」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隧道", "is_correct": true, "explanation": "「公路隧道」是固定说法，指公路上穿过山体的通道，符合句意。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不是公路设施，与「全国最长的公路」不搭。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「公路」修饰的名词须是道路或交通设施，「公路窗户」不能成立。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是公路，「全国最长的公路饭」句子不通。"}], "explanations": {"隧道": "「公路隧道」是固定说法，指公路上穿过山体的通道，符合句意。", "鱼": "语义：鱼不是公路设施，与「全国最长的公路」不搭。", "窗户": "搭配：「公路」修饰的名词须是道路或交通设施，「公路窗户」不能成立。", "饭": "语义：饭不是公路，「全国最长的公路饭」句子不通。"}, "sentence_index": 6, "correct_answer": "隧道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们爬上了这座隧道，看见了大海。", "explanation": "这里应该用〈山〉。隧道是穿过山体或地下的通道，不能「爬上」，人爬上的是山。"}, {"text": "飞机在天上飞，隧道在天上飞。", "explanation": "这里应该用〈鸟〉。隧道是固定在山里或地下的长路，不会在天上飞。"}, {"text": "这条隧道很甜，大家都尝了一口。", "explanation": "这里应该用〈食物〉。隧道是通道，不能被尝，也没有味道，只有食物才能说「甜」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们在山里挖了一头隧道。", "corrected_sentence": "工人们在山里挖了一条隧道。", "error_description": "隧道应用量词「条」，「头」用于大型牲畜，这里把「条」错成「头」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只隧道是去年才挖好的。", "corrected_sentence": "那条隧道是去年才挖好的。", "error_description": "「只」用于动物，隧道应用量词「条」，这里把「条」错成「只」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
