INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93387, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93387, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鱼类是生活在水里、用鳃呼吸的一大类动物。", "primary_collocate": null, "pronunciation": "yú lèi", "ipa": "y˧˥ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "鲨鱼和金鱼都是鱼类。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼类生活在水里，用鳃呼吸。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片海里有很多种鱼类。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员正在调查鱼类的迁徙路线。", "target_word": "鱼类", "complexity_tier": "T3", "furigana": "yán jiū rén yuán zhèng zài diào chá yú lèi de qiān xǐ lù xiàn", "sentence_source": "generated"}, {"text": "鱼类需要干净的水才能活下去。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水脏了，鱼类越来越少。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位科学家研究海里的鱼类。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼类和鸟类都是动物。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民每天把捕到的鱼类运到市场。", "target_word": "鱼类", "complexity_tier": "T3", "furigana": "yú mín měi tiān bǎ bǔ dào de yú lèi yùn dào shì chǎng", "sentence_source": "generated"}, {"text": "鱼类的身上有鳍，可以在水里游。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "魚類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生活在水里、用鳃呼吸的一大类动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鱼类", "is_correct": true, "explanation": "“鱼类”指生活在水里、用鳃呼吸的一大类动物，鲨鱼和金鱼都属于这一类，句意成立。"}, {"text": "鸟类", "is_correct": false, "explanation": "语义：鲨鱼和金鱼都不是鸟类，“都是鸟类”与事实不符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：鲨鱼和金鱼都是动物，不属于植物。"}, {"text": "鱼群", "is_correct": false, "explanation": "搭配：“鱼群”指一群游动的鱼，不是分类名称，不能用“都是……”来归类。"}], "explanations": {"鱼类": "“鱼类”指生活在水里、用鳃呼吸的一大类动物，鲨鱼和金鱼都属于这一类，句意成立。", "鸟类": "语义：鲨鱼和金鱼都不是鸟类，“都是鸟类”与事实不符。", "植物": "语义：鲨鱼和金鱼都是动物，不属于植物。", "鱼群": "搭配：“鱼群”指一群游动的鱼，不是分类名称，不能用“都是……”来归类。"}, "sentence_index": 0, "correct_answer": "鱼类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今晚想吃一盘鱼类。", "explanation": "这里应该用〈鱼肉〉。“鱼类”指动物的大类，做好的菜要说“鱼肉”。"}, {"text": "我在河边钓到了一条鱼类。", "explanation": "这里量词应该用〈种〉。“鱼类”是类别名称，计量要用“种”，不能用“条”。"}, {"text": "他在河边随手拿起鱼类当枕头。", "explanation": "这里应该用〈石块〉。“鱼类”是动物的类别名称，不是具体的物件，不能拿来当枕头；当枕头的应是石块之类的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鱼类", "is_correct": true, "explanation": "“鱼类”指海里生活的一大类动物，与“研究”的对象相合。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫是陆地上的动物，海里没有猫，句子不成立。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是生物，科学家不会研究海里的汽车。"}, {"text": "汉字", "is_correct": false, "explanation": "语义：汉字是书写符号，不存在于海里，句子不成立。"}], "explanations": {"鱼类": "“鱼类”指海里生活的一大类动物，与“研究”的对象相合。", "猫": "语义：猫是陆地上的动物，海里没有猫，句子不成立。", "汽车": "语义：汽车不是生物，科学家不会研究海里的汽车。", "汉字": "语义：汉字是书写符号，不存在于海里，句子不成立。"}, "sentence_index": 6, "correct_answer": "鱼类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈煮了一锅鱼类，全家都吃得很开心。", "explanation": "这里应该用〈鱼汤〉。“鱼类”指动物类别，煮好的汤不能说成“鱼类”。"}, {"text": "我把新养的小狗取名叫鱼类。", "explanation": "这里应该用〈小白〉这类名字。“鱼类”是动物的分类名称，不能拿来当某一只动物的名字。"}, {"text": "他的手被鱼类扎破了。", "explanation": "这里应该用〈鱼刺〉。“鱼类”是动物大类，扎破手的是鱼身上的“鱼刺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池塘里养着几只鱼类。", "corrected_sentence": "池塘里养着几种鱼类。", "error_description": "量词错误：“鱼类”是类别名词，计量应用“种”，不能用“只”。应改为“几种鱼类”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河里的鱼类们都很好看。", "corrected_sentence": "这条河里的鱼类都很好看。", "error_description": "后缀错误：“们”一般只加在指人的名词后，“鱼类”不能加“们”。应去掉“们”，改为“鱼类都……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
