INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93388, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93388, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生活在水中、用鳃呼吸、以鳍游动的脊椎动物的总称。", "primary_collocate": null, "pronunciation": "yú lèi", "ipa": "y˧˥ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "鱼类是脊椎动物中的一大类。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼类用鳍在水中游动。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海洋里的鱼类比河里的多。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了不同鱼类的图片。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水温太高时，很多鱼类会死去。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了一百多种鱼类。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼类大多生活在水里，用鳃呼吸。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海边工作，专门保护鱼类。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼类的身体里有一根长长的脊骨。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水干净了，回来的鱼类多了。", "target_word": "鱼类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "魚類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用鳃呼吸、以鳍游动的脊椎动物总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鱼类", "is_correct": true, "explanation": "“鱼类”是脊椎动物中的一大类，与句意相合。"}, {"text": "昆虫", "is_correct": false, "explanation": "语义：昆虫属于无脊椎动物，不属于脊椎动物。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不是动物，不能归入脊椎动物。"}, {"text": "鱼群", "is_correct": false, "explanation": "搭配：“鱼群”指一群鱼，不是分类单位，不能说“是……中的一大类”。"}], "explanations": {"鱼类": "“鱼类”是脊椎动物中的一大类，与句意相合。", "昆虫": "语义：昆虫属于无脊椎动物，不属于脊椎动物。", "植物": "语义：植物不是动物，不能归入脊椎动物。", "鱼群": "搭配：“鱼群”指一群鱼，不是分类单位，不能说“是……中的一大类”。"}, "sentence_index": 0, "correct_answer": "鱼类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师给我们看了一条鱼类的图片。", "explanation": "这里量词应该用〈种〉。“鱼类”是类别，计量用“种”，不用“条”。"}, {"text": "他一生气，就拿起鱼类往门上扔。", "explanation": "这里应该用〈石块〉。“鱼类”是动物的类别名称，不是具体的物件，不能拿起来扔；能扔的应是石块之类的东西。"}, {"text": "老师给我们看了一棵鱼类的图片。", "explanation": "这里量词应该用〈种〉。“棵”用于树木、植株，“鱼类”是类别名称，要用“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鱼类", "is_correct": true, "explanation": "“鱼类”大多生活在水里并用鳃呼吸，与句意相合。"}, {"text": "鸟类", "is_correct": false, "explanation": "语义：鸟类大多不在水里生活，与句意不符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物一般不在水里“生活”着游动，与句意不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“生活”的主语须是生物，“石头”不能说“生活在水里”。"}], "explanations": {"鱼类": "“鱼类”大多生活在水里并用鳃呼吸，与句意相合。", "鸟类": "语义：鸟类大多不在水里生活，与句意不符。", "植物": "语义：植物一般不在水里“生活”着游动，与句意不符。", "石头": "搭配：“生活”的主语须是生物，“石头”不能说“生活在水里”。"}, "sentence_index": 6, "correct_answer": "鱼类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "餐厅端上了一盘鱼类，客人很满意。", "explanation": "这里应该用〈鱼肉〉。“鱼类”指动物类别，端上桌的菜要说“鱼肉”。"}, {"text": "我们班新来的同学叫鱼类。", "explanation": "这里应该用〈小芳〉这类人名。“鱼类”是动物的分类名称，不能用作人名。"}, {"text": "他用鱼类钓鱼，结果什么也没钓到。", "explanation": "这里应该用〈鱼饵〉。“鱼类”是动物大类，钓鱼时用来引诱鱼的是“鱼饵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个鱼类用鳍在水中游动。", "corrected_sentence": "很多鱼类用鳍在水中游动。", "error_description": "数量词错误：“鱼类”是类别名词，不能用个体量词“一个”计数，应说“很多鱼类”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "池塘里的鱼类们很多。", "corrected_sentence": "池塘里的鱼类很多。", "error_description": "后缀错误：“们”一般只加在指人的名词后，“鱼类”不能加“们”。应去掉“们”，改为“鱼类很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93389, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "胆小", "is_correct": true, "explanation": "“胆小”与“大胆”是反义词，指不敢做事，与“别人都不敢，她却大胆地举起了手”的对比相反。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指头脑灵活，与“大胆”没有反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”指心地好，与“大胆”不构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指不吵闹，与“大胆”没有反义关系。"}], "correct_answer": "胆小", "explanations": {"胆小": "“胆小”与“大胆”是反义词，指不敢做事，与“别人都不敢，她却大胆地举起了手”的对比相反。", "聪明": "“聪明”指头脑灵活，与“大胆”没有反义关系。", "善良": "“善良”指心地好，与“大胆”不构成反义。", "安静": "“安静”指不吵闹，与“大胆”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93389, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "胆小", "is_correct": true, "explanation": "“胆小”与“大胆”是反义词，指不敢做事，与这个小偷敢于进屋的胆量相反。"}, {"text": "诚实", "is_correct": false, "explanation": "“诚实”指不说谎，与“大胆”没有反义关系。"}, {"text": "勤劳", "is_correct": false, "explanation": "“勤劳”指肯干活，与“大胆”不构成反义。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”指做事专心，与“大胆”没有反义关系。"}], "correct_answer": "胆小", "explanations": {"胆小": "“胆小”与“大胆”是反义词，指不敢做事，与这个小偷敢于进屋的胆量相反。", "诚实": "“诚实”指不说谎，与“大胆”没有反义关系。", "勤劳": "“勤劳”指肯干活，与“大胆”不构成反义。", "认真": "“认真”指做事专心，与“大胆”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93389, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大胆是什么都不怕，敢去做。", "primary_collocate": null, "pronunciation": "dà dǎn", "ipa": "ta˥˩ tan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他很大胆，一个人去山里住了三天。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明很大胆，敢和大狗一起玩。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子真大胆，一个人就敢上台唱歌。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人都不敢，她却大胆地举起了手。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真大胆，竟然敢一个人走夜路！", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟很大胆，晚上不开灯也不怕黑。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大胆地走进了那间没人敢进的屋子。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就大胆，爬树、下河都不怕。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不太大胆，所以不敢一个人坐飞机。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个大胆的小偷，白天就敢进别人家。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大胆地", "label": "状语形式"}, {"form": "大膽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "什么都不怕、敢去做的人或行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a469138-6fb8-45ff-8b3c-19ee085e4330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93389, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大胆", "is_correct": true, "explanation": "大胆（dà dǎn）指什么都不怕、敢去做，是听到的目标词。"}, {"text": "大单", "is_correct": false, "explanation": "dān（第一声）与 dǎn（第三声）声调不同，意思是大额订单。"}, {"text": "大难", "is_correct": false, "explanation": "nàn（第四声）与 dǎn（第三声）声母不同，声调也不同，意思是重大的灾难。"}, {"text": "大党", "is_correct": false, "explanation": "dǎng 与 dǎn 韵尾不同（ng 与 n），意思是大的政党。"}, {"text": "打蛋", "is_correct": false, "explanation": "dǎ dàn 两个音节的声调都与 dà dǎn 不同，意思是打鸡蛋。"}], "explanations": {"大胆": "大胆（dà dǎn）指什么都不怕、敢去做，是听到的目标词。", "大单": "dān（第一声）与 dǎn（第三声）声调不同，意思是大额订单。", "大难": "nàn（第四声）与 dǎn（第三声）声母不同，声调也不同，意思是重大的灾难。", "大党": "dǎng 与 dǎn 韵尾不同（ng 与 n），意思是大的政党。", "打蛋": "dǎ dàn 两个音节的声调都与 dà dǎn 不同，意思是打鸡蛋。"}, "sentence_index": null, "correct_answer": "大胆"}, "level_3": {"options": [{"text": "大胆", "is_correct": true, "explanation": "“大胆”形容敢做、不怕事，与“一个人去山里住了三天”相符。"}, {"text": "胆小", "is_correct": false, "explanation": "语义：“胆小”指害怕，与“一个人去山里住了三天”的行为相矛盾。"}, {"text": "懦弱", "is_correct": false, "explanation": "语义：“懦弱”指缺乏勇气，与“一个人去山里住了三天”不相符。"}, {"text": "怯懦", "is_correct": false, "explanation": "语域：“怯懦”偏书面，口语叙述中很少这样说，且与“一个人去山里住了三天”的勇敢不合。"}], "explanations": {"大胆": "“大胆”形容敢做、不怕事，与“一个人去山里住了三天”相符。", "胆小": "语义：“胆小”指害怕，与“一个人去山里住了三天”的行为相矛盾。", "懦弱": "语义：“懦弱”指缺乏勇气，与“一个人去山里住了三天”不相符。", "怯懦": "语域：“怯懦”偏书面，口语叙述中很少这样说，且与“一个人去山里住了三天”的勇敢不合。"}, "sentence_index": 0, "correct_answer": "大胆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她很大胆，常常请朋友吃饭，从不计较花了多少钱。", "explanation": "这里应该用〈大方〉。大胆指敢做、不畏惧；形容慷慨、不计较钱财要用大方。"}, {"text": "他很大胆，作业里写错了三个字都没有发现。", "explanation": "这里应该用〈粗心〉。大胆指敢做、不畏惧，不指做事不仔细，这里要用粗心。"}, {"text": "他很大胆，天一黑就躲在被子里哭个不停。", "explanation": "这里应该用〈害怕〉。大胆指敢做、不畏惧，与“躲在被子里哭”的状态正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93389, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大胆", "is_correct": true, "explanation": "大胆（dà dǎn）指什么都不怕、敢去做，是听到的目标词。"}, {"text": "大喊", "is_correct": false, "explanation": "hǎn（第三声）与 dǎn 声母不同（h 与 d），意思是大声喊叫。"}, {"text": "大伞", "is_correct": false, "explanation": "sǎn（第三声）与 dǎn 声母不同（s 与 d），意思是大号的伞。"}, {"text": "大板", "is_correct": false, "explanation": "bǎn（第三声）与 dǎn 声母不同（b 与 d），意思是大木板。"}, {"text": "大岛", "is_correct": false, "explanation": "dǎo（第三声）与 dǎn 韵尾不同（o 与 n），意思是大岛屿。"}], "explanations": {"大胆": "大胆（dà dǎn）指什么都不怕、敢去做，是听到的目标词。", "大喊": "hǎn（第三声）与 dǎn 声母不同（h 与 d），意思是大声喊叫。", "大伞": "sǎn（第三声）与 dǎn 声母不同（s 与 d），意思是大号的伞。", "大板": "bǎn（第三声）与 dǎn 声母不同（b 与 d），意思是大木板。", "大岛": "dǎo（第三声）与 dǎn 韵尾不同（o 与 n），意思是大岛屿。"}, "sentence_index": null, "correct_answer": "大胆"}, "level_3": {"options": [{"text": "大胆", "is_correct": true, "explanation": "“大胆”形容敢做、不畏惧，与“没人敢进的屋子”所描绘的情境相符。"}, {"text": "畏缩", "is_correct": false, "explanation": "语义：“畏缩”指因害怕而退缩，与“主动走进没人敢进的屋子”的行为相矛盾。"}, {"text": "慌张", "is_correct": false, "explanation": "语义：“慌张”指心慌失措，与“主动走进没人敢进的屋子”所体现的从容勇气不符。"}, {"text": "害怕", "is_correct": false, "explanation": "语义：“害怕”指心中畏惧，与“走进没人敢进的屋子”的行为相矛盾。"}], "explanations": {"大胆": "“大胆”形容敢做、不畏惧，与“没人敢进的屋子”所描绘的情境相符。", "畏缩": "语义：“畏缩”指因害怕而退缩，与“主动走进没人敢进的屋子”的行为相矛盾。", "慌张": "语义：“慌张”指心慌失措，与“主动走进没人敢进的屋子”所体现的从容勇气不符。", "害怕": "语义：“害怕”指心中畏惧，与“走进没人敢进的屋子”的行为相矛盾。"}, "sentence_index": 6, "correct_answer": "大胆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很大胆，从不计较别人的错误。", "explanation": "这里应该用〈大度〉。大胆指敢做、不畏惧；形容宽容、不计较要用大度。"}, {"text": "他很大胆，从不炫耀自己的成绩。", "explanation": "这里应该用〈谦虚〉。大胆指敢做、不畏惧，不指待人谦逊、不张扬。"}, {"text": "他很大胆，过马路时东张西望，不敢走快。", "explanation": "这里应该用〈胆怯〉。大胆指敢做、不畏惧，与“不敢走快”的畏缩相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是个大胆地人，独自走进了山洞。", "corrected_sentence": "他是个大胆的人，独自走进了山洞。", "error_description": "“大胆”修饰名词“人”时要用“的”，“地”只用于修饰动词，应说“大胆的人”，不能说“大胆地人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位大胆地探险家第一个爬上了山顶。", "corrected_sentence": "这位大胆的探险家第一个爬上了山顶。", "error_description": "“大胆”修饰名词“探险家”时要用“的”，“地”只用于修饰动词，应说“大胆的探险家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93390, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保守", "is_correct": true, "explanation": "“保守”与“大胆”（敢想敢做的决定）是反义词，指不敢冒险、只求稳妥，与“老板大胆用年轻人”相反。"}, {"text": "诚实", "is_correct": false, "explanation": "“诚实”指不说谎，与“大胆”没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”指做事专心，与“大胆”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”指待人亲切，与“大胆”没有反义关系。"}], "correct_answer": "保守", "explanations": {"保守": "“保守”与“大胆”（敢想敢做的决定）是反义词，指不敢冒险、只求稳妥，与“老板大胆用年轻人”相反。", "诚实": "“诚实”指不说谎，与“大胆”没有反义关系。", "认真": "“认真”指做事专心，与“大胆”没有反义关系。", "热情": "“热情”指待人亲切，与“大胆”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93390, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保守", "is_correct": true, "explanation": "“保守”与“大胆”（敢做敢为的做法）是反义词，指不愿冒险、墨守成规，与“什么新东西都想试”相反。"}, {"text": "勤劳", "is_correct": false, "explanation": "“勤劳”指肯干活，与“大胆”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指头脑灵活，与“大胆”没有反义关系。"}, {"text": "活泼", "is_correct": false, "explanation": "“活泼”指性情开朗、爱动，与“大胆”没有反义关系。"}], "correct_answer": "保守", "explanations": {"保守": "“保守”与“大胆”（敢做敢为的做法）是反义词，指不愿冒险、墨守成规，与“什么新东西都想试”相反。", "勤劳": "“勤劳”指肯干活，与“大胆”没有反义关系。", "聪明": "“聪明”指头脑灵活，与“大胆”没有反义关系。", "活泼": "“活泼”指性情开朗、爱动，与“大胆”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93390, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "胆量大，敢做敢为，不畏惧。", "primary_collocate": null, "pronunciation": "dà dǎn", "ipa": "ta˥˩ tan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个想法很大胆，以前没人敢这样做。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做了一个大胆的决定，辞职去开店。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大胆地在会上提出了一个新方案。", "target_word": "大胆", "complexity_tier": "T3", "furigana": "dà dǎn", "sentence_source": "generated"}, {"text": "老板大胆用年轻人，公司越来越好。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要大胆尝试，不要怕错。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的做法很大胆，让大家都吃了一惊。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大胆地说出了自己的看法。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位大胆的设计师把花园建在了屋顶上。", "target_word": "大胆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大胆提问，老师不会生气。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年轻时的做法很大胆，什么新东西都想试。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大胆地", "label": "状语形式"}, {"form": "大膽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "胆量大、敢做敢为的想法、决定或做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a469138-6fb8-45ff-8b3c-19ee085e4330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93390, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大胆", "is_correct": true, "explanation": "大胆（dà dǎn）指胆量大、敢做敢为，是听到的目标词。"}, {"text": "大单", "is_correct": false, "explanation": "dān（第一声）与 dǎn（第三声）声调不同，意思是大额订单。"}, {"text": "大难", "is_correct": false, "explanation": "nàn（第四声）与 dǎn（第三声）声母不同，声调也不同，意思是重大的灾难。"}, {"text": "大党", "is_correct": false, "explanation": "dǎng 与 dǎn 韵尾不同（ng 与 n），意思是大的政党。"}, {"text": "大岛", "is_correct": false, "explanation": "dǎo（第三声）与 dǎn 韵尾不同（o 与 n），意思是大岛屿。"}], "explanations": {"大胆": "大胆（dà dǎn）指胆量大、敢做敢为，是听到的目标词。", "大单": "dān（第一声）与 dǎn（第三声）声调不同，意思是大额订单。", "大难": "nàn（第四声）与 dǎn（第三声）声母不同，声调也不同，意思是重大的灾难。", "大党": "dǎng 与 dǎn 韵尾不同（ng 与 n），意思是大的政党。", "大岛": "dǎo（第三声）与 dǎn 韵尾不同（o 与 n），意思是大岛屿。"}, "sentence_index": null, "correct_answer": "大胆"}, "level_3": {"options": [{"text": "大胆", "is_correct": true, "explanation": "“大胆”形容想法敢于突破，与“以前没人敢这样做”相符。"}, {"text": "普通", "is_correct": false, "explanation": "语义：“普通”指平常，与“以前没人敢这样做”的新奇相矛盾。"}, {"text": "寻常", "is_correct": false, "explanation": "语域：“寻常”偏书面，口语中很少这样形容想法，且与“以前没人敢这样做”的含义相反。"}, {"text": "稳妥", "is_correct": false, "explanation": "语义：“稳妥”指不冒险，与“以前没人敢这样做”所说的敢于突破相反。"}], "explanations": {"大胆": "“大胆”形容想法敢于突破，与“以前没人敢这样做”相符。", "普通": "语义：“普通”指平常，与“以前没人敢这样做”的新奇相矛盾。", "寻常": "语域：“寻常”偏书面，口语中很少这样形容想法，且与“以前没人敢这样做”的含义相反。", "稳妥": "语义：“稳妥”指不冒险，与“以前没人敢这样做”所说的敢于突破相反。"}, "sentence_index": 0, "correct_answer": "大胆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老板很大胆，每次进货都要先请示上级，不敢拿主意。", "explanation": "这里应该用〈犹豫〉。大胆指敢做、敢拿主意，与“不敢拿主意”相矛盾。"}, {"text": "他很大胆，整天躺在床上，什么事都不愿做。", "explanation": "这里应该用〈懒惰〉。大胆指敢做、不畏惧，不指不愿动。"}, {"text": "这个孩子很大胆，见了生人就脸红。", "explanation": "这里应该用〈害羞〉。大胆指敢做、不畏惧，不指怕生、脸红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93390, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大胆", "is_correct": true, "explanation": "大胆（dà dǎn）指胆量大、敢做敢为，是听到的目标词。"}, {"text": "大喊", "is_correct": false, "explanation": "hǎn（第三声）与 dǎn 声母不同（h 与 d），意思是大声喊叫。"}, {"text": "大伞", "is_correct": false, "explanation": "sǎn（第三声）与 dǎn 声母不同（s 与 d），意思是大号的伞。"}, {"text": "大板", "is_correct": false, "explanation": "bǎn（第三声）与 dǎn 声母不同（b 与 d），意思是大木板。"}, {"text": "打蛋", "is_correct": false, "explanation": "dǎ dàn 两个音节的声调都与 dà dǎn 不同，意思是打鸡蛋。"}], "explanations": {"大胆": "大胆（dà dǎn）指胆量大、敢做敢为，是听到的目标词。", "大喊": "hǎn（第三声）与 dǎn 声母不同（h 与 d），意思是大声喊叫。", "大伞": "sǎn（第三声）与 dǎn 声母不同（s 与 d），意思是大号的伞。", "大板": "bǎn（第三声）与 dǎn 声母不同（b 与 d），意思是大木板。", "打蛋": "dǎ dàn 两个音节的声调都与 dà dǎn 不同，意思是打鸡蛋。"}, "sentence_index": null, "correct_answer": "大胆"}, "level_3": {"options": [{"text": "大胆", "is_correct": true, "explanation": "“大胆”形容敢做、不畏惧，与“她……说出了自己的看法”的敢于表达相符。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不说话，与“说出了自己的看法”相矛盾。"}, {"text": "唯唯诺诺", "is_correct": false, "explanation": "语域：“唯唯诺诺”偏书面，且形容顺从、不敢表态，与“说出了自己的看法”不合。"}, {"text": "不敢", "is_correct": false, "explanation": "搭配：“不敢地说出”不通，且与“说出了自己的看法”的敢言相反。"}], "explanations": {"大胆": "“大胆”形容敢做、不畏惧，与“她……说出了自己的看法”的敢于表达相符。", "沉默": "语义：“沉默”指不说话，与“说出了自己的看法”相矛盾。", "唯唯诺诺": "语域：“唯唯诺诺”偏书面，且形容顺从、不敢表态，与“说出了自己的看法”不合。", "不敢": "搭配：“不敢地说出”不通，且与“说出了自己的看法”的敢言相反。"}, "sentence_index": 6, "correct_answer": "大胆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很大胆，见了生人就躲到妈妈身后。", "explanation": "这里应该用〈害羞〉。大胆指敢做、不畏惧，与“躲到妈妈身后”的怕生正相反。"}, {"text": "他很大胆，一见大场面就发抖。", "explanation": "这里应该用〈胆怯〉。大胆指敢做、不畏惧，与“发抖”的怯场状态正相反。"}, {"text": "他很大胆，每次走夜路都要拉着同伴的手。", "explanation": "这里应该用〈依赖〉。大胆指敢做、不畏惧，不指事事都要靠别人陪着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (