INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93393, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女朋友是小孩子之间关系亲近、常一起玩的某个女生朋友，不指恋爱对象。", "primary_collocate": null, "pronunciation": "nǚ péng you", "ipa": "ny˨˩˦ pʰɤŋ˧˥ joʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "小明常常和女朋友一起玩游戏。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的女朋友很爱笑。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着女朋友去公园玩。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的女朋友喜欢和我一起打球。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天放学都和女朋友一起走。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的女朋友是我们班的同学。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，他又去找女朋友玩。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的女朋友唱歌很好听。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给女朋友看了自己的新自行车。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想让大家认识他的女朋友，她是我们的好朋友。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "女友", "label": "简称"}], "register": "口语", "sense_fingerprint": "女朋友：小孩之间关系亲近、常一起玩的女生朋友（非恋爱）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df811bf5-9274-44e9-838a-6aef24dd96b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会玩游戏，“和桌子一起玩游戏”与语境不合。"}, {"text": "女朋友", "is_correct": true, "explanation": "女朋友是男生常一起玩的女生，与小明一起玩游戏，语义通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能和人一起玩游戏。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“一起玩”的对象应是人，闹钟不能这样使用。"}], "explanations": {"桌子": "语义：桌子不会玩游戏，“和桌子一起玩游戏”与语境不合。", "女朋友": "女朋友是男生常一起玩的女生，与小明一起玩游戏，语义通顺。", "石头": "语义：石头不能和人一起玩游戏。", "闹钟": "搭配：“一起玩”的对象应是人，闹钟不能这样使用。"}, "sentence_index": 0, "correct_answer": "女朋友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的女朋友是个男生，常和我一起打球。", "explanation": "这里应该用〈男孩〉。“女朋友”指女生，不能用来指男性。"}, {"text": "班里的女朋友都很用功。", "explanation": "这里应该用〈女同学〉。“女朋友”指关系亲近、常一起玩的某个女生朋友，不能泛指全班的女生。"}, {"text": "我有一块女朋友，常和我一起打球。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，不能修饰人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能被找去一起玩。"}, {"text": "女朋友", "is_correct": true, "explanation": "女朋友是男生常一起玩的女生，下课后去找她玩，语义通顺。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵是天上的水汽，不能被找去玩。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：“找……玩”的对象应是人或宠物，“黑板”不能这样使用。"}], "explanations": {"太阳": "语义：太阳是天体，不能被找去一起玩。", "女朋友": "女朋友是男生常一起玩的女生，下课后去找她玩，语义通顺。", "云朵": "语义：云朵是天上的水汽，不能被找去玩。", "黑板": "搭配：“找……玩”的对象应是人或宠物，“黑板”不能这样使用。"}, "sentence_index": 6, "correct_answer": "女朋友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈是我的女朋友，每天陪我玩。", "explanation": "这里应该用〈母亲〉。“女朋友”指同龄、常一起玩的女生，不能指母亲。"}, {"text": "他有一条女朋友，常和他一起玩。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不能修饰人。"}, {"text": "我们班的女朋友都很友好。", "explanation": "这里应该用〈女孩〉。本义的“女朋友”指特定的、常一起玩的女生，不能泛指班里所有女孩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只女朋友，常常和我一起打球。", "corrected_sentence": "我有一个女朋友，常常和我一起打球。", "error_description": "量词错误：“女朋友”前应用〈个〉，“只”用于动物或成对器官中的一个，不能修饰人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一台女朋友，常常一起玩。", "corrected_sentence": "他有一位女朋友，常常一起玩。", "error_description": "量词错误：“女朋友”前应用〈位〉或〈个〉，“台”用于机器等器械，不能修饰人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
