INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93395, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一堆是很多东西放在一起，堆得高高的。", "primary_collocate": null, "pronunciation": "yì duī", "ipa": "i˥˩ tweɪ˥", "syllable_count": 2, "sentences": [{"text": "桌子上有一堆书。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里有一堆黄色的叶子。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的沙滩上有一堆贝壳，是孩子们捡来的。", "target_word": "一堆", "complexity_tier": "T3", "furigana": "hǎi biān de shā tān shàng yǒu yì duī bèi ké, shì hái zi men jiǎn lái de", "sentence_source": "generated"}, {"text": "房间角落里放着一堆旧衣服。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的床上有一堆脏衣服。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下有一堆大石头。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边有一堆雪，是昨天扫出来的。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我面前有一堆作业要写。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房门口有一堆垃圾，很臭。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一堆木头搬到了车上。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一大堆", "label": "复合"}], "register": "中性", "sense_fingerprint": "放在一起、堆得高高的很多东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93395, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一堆", "is_correct": true, "explanation": "“一堆”指堆积在一起的很多东西，桌子上堆着的书正是这样，句意成立。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、房屋等大型固定物体，书不能用“座”来计量。"}, {"text": "一片", "is_correct": false, "explanation": "搭配：“片”指扁平、成片的东西，堆在桌上的书不能用“片”计量。"}, {"text": "一场", "is_correct": false, "explanation": "语义：“场”用于一段活动或事件，“一场书”说不通。"}], "explanations": {"一堆": "“一堆”指堆积在一起的很多东西，桌子上堆着的书正是这样，句意成立。", "一座": "搭配：“座”用于山、房屋等大型固定物体，书不能用“座”来计量。", "一片": "搭配：“片”指扁平、成片的东西，堆在桌上的书不能用“片”计量。", "一场": "语义：“场”用于一段活动或事件，“一场书”说不通。"}, "sentence_index": 0, "correct_answer": "一堆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他骑着一堆自行车去上学。", "explanation": "这里应该用〈一辆〉。“一堆”指堆在一起的很多东西，骑车一次只能骑一辆，要说“一辆”。"}, {"text": "公园里有一堆湖。", "explanation": "这里应该用〈一片〉。“一堆”指堆积在一起的东西，湖是平铺的水面，要说“一片湖”。"}, {"text": "他坐在一堆沙发上看电视。", "explanation": "这里应该用〈一张〉。“一堆”指堆在一起的东西，坐的沙发要说“一张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93395, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一堆", "is_correct": true, "explanation": "“一堆”指堆积在一起的很多东西，路边的积雪正是这样，句意成立。"}, {"text": "一根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，堆起来的雪不能用“根”计量。"}, {"text": "一张", "is_correct": false, "explanation": "搭配：“张”用于平面、薄片状的东西，堆起来的雪不能说“一张雪”。"}, {"text": "一本", "is_correct": false, "explanation": "语义：“本”用于书册，雪不是书，句意不通。"}], "explanations": {"一堆": "“一堆”指堆积在一起的很多东西，路边的积雪正是这样，句意成立。", "一根": "搭配：“根”用于细长的东西，堆起来的雪不能用“根”计量。", "一张": "搭配：“张”用于平面、薄片状的东西，堆起来的雪不能说“一张雪”。", "一本": "语义：“本”用于书册，雪不是书，句意不通。"}, "sentence_index": 6, "correct_answer": "一堆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一堆手表戴在了手腕上。", "explanation": "这里应该用〈一块〉。“一堆”指很多东西堆在一起，戴在手腕上的单只手表要说“一块”。"}, {"text": "他戴上一堆帽子出门了。", "explanation": "这里应该用〈一顶〉。“一堆”指堆在一起的东西，戴在头上的帽子要说“一顶”。"}, {"text": "他的脚上穿着一堆袜子。", "explanation": "这里应该用〈一双〉。“一堆”指堆在一起的东西，成对穿在脚上的袜子要说“一双”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙角堆着一堆一堆煤。", "corrected_sentence": "墙角堆着一堆煤。", "error_description": "重复错误：“一堆”只需用一次，多出的“一堆”应删去。应改为“墙角堆着一堆煤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山脚下有一堆个石头。", "corrected_sentence": "山脚下有一堆石头。", "error_description": "量词错误：“一堆”后面直接接名词，不能再加个体量词“个”。应删去“个”，改为“一堆石头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
