INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93396, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数量词，指堆积在一起的很多东西。", "primary_collocate": null, "pronunciation": "yì duī", "ipa": "i˥˩ tweɪ˥", "syllable_count": 2, "sentences": [{"text": "他买了一堆水果回家。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一堆吃的。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发给我们一堆练习题。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从箱子里拿出一堆照片。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里有一堆便宜的苹果。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车里装着一堆行李。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店门口放了一堆旧书，很便宜。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把一堆玩具放进了箱子里。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她洗了一堆碗，累坏了。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子旁边有一堆盒子。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一大堆", "label": "复合"}], "register": "中性", "sense_fingerprint": "数量词，指堆积在一起的很多东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一堆", "is_correct": true, "explanation": "“一堆”指堆积在一起的很多东西，买来的水果正是这样，句意成立。"}, {"text": "一台", "is_correct": false, "explanation": "搭配：“台”用于机器、仪器等，水果不能用“台”计量。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、房屋等大型固定物体，水果不能用“座”计量。"}, {"text": "一场", "is_correct": false, "explanation": "语义：“场”用于一段活动或事件，“他买了一场水果”说不通。"}], "explanations": {"一堆": "“一堆”指堆积在一起的很多东西，买来的水果正是这样，句意成立。", "一台": "搭配：“台”用于机器、仪器等，水果不能用“台”计量。", "一座": "搭配：“座”用于山、房屋等大型固定物体，水果不能用“座”计量。", "一场": "语义：“场”用于一段活动或事件，“他买了一场水果”说不通。"}, "sentence_index": 0, "correct_answer": "一堆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气喝完了一堆牛奶。", "explanation": "这里应该用〈一杯〉。“一堆”指堆在一起的固体东西，牛奶是液体，要用“杯”计量。"}, {"text": "他端来一堆汤给客人喝。", "explanation": "这里应该用〈一碗〉。“一堆”指堆在一起的固体东西，汤是液体，盛出来要说“一碗汤”。"}, {"text": "操场上站着一堆大树。", "explanation": "这里应该用〈一排〉。“一堆”指堆在一起的东西，整齐排列的树要说“一排”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一堆", "is_correct": true, "explanation": "“一堆”指堆积在一起的很多东西，门口放着的旧书正是这样，句意成立。"}, {"text": "一顶", "is_correct": false, "explanation": "搭配：“顶”用于帽子、帐篷等，书不能用“顶”计量。"}, {"text": "一根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，成堆的旧书不能用“根”计量。"}, {"text": "一位", "is_correct": false, "explanation": "语义：“位”用于人，旧书不是人，“放了一位旧书”说不通。"}], "explanations": {"一堆": "“一堆”指堆积在一起的很多东西，门口放着的旧书正是这样，句意成立。", "一顶": "搭配：“顶”用于帽子、帐篷等，书不能用“顶”计量。", "一根": "搭配：“根”用于细长的东西，成堆的旧书不能用“根”计量。", "一位": "语义：“位”用于人，旧书不是人，“放了一位旧书”说不通。"}, "sentence_index": 6, "correct_answer": "一堆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子旁边站着一堆书架。", "explanation": "这里应该用〈一个〉。“一堆”指很多东西堆在一起，单独的一件家具要用“个”计数。"}, {"text": "我把一堆眼镜戴在了鼻子上。", "explanation": "这里应该用〈一副〉。“一堆”指堆放的东西，成对成套的眼镜要说“一副”。"}, {"text": "他坐在一堆椅子上吃饭。", "explanation": "这里应该用〈一把〉。“一堆”指很多东西堆在一起，坐的椅子只能一把，要说“一把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们搬走了一堆了旧书。", "corrected_sentence": "我们搬走了一堆旧书。", "error_description": "助词位置错误：“了”只能放在动词后，不能插在“一堆”后面。应删去“一堆”后多出的“了”，改为“搬走了一堆旧书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙角有一堆个纸盒。", "corrected_sentence": "墙角有一堆纸盒。", "error_description": "量词错误：“一堆”后面直接接名词，不能再加个体量词“个”。应删去“个”，改为“一堆纸盒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难吃", "is_correct": true, "explanation": "正确：“难吃”是“好吃”的反义词，说食物味道不好。"}, {"text": "便宜", "is_correct": false, "explanation": "与“好吃”无反义关系，“便宜”说价钱低。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“好吃”无反义关系，“漂亮”说外貌好看。"}, {"text": "干净", "is_correct": false, "explanation": "与“好吃”无反义关系，“干净”说整洁。"}], "correct_answer": "难吃", "explanations": {"难吃": "正确：“难吃”是“好吃”的反义词，说食物味道不好。", "便宜": "与“好吃”无反义关系，“便宜”说价钱低。", "漂亮": "与“好吃”无反义关系，“漂亮”说外貌好看。", "干净": "与“好吃”无反义关系，“干净”说整洁。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难吃", "is_correct": true, "explanation": "正确：“难吃”是“好吃”的反义词，说食物味道不好。"}, {"text": "高兴", "is_correct": false, "explanation": "与“好吃”无反义关系，“高兴”说心情好。"}, {"text": "凉快", "is_correct": false, "explanation": "与“好吃”无反义关系，“凉快”说温度低。"}, {"text": "整齐", "is_correct": false, "explanation": "与“好吃”无反义关系，“整齐”说排列有序。"}], "correct_answer": "难吃", "explanations": {"难吃": "正确：“难吃”是“好吃”的反义词，说食物味道不好。", "高兴": "与“好吃”无反义关系，“高兴”说心情好。", "凉快": "与“好吃”无反义关系，“凉快”说温度低。", "整齐": "与“好吃”无反义关系，“整齐”说排列有序。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好吃是吃起来味道很好。", "primary_collocate": null, "pronunciation": "hǎo chī", "ipa": "xaʊ˨˩ ʈʂʰɻ̩˥", "syllable_count": 2, "sentences": [{"text": "妈妈做的鱼很好吃，我吃了两碗饭。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的面条又便宜又好吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果看起来很大，但是不太好吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做的蛋糕真好吃，再给我一块吧。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京烤鸭好吃极了，我还想再吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个菜最好吃？我想点一个。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说奶奶包的饺子比饭馆的更好吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果不贵，而且都很好吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我们吃的火锅特别好吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子都喜欢好吃的东西。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更好吃", "label": "比较"}, {"form": "最好吃", "label": "最高级"}, {"form": "不好吃", "label": "否定"}, {"form": "好吃的", "label": "的字结构"}], "register": "口语", "sense_fingerprint": "食物吃起来味道很好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab94bc6-c383-4ea4-8aec-1bb1428bc55b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好吃", "is_correct": true, "explanation": "正确：“很好吃”说鱼的味道好，与“吃了两碗饭”相符。"}, {"text": "好喝", "is_correct": false, "explanation": "搭配：“好喝”说饮料，不能用来形容鱼。"}, {"text": "好听", "is_correct": false, "explanation": "语义：“好听”说声音，不能用来形容鱼的味道。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”说价钱，自己做的鱼不谈价钱，与句子不搭。"}], "explanations": {"好吃": "正确：“很好吃”说鱼的味道好，与“吃了两碗饭”相符。", "好喝": "搭配：“好喝”说饮料，不能用来形容鱼。", "好听": "语义：“好听”说声音，不能用来形容鱼的味道。", "贵": "搭配：“贵”说价钱，自己做的鱼不谈价钱，与句子不搭。"}, "sentence_index": 0, "correct_answer": "好吃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子很好吃。", "explanation": "这里应该用〈结实〉。好吃说食物味道好，桌子坚固要说结实。"}, {"text": "这把剪刀很好吃。", "explanation": "这里应该用〈好用〉。好吃用于食物，工具好不好用要说好用。"}, {"text": "这首歌很好吃。", "explanation": "这里应该用〈好听〉。好吃说食物味道，歌曲好不好要说好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好吃", "is_correct": true, "explanation": "正确：“比饭馆的更好吃”说饺子味道更好，与句意相符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说人的头脑，不能用来形容饺子。"}, {"text": "勤快", "is_correct": false, "explanation": "语义：“勤快”说人的做事态度，不能用来形容饺子。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”多说场面，不搭配饺子的味道比较。"}], "explanations": {"好吃": "正确：“比饭馆的更好吃”说饺子味道更好，与句意相符。", "聪明": "语义：“聪明”说人的头脑，不能用来形容饺子。", "勤快": "语义：“勤快”说人的做事态度，不能用来形容饺子。", "热闹": "搭配：“热闹”多说场面，不搭配饺子的味道比较。"}, "sentence_index": 6, "correct_answer": "好吃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书很好吃。", "explanation": "这里应该用〈好读〉。好吃说食物味道好，书读起来容易要说好读。"}, {"text": "这个游戏很好吃。", "explanation": "这里应该用〈好玩〉。好吃用于食物，游戏有趣要说好玩。"}, {"text": "这朵花很好吃。", "explanation": "这里应该用〈好闻〉。好吃说味道可口，花的气味要说好闻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这碗面条真好吃得，我还想再来一碗。", "corrected_sentence": "这碗面条真好吃，我还想再来一碗。", "error_description": "错误：“得”不能接在没有补语的“好吃”后面，“真好吃得”应去掉“得”。正确形式是“真好吃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的饺子最更好吃，每天都排队。", "corrected_sentence": "这家店的饺子最好吃，每天都排队。", "error_description": "错误：“最”和“更”都表示程度，不能同时用。“最好吃”是最高级，应去掉多余的“更”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
