INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93407, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "住区是很多人住在一起的一片地方。", "primary_collocate": null, "pronunciation": "zhù qū", "ipa": "ʈʂu˥˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "住区里每天早上都很热闹。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住区的超市就在大门旁边。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个住区新建了一座幼儿园。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住区占地广阔，去菜市场要走十分钟。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们常在住区的树下下棋。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司附近的住区房租比较贵。", "target_word": "住区", "complexity_tier": "T3", "furigana": "gōngsī fùjìn de zhù qū fáng zū bǐ jiào guì", "sentence_source": "generated"}, {"text": "城市里的每个住区都应该有公园。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个住区环境安静整洁，适宜居住。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在住区里骑着自行车转了一圈。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家所在的住区去年重新修了路。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "住區", "label": "繁体"}], "register": "书面", "sense_fingerprint": "很多人住在一起的一片地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e49e6890-ab2b-4fe2-b804-aada486c92c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93407, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住区", "is_correct": true, "explanation": "正确：“住区里每天早上都很热闹”指很多人住在一起的地方，语义相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装东西的袋子，不能指很多人住的地方。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“咖啡里”不能组成表示人群聚集的场所，与“每天早上很热闹”不搭。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书籍，不能作为人群聚居、热闹的地方。"}], "explanations": {"住区": "正确：“住区里每天早上都很热闹”指很多人住在一起的地方，语义相符。", "书包": "语义：“书包”是装东西的袋子，不能指很多人住的地方。", "咖啡": "搭配：“咖啡里”不能组成表示人群聚集的场所，与“每天早上很热闹”不搭。", "课本": "语义：“课本”是书籍，不能作为人群聚居、热闹的地方。"}, "sentence_index": 0, "correct_answer": "住区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的住区在二楼。", "explanation": "这里应该用〈住宅〉。住区指很多人住在一起的一片地方，不能说某户住在哪一层。"}, {"text": "这个住区的车间很大，工人每天三班倒。", "explanation": "这里应该用〈工厂〉。住区供人居住，有车间、工人三班倒的地方要用工厂。"}, {"text": "我们搬进了一部新建的住区。", "explanation": "这里应该用〈片〉。住区是一片地方，量词“部”多用于影视、车辆，应说“一片住区”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住区", "is_correct": true, "explanation": "正确：“城市里的每个住区都应该有公园”指居民聚居的区域，语义相符。"}, {"text": "毛衣", "is_correct": false, "explanation": "语义：“毛衣”是衣物，不能说每个都应该有公园。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：“钢笔”是书写工具，与城市规划中公园的语境无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱应该有公园”不成立，“冰箱”与城市公共设施不搭。"}], "explanations": {"住区": "正确：“城市里的每个住区都应该有公园”指居民聚居的区域，语义相符。", "毛衣": "语义：“毛衣”是衣物，不能说每个都应该有公园。", "钢笔": "语义：“钢笔”是书写工具，与城市规划中公园的语境无关。", "冰箱": "搭配：“冰箱应该有公园”不成立，“冰箱”与城市公共设施不搭。"}, "sentence_index": 6, "correct_answer": "住区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个住区一晚两百块，周末住着很划算。", "explanation": "这里应该用〈宾馆〉。住区是居民居住的区域，不按晚计价，要说住一晚的价钱应用宾馆。"}, {"text": "这个住区里有很多病人，每天都有医生查房。", "explanation": "这里应该用〈医院〉。住区供居民居住，有病人住院、医生查房的地方要用医院。"}, {"text": "游客要买票才能进入这个住区参观。", "explanation": "这里应该用〈景区〉。住区供居民居住，要买票参观的地方要用景区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把住区里每天早上都很热闹。", "corrected_sentence": "这个住区里每天早上都很热闹。", "error_description": "错误：量词。“把”用于有柄的器具，住区是一片地方，应说“这个住区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个安静又干净住区很适合住。", "corrected_sentence": "这个安静又干净的住区很适合住。", "error_description": "错误：漏掉“的”。“安静又干净”修饰名词“住区”时要加“的”，应说“安静又干净的住区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
