INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93408, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "居民居住的区域。", "primary_collocate": null, "pronunciation": "zhù qū", "ipa": "ʈʂu˥˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这个住区离地铁站只有五分钟。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新住区里有学校，也有医院。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府在城东规划了一个大住区。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老住区的房子大多有三十年了。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住区里的路很宽，孩子可以安全玩。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片住区住着上万居民。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住区入口有保安，外人不能随便进。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们搬进了城南新建的住区。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住区中间有一个小公园。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个住区的绿地很多，空气也好。", "target_word": "住区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "住區", "label": "繁体"}], "register": "书面", "sense_fingerprint": "居民居住的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e49e6890-ab2b-4fe2-b804-aada486c92c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住区", "is_correct": true, "explanation": "正确：“住区”指居民居住的区域，可以说离地铁站有多远。"}, {"text": "学期", "is_correct": false, "explanation": "语义：“学期”是一段时间，不能指居民居住的地方，无法与“离地铁站”搭配。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装东西的袋子，不能指一片区域。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，不能指一片住宅区域。"}], "explanations": {"住区": "正确：“住区”指居民居住的区域，可以说离地铁站有多远。", "学期": "语义：“学期”是一段时间，不能指居民居住的地方，无法与“离地铁站”搭配。", "书包": "语义：“书包”是装东西的袋子，不能指一片区域。", "身材": "体貌：“身材”指人的体型，不能指一片住宅区域。"}, "sentence_index": 0, "correct_answer": "住区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个住区有三层，每层住四户。", "explanation": "这里应该用〈住宅〉。住区指一片居民区，由许多楼组成；说某栋房子有几层要用住宅。"}, {"text": "我家的住区有两间卧室。", "explanation": "这里应该用〈住房〉。住区指一片地方，不是房屋；说房子有几间卧室要用住房。"}, {"text": "他们搬进了城南新建的一栋住区。", "explanation": "这里应该用〈片〉。住区是一片区域，量词“栋”只用于楼房，应说“一片住区”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住区", "is_correct": true, "explanation": "正确：“住区入口”指居民区的入口，与“有保安、外人不能随便进”相符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，不能作为有保安把守的入口。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：“课桌”是学校里的家具，与保安把守、外人不能进的语境不符。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是身体器官，不能用作有保安把守的入口。"}], "explanations": {"住区": "正确：“住区入口”指居民区的入口，与“有保安、外人不能随便进”相符。", "面包": "语义：“面包”是食物，不能作为有保安把守的入口。", "课桌": "语义：“课桌”是学校里的家具，与保安把守、外人不能进的语境不符。", "眼睛": "体貌：“眼睛”是身体器官，不能用作有保安把守的入口。"}, "sentence_index": 6, "correct_answer": "住区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个住区一晚要五百块，住着很划算。", "explanation": "这里应该用〈宾馆〉。住区是居民居住的区域，不按晚计价，要说住一晚的价钱应用宾馆。"}, {"text": "这个住区每人要买票，游客可以进去参观。", "explanation": "这里应该用〈景区〉。住区供居民居住，不卖门票；要说游客买票参观应用景区。"}, {"text": "这个住区里有一条生产线，每天生产上千件产品。", "explanation": "这里应该用〈工厂〉。住区供居民居住，用于生产的场所要用工厂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋住区绿化很好，离地铁也近。", "corrected_sentence": "这个住区绿化很好，离地铁也近。", "error_description": "错误：量词。住区是一片区域，“栋”只用于楼房，应说“这个住区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那些住区们都很安静。", "corrected_sentence": "那些住区都很安静。", "error_description": "错误：“们”。“住区”不是指人的名词，不能加“们”表示复数，应说“那些住区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
