INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93409, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "几次是不知道有多少次，但不是很多。", "primary_collocate": null, "pronunciation": "jǐ cì", "ipa": "tɕi˨˩˦ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "我只去过几次那家饭馆。", "target_word": "几次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来过几次，可是我记不清了。", "target_word": "几次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月妈妈才给我打了几次电话。", "target_word": "几次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一年只见几次面。", "target_word": "几次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说过几次，他还是忘了带书。", "target_word": "几次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路我走过几次，不太难走。", "target_word": "几次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟昨天哭了几次，现在睡着了。", "target_word": "几次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了几次手表，就走了。", "target_word": "几次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我试了几次，终于打开了门。", "target_word": "几次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在那个城市住过几次，每次都不长。", "target_word": "几次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好几次", "label": "复合"}, {"form": "幾次", "label": "繁体"}], "register": "口语", "sense_fingerprint": "不确定的少数次数，表示没有很多次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df811bf5-9274-44e9-838a-6aef24dd96b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "几次", "is_correct": true, "explanation": "正确：“几次”表示不多的若干次，与“只”搭配，句意自然。"}, {"text": "屡次", "is_correct": false, "explanation": "语域：“屡次”偏书面，与口语语境不符；而且“只去过屡次”语义冲突。"}, {"text": "很多次", "is_correct": false, "explanation": "语义：“只”表示数量少，与“很多次”的数量大冲突。"}, {"text": "上百次", "is_correct": false, "explanation": "语义：“只”表示少，与“上百次”的大数量冲突。"}], "explanations": {"几次": "正确：“几次”表示不多的若干次，与“只”搭配，句意自然。", "屡次": "语域：“屡次”偏书面，与口语语境不符；而且“只去过屡次”语义冲突。", "很多次": "语义：“只”表示数量少，与“很多次”的数量大冲突。", "上百次": "语义：“只”表示少，与“上百次”的大数量冲突。"}, "sentence_index": 0, "correct_answer": "几次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一天给我打了几次电话，一共五百次。", "explanation": "这里应该用〈很多次〉。“几次”表示不多的次数，不能用来计算五百次这样的大数。"}, {"text": "我们一年见几次面，一共见了一千次。", "explanation": "这里应该用〈很多次〉。“几次”表示不多的次数，与“一千次”的大数矛盾。"}, {"text": "我们班一共有几次学生。", "explanation": "这里应该用〈几个〉。“次”是计量动作的量词，不能用来数人，数学生应说几个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几次", "is_correct": true, "explanation": "正确：“哭了几次”表示次数不多，与“昨天”相合。"}, {"text": "一辈子", "is_correct": false, "explanation": "语义：“一辈子”是漫长的时间，与“昨天”冲突。"}, {"text": "好几年", "is_correct": false, "explanation": "语义：“好几年”指很长的时间，与“昨天”冲突。"}, {"text": "几十年", "is_correct": false, "explanation": "语义：“几十年”指很长的时间，与“昨天”冲突。"}], "explanations": {"几次": "正确：“哭了几次”表示次数不多，与“昨天”相合。", "一辈子": "语义：“一辈子”是漫长的时间，与“昨天”冲突。", "好几年": "语义：“好几年”指很长的时间，与“昨天”冲突。", "几十年": "语义：“几十年”指很长的时间，与“昨天”冲突。"}, "sentence_index": 6, "correct_answer": "几次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在那个城市住过几次年，每次都不长。", "explanation": "这里应该用〈几年〉。“次”是计量动作的量词，不能用来计算住的年数。"}, {"text": "他在那个城市住过几次，一共住了一千次。", "explanation": "这里应该用〈很多次〉。“几次”表示不多的次数，不能与“一千次”这样的大数搭配。"}, {"text": "他在那个城市有几次房子。", "explanation": "这里应该用〈几套〉。“次”是计量动作的量词，不能用来数房子，房子要用“套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我这个学期只去过几次了图书馆。", "corrected_sentence": "我这个学期只去过几次图书馆。", "error_description": "错误在于“了”的位置。“去过”已表示经历，“几次”后面不能加“了”，应说“去过几次图书馆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去了几次个医院。", "corrected_sentence": "他去了几次医院。", "error_description": "错误在于量词的堆叠。“几次”本身已是次数，后面不能再接量词“个”，应说“去了几次医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
