INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93411, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "传来是声音或消息从远处过来。", "primary_collocate": null, "pronunciation": "chuán lái", "ipa": "tʂʰwan³⁵ lai³⁵", "syllable_count": 2, "sentences": [{"text": "夜里，远处传来火车的声音。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室外面传来笑声。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师那里传来了考试的消息。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里传来切菜的声音。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从海边传来了台风要来的消息。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里传来小鸟的歌声。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对面的房间传来唱歌的声音。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听到城里传来的好消息，很高兴。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河对岸传来了一声大叫。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话那头传来朋友着急的声音。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传来了", "label": "体标"}, {"form": "传来过", "label": "体标"}], "register": "中性", "sense_fingerprint": "传来：声音或消息从远处过来，让人听到或得知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e6d86ab-0aec-443b-942c-15f3d782f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传来", "is_correct": true, "explanation": "声音从远处传到说话人这里，与“夜里，远处”和“火车的声音”相合。"}, {"text": "闻到", "is_correct": false, "explanation": "语义：“闻到”是嗅觉感知，“火车的声音”是听觉对象，句意不通。"}, {"text": "咬碎", "is_correct": false, "explanation": "搭配：“咬碎”的对象是食物等实物，不能说咬碎声音。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，用于尊贵的人，不能用于火车的声音。"}], "explanations": {"传来": "声音从远处传到说话人这里，与“夜里，远处”和“火车的声音”相合。", "闻到": "语义：“闻到”是嗅觉感知，“火车的声音”是听觉对象，句意不通。", "咬碎": "搭配：“咬碎”的对象是食物等实物，不能说咬碎声音。", "驾临": "语域：“驾临”是敬辞，用于尊贵的人，不能用于火车的声音。"}, "sentence_index": 0, "correct_answer": "传来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈从超市传来一箱牛奶。", "explanation": "这里应该用〈拿来〉。传来用于声音或消息，实物要用〈拿来〉。"}, {"text": "老师从办公室传来一叠试卷。", "explanation": "这里应该用〈带来〉。传来用于声音或消息，试卷是实物，要用〈带来〉。"}, {"text": "姐姐从北京传来一本书。", "explanation": "这里应该用〈寄来〉。传来用于声音或消息，书是实物，要用〈寄来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传来", "is_correct": true, "explanation": "声音从别处传到说话人这里，与“对面的房间”和“唱歌的声音”相合。"}, {"text": "摸到", "is_correct": false, "explanation": "语义：“摸到”靠触觉感知，“唱歌的声音”不能用手摸到。"}, {"text": "挖出", "is_correct": false, "explanation": "搭配：“挖出”的对象是埋在地下的东西，不能说挖出声音。"}, {"text": "传给", "is_correct": false, "explanation": "配价：“传给”需要接受者，且接受者应是人；句中没有合适的接受者，声音也不是传给房间的。"}], "explanations": {"传来": "声音从别处传到说话人这里，与“对面的房间”和“唱歌的声音”相合。", "摸到": "语义：“摸到”靠触觉感知，“唱歌的声音”不能用手摸到。", "挖出": "搭配：“挖出”的对象是埋在地下的东西，不能说挖出声音。", "传给": "配价：“传给”需要接受者，且接受者应是人；句中没有合适的接受者，声音也不是传给房间的。"}, "sentence_index": 6, "correct_answer": "传来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人从仓库传来一把椅子。", "explanation": "这里应该用〈搬来〉。传来用于声音或消息，椅子是实物，要用〈搬来〉。"}, {"text": "服务员传来一碗汤。", "explanation": "这里应该用〈端来〉。传来不用于送来食物，端来一碗汤要用〈端来〉。"}, {"text": "邻居从楼下传来一盘饺子。", "explanation": "这里应该用〈送来〉。传来用于声音或消息，饺子是实物，要用〈送来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里，火车的声音传来远处。", "corrected_sentence": "夜里，火车的声音传到了远处。", "error_description": "方向补语错误：“传来”的终点是说话人所在之处，不能说“传来远处”，应说“传到远处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对面的房间传来到一阵唱歌的声音。", "corrected_sentence": "对面的房间传来一阵唱歌的声音。", "error_description": "补语重复：“传来”已含趋向补语“来”，其后不能再加“到”，应删去“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
