INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93412, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从别处传递过来（声音、消息等）。", "primary_collocate": null, "pronunciation": "chuán lái", "ipa": "tʂʰwan³⁵ lai³⁵", "syllable_count": 2, "sentences": [{"text": "远处传来一阵音乐声。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁传来孩子的哭声。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好消息从北京传来了。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼下传来有人说话的声音。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里传来了清楚的鸟叫声。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里传来妈妈的声音。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外传来汽车的喇叭声。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前方传来比赛胜利的消息。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正睡着，门外突然传来敲门声。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天从老家传来一个坏消息。", "target_word": "传来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传来了", "label": "体标"}, {"form": "传来过", "label": "体标"}], "register": "中性", "sense_fingerprint": "传来：声音、消息等从别处传到说话人这里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e6d86ab-0aec-443b-942c-15f3d782f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传来", "is_correct": true, "explanation": "声音从远处传到说话人这里，与“远处”和“一阵音乐声”相合。"}, {"text": "看见", "is_correct": false, "explanation": "语义：“看见”靠视觉感知，“音乐声”要用耳朵听，句中说的是听到的声音。"}, {"text": "飞走", "is_correct": false, "explanation": "搭配：“飞走”多指鸟等会飞的东西离开，不能说“飞走一阵音乐声”。"}, {"text": "降临", "is_correct": false, "explanation": "语域：“降临”是书面语，多用于夜幕、福音等降下或到来，与口语化的音乐声不合。"}], "explanations": {"传来": "声音从远处传到说话人这里，与“远处”和“一阵音乐声”相合。", "看见": "语义：“看见”靠视觉感知，“音乐声”要用耳朵听，句中说的是听到的声音。", "飞走": "搭配：“飞走”多指鸟等会飞的东西离开，不能说“飞走一阵音乐声”。", "降临": "语域：“降临”是书面语，多用于夜幕、福音等降下或到来，与口语化的音乐声不合。"}, "sentence_index": 0, "correct_answer": "传来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈从老家传来一个包裹。", "explanation": "这里应该用〈送来〉。传来用于声音或消息，包裹是实物，要用〈送来〉。"}, {"text": "他从学校传来一本课本。", "explanation": "这里应该用〈带来〉。传来用于声音或消息，课本是实物，要用〈带来〉。"}, {"text": "他从英国传来一箱茶叶。", "explanation": "这里应该用〈寄来〉。传来用于声音或消息，茶叶是实物，要用〈寄来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传来", "is_correct": true, "explanation": "声音从别处传到说话人这里，与“窗外”和“汽车的喇叭声”相合。"}, {"text": "传给", "is_correct": false, "explanation": "配价：“传给”后面要带接受者，且接受者应是人；“汽车”不能作接受者。"}, {"text": "摔碎", "is_correct": false, "explanation": "搭配：“摔碎”的对象是易碎的器物，不能和“喇叭声”搭配。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的对象须是可以吃的东西，声音不能被吃掉。"}], "explanations": {"传来": "声音从别处传到说话人这里，与“窗外”和“汽车的喇叭声”相合。", "传给": "配价：“传给”后面要带接受者，且接受者应是人；“汽车”不能作接受者。", "摔碎": "搭配：“摔碎”的对象是易碎的器物，不能和“喇叭声”搭配。", "吃掉": "搭配：“吃掉”的对象须是可以吃的东西，声音不能被吃掉。"}, "sentence_index": 6, "correct_answer": "传来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂从外地传来一车钢材。", "explanation": "这里应该用〈运来〉。传来用于声音或消息，大宗货物要用〈运来〉。"}, {"text": "服务员从厨房传来一碗汤。", "explanation": "这里应该用〈端来〉。传来不用于端送食物，端来一碗汤要用〈端来〉。"}, {"text": "他从车库传来一把铲子。", "explanation": "这里应该用〈拿来〉。传来用于声音或消息，铲子是实物，要用〈拿来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一阵风声传来远处。", "corrected_sentence": "一阵风声传到了远处。", "error_description": "方向补语错误：“传来”的终点是说话人所在之处，不能说“传来远处”，应说“传到远处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗外传来来汽车的喇叭声。", "corrected_sentence": "窗外传来了汽车的喇叭声。", "error_description": "补语错误：“传来”后面不能再接一个“来”，表示完成应用“了”，应说“传来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
