INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "临时停止，之后还可能继续。", "primary_collocate": null, "pronunciation": "zàn tíng", "ipa": "tsan˥˩ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "因为大雾，航班暂停起飞。", "target_word": "暂停", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店暂停营业，下周才开门。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司因为修路，暂停了送货服务。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校暂停了所有的户外活动。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁暂停运行，请改坐公共汽车。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "由于天气不好，演出暂停了一周。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院暂停接收新病人，等通知再说。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网站正在维修，注册功能暂停使用。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们暂停了合作，准备明年再谈。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路暂停通行，三天后才开放。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "暂停了", "label": "完成体标"}, {"form": "暂停过", "label": "经历体标"}, {"form": "暂停键", "label": "复合词"}, {"form": "暫停", "label": "繁体"}], "register": "中性", "sense_fingerprint": "业务、活动、服务因故临时停止，以后可能恢复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a469138-6fb8-45ff-8b3c-19ee085e4330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暂停", "is_correct": true, "explanation": "暂停（zàn tíng）指临时停止，是听到的目标词。"}, {"text": "暂定", "is_correct": false, "explanation": "dìng（第四声）与 tíng 声母不同（d 与 t），声调也不同，意思是暂时确定。"}, {"text": "赞同", "is_correct": false, "explanation": "tóng（第二声）与 tíng 韵尾不同（ong 与 ing），意思是表示同意。"}, {"text": "站停", "is_correct": false, "explanation": "zhàn（第四声）与 zàn 声母不同（zh 与 z），意思是在站点停下。"}, {"text": "暂行", "is_correct": false, "explanation": "xíng（第二声）与 tíng 声母不同（x 与 t），意思是暂时施行。"}], "explanations": {"暂停": "暂停（zàn tíng）指临时停止，是听到的目标词。", "暂定": "dìng（第四声）与 tíng 声母不同（d 与 t），声调也不同，意思是暂时确定。", "赞同": "tóng（第二声）与 tíng 韵尾不同（ong 与 ing），意思是表示同意。", "站停": "zhàn（第四声）与 zàn 声母不同（zh 与 z），意思是在站点停下。", "暂行": "xíng（第二声）与 tíng 声母不同（x 与 t），意思是暂时施行。"}, "sentence_index": null, "correct_answer": "暂停"}, "level_3": {"options": [{"text": "暂停", "is_correct": true, "explanation": "“暂停”表示临时停止，与“因为大雾”的停飞原因相符。"}, {"text": "继续", "is_correct": false, "explanation": "语义：“继续”表示接着进行，与“因为大雾”的停飞原因相反。"}, {"text": "允许", "is_correct": false, "explanation": "语义：“允许”表示同意，与“因为大雾”的停飞原因不合。"}, {"text": "开放", "is_correct": false, "explanation": "搭配与语义：“开放”指对外提供服务，不能说“航班开放起飞”，与大雾停飞的情境相反。"}], "explanations": {"暂停": "“暂停”表示临时停止，与“因为大雾”的停飞原因相符。", "继续": "语义：“继续”表示接着进行，与“因为大雾”的停飞原因相反。", "允许": "语义：“允许”表示同意，与“因为大雾”的停飞原因不合。", "开放": "搭配与语义：“开放”指对外提供服务，不能说“航班开放起飞”，与大雾停飞的情境相反。"}, "sentence_index": 0, "correct_answer": "暂停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市暂停营业，以后再也不开门了。", "explanation": "这里应该用〈倒闭〉。暂停指暂时停止、之后会恢复；“以后再也不开门”说的是彻底停业，要用倒闭。"}, {"text": "博物馆已经暂停，欢迎大家来参观。", "explanation": "这里应该用〈开放〉。暂停是停止服务，与“欢迎大家来参观”矛盾。"}, {"text": "这次活动已经暂停，以后不会再办了。", "explanation": "这里应该用〈取消〉。暂停表示之后还会恢复，与“不会再办”矛盾，要用取消。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暂停", "is_correct": true, "explanation": "“暂停”表示暂时停止接收，与“等通知再说”相符。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大”表示增加范围，与“等通知再说”的暂缓不符。"}, {"text": "公布", "is_correct": false, "explanation": "搭配：“公布”指对外发布消息，不能用作“医院……接收新病人”的谓语，与“等通知再说”也不合。"}, {"text": "启动", "is_correct": false, "explanation": "搭配：“启动”多用于程序或项目，不用于医院接收病人。"}], "explanations": {"暂停": "“暂停”表示暂时停止接收，与“等通知再说”相符。", "扩大": "语义：“扩大”表示增加范围，与“等通知再说”的暂缓不符。", "公布": "搭配：“公布”指对外发布消息，不能用作“医院……接收新病人”的谓语，与“等通知再说”也不合。", "启动": "搭配：“启动”多用于程序或项目，不用于医院接收病人。"}, "sentence_index": 6, "correct_answer": "暂停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件服务已经暂停，用户以后再也不能登录了。", "explanation": "这里应该用〈终止〉。暂停说明之后还会恢复，“以后再也不能登录”是彻底结束，要用终止。"}, {"text": "这条线路已经暂停，每天都有车。", "explanation": "这里应该用〈开通〉。暂停指停止服务，与“每天都有车”矛盾。"}, {"text": "这家新店今天终于暂停了，大家都很高兴。", "explanation": "这里应该用〈开业〉。暂停指停止营业，不用来说新店开张。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "因为台风，渡轮暂停了运营了两天。", "corrected_sentence": "因为台风，渡轮暂停运营了两天。", "error_description": "“暂停”后多加了一个“了”：“运营”后已有“了”，动词之间不能重复用“了”；应说“暂停运营了两天”，不能说“暂停了运营了两天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店很暂停营业，等装修好再开。", "corrected_sentence": "这家店暂停营业，等装修好再开。", "error_description": "“很”一般不修饰“暂停营业”这类动作动词（可说“很喜欢”，不说“很暂停”），应去掉“很”，说“这家店暂停营业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
