INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "重大日子或事件到来之前的晚上或时期。", "primary_collocate": null, "pronunciation": "qián xī", "ipa": "tɕʰjɛn˧˥ ɕi˥", "syllable_count": 2, "sentences": [{"text": "比赛前夕，队员们都很紧张。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节前夕，街上挂满了红灯笼。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前夕，他一直在复习功课。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼前夕，新娘一直睡不着。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业前夕，同学们互相写了留言。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发前夕，我又检查了一遍行李。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国庆前夕，广场上摆满了鲜花。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会前夕，工作人员忙到很晚。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争前夕，这个小城还很平静。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出前夕，演员们在台上最后排练了一次。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "重大日子或事件到来之前的晚上或时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d689ef-f29c-47a1-838b-0acd26167009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墨水", "is_correct": false, "explanation": "语义：墨水是液体，不表示时间，“比赛墨水”说不通。"}, {"text": "前夕", "is_correct": true, "explanation": "“前夕”指比赛这类大事来临前的一段时间，放在“比赛”后面正合适。"}, {"text": "假期", "is_correct": false, "explanation": "搭配：“比赛”后面不能接“假期”，二者无法组合成表示时间的词语。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是随身的物品，与比赛的时间无关。"}], "explanations": {"墨水": "语义：墨水是液体，不表示时间，“比赛墨水”说不通。", "前夕": "“前夕”指比赛这类大事来临前的一段时间，放在“比赛”后面正合适。", "假期": "搭配：“比赛”后面不能接“假期”，二者无法组合成表示时间的词语。", "钱包": "语义：钱包是随身的物品，与比赛的时间无关。"}, "sentence_index": 0, "correct_answer": "前夕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个项目前夕进展很顺利。", "explanation": "这里应该用〈前期〉。“前期”指项目的初始阶段，“前夕”指重大日子来临前的晚上或时期，不能用来指项目的阶段。"}, {"text": "我前夕收到了一封信。", "explanation": "这里应该用〈前天〉。“前夕”只用于重大日子或事件来临前，普通的日子不能用。"}, {"text": "前夕我睡得很好。", "explanation": "这里应该用〈前一晚〉。“前夕”要指大事来临前，普通的前一晚不能说“前夕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树叶", "is_correct": false, "explanation": "语义：树叶是植物的一部分，不表示节日前的时间，“国庆树叶”说不通。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是物品，不能指节日来临前的时间段。"}, {"text": "前夕", "is_correct": true, "explanation": "“前夕”指国庆这样的节日来临前的时间，与“国庆”搭配正确。"}, {"text": "期中", "is_correct": false, "explanation": "搭配：“期中”指学期的中间阶段，不能与“国庆”组合。"}], "explanations": {"树叶": "语义：树叶是植物的一部分，不表示节日前的时间，“国庆树叶”说不通。", "鞋子": "语义：鞋子是物品，不能指节日来临前的时间段。", "前夕": "“前夕”指国庆这样的节日来临前的时间，与“国庆”搭配正确。", "期中": "搭配：“期中”指学期的中间阶段，不能与“国庆”组合。"}, "sentence_index": 6, "correct_answer": "前夕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我前夕去跑步了。", "explanation": "这里应该用〈早晨〉。“前夕”指重大事件来临前的时间，普通的早晨去跑步不能用“前夕”。"}, {"text": "这个计划的前夕很好。", "explanation": "这里应该用〈前景〉。“前景”指发展的前途，“前夕”只指时间，不能用来说计划的前途。"}, {"text": "这首歌的前夕太长了。", "explanation": "这里应该用〈前奏〉。“前奏”指歌曲开头的部分，“前夕”指重大日子之前的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台风登陆前夕地，超市里挤满了人。", "corrected_sentence": "台风登陆前夕，超市里挤满了人。", "error_description": "“前夕”是名词，后面不能加“地”修饰，应说“台风登陆前夕，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司年会前夕们，大家都在加班。", "corrected_sentence": "公司年会前夕，大家都在加班。", "error_description": "“前夕”后面多加了“们”。“前夕”是表示时间的名词，不能加“们”表示复数，应说“公司年会前夕，……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
