INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "本就是一开始就是这样，不是后来才这样。", "primary_collocate": null, "pronunciation": "běn jiù", "ipa": "pən˨˩ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个湖本就在这里，不是人造的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的性格本就开朗，不是现在才变的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路本就很窄，不是因为修路才窄。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她本就是南方人，不是搬去的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地本就是我家的，不是借来的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音本就很小，不是感冒才这样。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的毛本就是白色的，不是洗白的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥本就叫长桥，不是后来改的名。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本就不会游泳，不是今天才怕水。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那件衣服本就破了，不是我弄坏的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，强调状态从一开始就如此，不是后来形成的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c11b62-a391-4e78-aa2c-8e0c8aef0aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "本就", "is_correct": true, "explanation": "正确答案。本就（běn jiù）意思是从一开始就如此。"}, {"text": "本剧", "is_correct": false, "explanation": "jù（第四声）与 jiù（第四声）的韵母不同，少了 i，意思是这部剧。"}, {"text": "本届", "is_correct": false, "explanation": "jiè（第四声）与 jiù（第四声）的韵母不同（è 与 ù），意思是这一届。"}, {"text": "本季", "is_correct": false, "explanation": "jì（第四声）与 jiù（第四声）的韵母不同，少了 u，意思是本季度。"}, {"text": "很旧", "is_correct": false, "explanation": "hěn（第三声）与 běn（第三声）的声母不同（h 与 b），意思是很旧。"}], "explanations": {"本就": "正确答案。本就（běn jiù）意思是从一开始就如此。", "本剧": "jù（第四声）与 jiù（第四声）的韵母不同，少了 i，意思是这部剧。", "本届": "jiè（第四声）与 jiù（第四声）的韵母不同（è 与 ù），意思是这一届。", "本季": "jì（第四声）与 jiù（第四声）的韵母不同，少了 u，意思是本季度。", "很旧": "hěn（第三声）与 běn（第三声）的声母不同（h 与 b），意思是很旧。"}, "sentence_index": null, "correct_answer": "本就"}, "level_3": {"options": [{"text": "本就", "is_correct": true, "explanation": "正确。本就表示湖从一开始就在这里，与“不是人造的”相合。"}, {"text": "又", "is_correct": false, "explanation": "语义：又表示再次或累加，句中没有先前的情况，“这个湖又在这里”说不通。"}, {"text": "更", "is_correct": false, "explanation": "搭配：更通常修饰形容词或用于比较句，不与“在这里”这样的处所动词搭配。"}, {"text": "突然", "is_correct": false, "explanation": "语义：突然表示事情忽然发生，与“不是人造的”强调湖原本就在的背景不符。"}], "explanations": {"本就": "正确。本就表示湖从一开始就在这里，与“不是人造的”相合。", "又": "语义：又表示再次或累加，句中没有先前的情况，“这个湖又在这里”说不通。", "更": "搭配：更通常修饰形容词或用于比较句，不与“在这里”这样的处所动词搭配。", "突然": "语义：突然表示事情忽然发生，与“不是人造的”强调湖原本就在的背景不符。"}, "sentence_index": 0, "correct_answer": "本就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她本就刚搬来这里，大家都不熟悉。", "explanation": "这里不能用〈本就〉。〈本就〉表示一直如此、不是后来形成，而句中说的是新近才发生的变动，两者意思矛盾。"}, {"text": "她本就变成了南方人，口音早就变了。", "explanation": "这里不能用〈本就〉。〈本就〉表示从一开始就如此，而句中说的是后来才发生的改变，两者意思矛盾。"}, {"text": "她本就已经搬走了，现在几乎找不到她。", "explanation": "这里不能用〈本就〉。〈本就〉表示从一开始就是这样，而句中说的是后来才发生的搬离，两者意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "本就", "is_correct": true, "explanation": "正确答案。本就（běn jiù）意思是从一开始就如此。"}, {"text": "半旧", "is_correct": false, "explanation": "bàn（第四声）与 běn（第三声）的声调不同，后一音节 jiù 相同，意思是半新不旧。"}, {"text": "奔救", "is_correct": false, "explanation": "bēn（第一声）与 běn（第三声）的声调不同，后一音节 jiù 相同，意思是奔赴救援。"}, {"text": "本价", "is_correct": false, "explanation": "jià（第四声）与 jiù（第四声）的韵母不同（a 与 u），意思是这个价格。"}], "explanations": {"本就": "正确答案。本就（běn jiù）意思是从一开始就如此。", "半旧": "bàn（第四声）与 běn（第三声）的声调不同，后一音节 jiù 相同，意思是半新不旧。", "奔救": "bēn（第一声）与 běn（第三声）的声调不同，后一音节 jiù 相同，意思是奔赴救援。", "本价": "jià（第四声）与 jiù（第四声）的韵母不同（a 与 u），意思是这个价格。"}, "sentence_index": null, "correct_answer": "本就"}, "level_3": {"options": [{"text": "本就", "is_correct": true, "explanation": "正确。本就表示小狗的毛从一开始就是白色，与“不是洗白的”相合。"}, {"text": "终于", "is_correct": false, "explanation": "语义：终于表示经过一段过程后才出现，与“本就是白色的”的从来如此相反。"}, {"text": "渐渐", "is_correct": false, "explanation": "搭配：渐渐修饰逐步发生的变化，不与“是白色的”这种判断搭配。"}, {"text": "逐渐", "is_correct": false, "explanation": "搭配：逐渐与渐渐同义，同样只修饰变化过程，不能用于“是……的”判断。"}], "explanations": {"本就": "正确。本就表示小狗的毛从一开始就是白色，与“不是洗白的”相合。", "终于": "语义：终于表示经过一段过程后才出现，与“本就是白色的”的从来如此相反。", "渐渐": "搭配：渐渐修饰逐步发生的变化，不与“是白色的”这种判断搭配。", "逐渐": "搭配：逐渐与渐渐同义，同样只修饰变化过程，不能用于“是……的”判断。"}, "sentence_index": 6, "correct_answer": "本就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那件衣服本就突然破了，我还没碰过它。", "explanation": "这里不能用〈本就〉。〈本就〉表示一直就是这样，而句中说的是新近才出现的情况，两者意思矛盾。"}, {"text": "那件衣服本就被我弄坏了，我很后悔。", "explanation": "这里不能用〈本就〉。〈本就〉表示从一开始就如此，而句中说的是后来才造成的损坏，两者意思矛盾。"}, {"text": "那件衣服本就送给了朋友，我再也没见过它。", "explanation": "这里不能用〈本就〉。〈本就〉表示从一开始就如此，而句中说的是后来才发生的转送，两者意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套家具本就了木头做的，不是塑料的。", "corrected_sentence": "这套家具本就是木头做的，不是塑料的。", "error_description": "错误形式：“本就了木头做的”，“了”不能用作判断动词。正确形式：“本就是木头做的”，判断句应用“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子本就了朝南，冬天很暖和。", "corrected_sentence": "这间屋子本就朝南，冬天很暖和。", "error_description": "“本就”后面不能直接加动态助词“了”：“本就了朝南”不通。“朝南”是静态状态，不需要“了”，去掉即可，说“这间屋子本就朝南”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
