INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "游泳是人在水里，用手和脚动一动，身体就能向前走。", "primary_collocate": null, "pronunciation": "yóu yǒng", "ipa": "joʊ˧˥ jʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我喜欢在夏天去游泳。", "target_word": "游泳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他会游泳，我不会。", "target_word": "游泳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明每个周末都和爸爸去游泳。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想不想跟我们一起去游泳？", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在河里游泳，玩得很开心。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天太热了，我们去游泳吧。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我四岁的时候就学会了游泳。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每天早上游泳一个小时。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，今天不能去游泳了。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妹妹怕水，不敢游泳。", "target_word": "游泳", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "游过泳", "label": "体标"}, {"form": "游泳池", "label": "复合"}, {"form": "游泳衣", "label": "复合"}], "register": "中性", "sense_fingerprint": "人在水里用手脚动，身体向前；日常去游泳、会不会游泳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df811bf5-9274-44e9-838a-6aef24dd96b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游泳", "is_correct": true, "explanation": "正确：“游泳”指在水中用手脚划动身体，与“在夏天去”搭配，句意自然。"}, {"text": "取暖", "is_correct": false, "explanation": "语义：取暖是冬天御寒的做法，与“夏天”冲突。"}, {"text": "烤火", "is_correct": false, "explanation": "语义：烤火是冬天取暖的做法，与“夏天”冲突。"}, {"text": "下雪", "is_correct": false, "explanation": "配价：“下雪”是自然现象，不是人能去做的动作，不能放在“去”后面。"}], "explanations": {"游泳": "正确：“游泳”指在水中用手脚划动身体，与“在夏天去”搭配，句意自然。", "取暖": "语义：取暖是冬天御寒的做法，与“夏天”冲突。", "烤火": "语义：烤火是冬天取暖的做法，与“夏天”冲突。", "下雪": "配价：“下雪”是自然现象，不是人能去做的动作，不能放在“去”后面。"}, "sentence_index": 0, "correct_answer": "游泳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车在马路上游泳。", "explanation": "这里应该用〈行驶〉。游泳指人或动物在水中划动身体前进，汽车在马路上只能行驶，不能说游泳。"}, {"text": "这个周末我们去长城游泳。", "explanation": "这里应该用〈游览〉。游泳是在水中划动身体前进，长城上没有水，去长城应说游览。"}, {"text": "周末我们去图书馆游泳。", "explanation": "这里应该用〈看书〉。游泳要在水中划动身体前进，图书馆里不能游泳，这里应说看书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游泳", "is_correct": true, "explanation": "正确：“学会了”后面接的是一项技能，“游泳”符合句意。"}, {"text": "开车", "is_correct": false, "explanation": "语义：四岁的孩子不能学开车，与“四岁的时候”冲突。"}, {"text": "喝酒", "is_correct": false, "explanation": "语义：四岁的孩子不会学喝酒，与“四岁的时候”冲突。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“学会”后接技能，“考试”是活动，不能说“学会了考试”。"}], "explanations": {"游泳": "正确：“学会了”后面接的是一项技能，“游泳”符合句意。", "开车": "语义：四岁的孩子不能学开车，与“四岁的时候”冲突。", "喝酒": "语义：四岁的孩子不会学喝酒，与“四岁的时候”冲突。", "考试": "搭配：“学会”后接技能，“考试”是活动，不能说“学会了考试”。"}, "sentence_index": 6, "correct_answer": "游泳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上在操场游泳。", "explanation": "这里应该用〈跑步〉。游泳要在水中划动身体前进，操场上不能游泳，这种锻炼应说跑步。"}, {"text": "他在床上游泳。", "explanation": "这里应该用〈睡觉〉。游泳要在水中划动身体，床上不能游泳，这里说的是躺在床上睡觉，应说睡觉。"}, {"text": "他用游泳的方法写完了报告。", "explanation": "这里应该用〈撰写〉。游泳指在水中划动身体前进，不能用作写报告的方法，写报告应说撰写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们湖里游泳。", "corrected_sentence": "周末我们在湖里游泳。", "error_description": "错误在于地点状语：“湖里”前缺少介词“在”，应说“在湖里游泳”，不能说“湖里游泳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每星期去游泳一个。", "corrected_sentence": "我每星期去游泳一次。", "error_description": "错误在于“游泳”的量词。游泳的次数要用量词“次”，不能用“个”。正确说法是“去游泳一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
