INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93445, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "湖是陆地上很大一片水，比池塘大很多。", "primary_collocate": null, "pronunciation": "hú", "ipa": "xu˧˥", "syllable_count": 1, "sentences": [{"text": "这个湖很大，比我家旁边的池塘大多了。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里有很多鱼，周末常有人来钓鱼。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐小船在湖上玩。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖的水很干净。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖很大，走一圈要两个小时。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，湖的两边开满了花。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天湖里的水结冰了。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个湖在山下，很多人去看。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在湖里游泳。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖有多大？", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "湖水", "label": "复合"}, {"form": "湖泊", "label": "复合"}], "register": "中性", "sense_fingerprint": "湖：比池塘大很多的大片水域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4949539b-d775-4702-b6ea-cac00b4ddf44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93445, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确答案。湖读作 hú，指陆地上比池塘大很多的大片水域。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ（第三声）与 hú（第二声）声调不同，虎的意思是老虎。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 hú（第二声）声调不同，呼的意思是呼喊或呼吸。"}, {"text": "户", "is_correct": false, "explanation": "hù（第四声）与 hú（第二声）声调不同，户的意思是门户或家庭。"}, {"text": "护", "is_correct": false, "explanation": "hù（第四声）与 hú（第二声）声调不同，护的意思是保护。"}], "explanations": {"湖": "正确答案。湖读作 hú，指陆地上比池塘大很多的大片水域。", "虎": "hǔ（第三声）与 hú（第二声）声调不同，虎的意思是老虎。", "呼": "hū（第一声）与 hú（第二声）声调不同，呼的意思是呼喊或呼吸。", "户": "hù（第四声）与 hú（第二声）声调不同，户的意思是门户或家庭。", "护": "hù（第四声）与 hú（第二声）声调不同，护的意思是保护。"}, "sentence_index": null, "correct_answer": "湖"}, "level_3": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确。“这个湖”指一片大水域，与“比池塘大多了”的比较相合。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子与池塘比较大小不合常理，句子说的是水域。"}, {"text": "人", "is_correct": false, "explanation": "搭配：“很大”形容体积，不能用来形容人。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间与池塘比较大小不合，“比池塘大”说的是水域的规模。"}], "explanations": {"湖": "正确。“这个湖”指一片大水域，与“比池塘大多了”的比较相合。", "房子": "语义：房子与池塘比较大小不合常理，句子说的是水域。", "人": "搭配：“很大”形容体积，不能用来形容人。", "房间": "语义：房间与池塘比较大小不合，“比池塘大”说的是水域的规模。"}, "sentence_index": 0, "correct_answer": "湖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在一只湖边散步。", "explanation": "这里应该用〈个〉。“只”多用于动物，不用于湖。"}, {"text": "这个湖很长，一直流到大海。", "explanation": "这里应该用〈河〉。湖是积聚不动的大片水域，不会“一直流到大海”；这是河的特点。"}, {"text": "这个湖的水可以用一个杯子装走。", "explanation": "这里应该用〈一杯水〉。湖是大片水域，不能用一个杯子装走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93445, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确答案。湖读作 hú，指比池塘大很多的大片水域。"}, {"text": "服", "is_correct": false, "explanation": "fú（第二声）与 hú 声母不同（f 与 h），服的意思是衣服或服从。"}, {"text": "扶", "is_correct": false, "explanation": "fú（第二声）与 hú 声母不同（f 与 h），扶的意思是扶着或搀扶。"}, {"text": "浮", "is_correct": false, "explanation": "fú（第二声）与 hú 声母不同（f 与 h），浮的意思是漂浮。"}], "explanations": {"湖": "正确答案。湖读作 hú，指比池塘大很多的大片水域。", "服": "fú（第二声）与 hú 声母不同（f 与 h），服的意思是衣服或服从。", "扶": "fú（第二声）与 hú 声母不同（f 与 h），扶的意思是扶着或搀扶。", "浮": "fú（第二声）与 hú 声母不同（f 与 h），浮的意思是漂浮。"}, "sentence_index": null, "correct_answer": "湖"}, "level_3": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确。“湖里的水”指湖中的水，冬天结冰符合湖的特点。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本里没有水，不能说“课本里的水结冰了”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机里一般不说水结冰，句子讲的是自然水域。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子里一般没有水，不能说“椅子里的水结冰了”。"}], "explanations": {"湖": "正确。“湖里的水”指湖中的水，冬天结冰符合湖的特点。", "课本": "语义：课本里没有水，不能说“课本里的水结冰了”。", "手机": "语义：手机里一般不说水结冰，句子讲的是自然水域。", "椅子": "语义：椅子里一般没有水，不能说“椅子里的水结冰了”。"}, "sentence_index": 6, "correct_answer": "湖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湖在草地上跑来跑去。", "explanation": "这里应该用〈动物〉。湖是静止的水域，不能做“跑来跑去”这种动作。"}, {"text": "路上的湖一会儿就干了。", "explanation": "这里应该用〈水坑〉。湖是持久的大片水域，不能说路上的积水一会儿就干了。"}, {"text": "这个湖在我的口袋里。", "explanation": "这里应该用〈一滴水〉。湖是大片水域，不能装在口袋里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块湖很大，我们在湖边坐了一个下午。", "corrected_sentence": "这个湖很大，我们在湖边坐了一个下午。", "error_description": "量词错误：“湖”应该用“个”（或“片”），“块”用于块状的东西，不用于湖。正确说法是“这个湖很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只湖很深，冬天的时候人们在上面滑冰。", "corrected_sentence": "这个湖很深，冬天的时候人们在上面滑冰。", "error_description": "量词错误：“湖”应该用“个”，“只”用于动物，不用于湖。正确说法是“这个湖很深”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
