INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "陆地上被陆地围着的大片积水区域。", "primary_collocate": null, "pronunciation": "hú", "ipa": "xu˧˥", "syllable_count": 1, "sentences": [{"text": "中国有很多大湖。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖在两座山中间。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖的四周都是树。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里有一个小岛，湖很蓝。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们开车绕着湖转了一圈。", "target_word": "湖", "complexity_tier": "T3", "furigana": "tā men kāi chē rào zhe hú zhuàn le yì quān.", "sentence_source": "generated"}, {"text": "地图上这个湖很大。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是中国最大的湖。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有一个湖，叫天池。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，很多鸟在湖上飞。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里的水来自山上的河。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "湖水", "label": "复合"}, {"form": "湖泊", "label": "复合"}], "register": "中性", "sense_fingerprint": "湖：被陆地围着的大片积水区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4949539b-d775-4702-b6ea-cac00b4ddf44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93446, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确答案。湖读作 hú，指陆地上被陆地围着的大片积水区域。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ（第三声）与 hú（第二声）声调不同，虎的意思是老虎。"}, {"text": "互", "is_correct": false, "explanation": "hù（第四声）与 hú（第二声）声调不同，互的意思是互相。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 hú（第二声）声调不同，呼的意思是呼喊。"}], "explanations": {"湖": "正确答案。湖读作 hú，指陆地上被陆地围着的大片积水区域。", "虎": "hǔ（第三声）与 hú（第二声）声调不同，虎的意思是老虎。", "互": "hù（第四声）与 hú（第二声）声调不同，互的意思是互相。", "呼": "hū（第一声）与 hú（第二声）声调不同，呼的意思是呼喊。"}, "sentence_index": null, "correct_answer": "湖"}, "level_3": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确。“大湖”指大片积水，中国有很多这样的湖。"}, {"text": "大脑", "is_correct": false, "explanation": "语义：“大脑”是人体器官，不能说“中国有很多大脑”。"}, {"text": "大洲", "is_correct": false, "explanation": "语义：“大洲”指亚洲、非洲等大陆，全世界只有几个，中国是国家而不是大洲，“中国有很多大洲”说不通。"}, {"text": "大手", "is_correct": false, "explanation": "搭配：“大手”一般修饰人的手，不与“中国有很多”这样指地理对象的说法搭配。"}], "explanations": {"湖": "正确。“大湖”指大片积水，中国有很多这样的湖。", "大脑": "语义：“大脑”是人体器官，不能说“中国有很多大脑”。", "大洲": "语义：“大洲”指亚洲、非洲等大陆，全世界只有几个，中国是国家而不是大洲，“中国有很多大洲”说不通。", "大手": "搭配：“大手”一般修饰人的手，不与“中国有很多”这样指地理对象的说法搭配。"}, "sentence_index": 0, "correct_answer": "湖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在一头湖边钓鱼。", "explanation": "这里应该用〈个〉。“头”多用于牲畜，不用于湖。"}, {"text": "这个湖的四周没有陆地，一望无际。", "explanation": "这里应该用〈海〉。湖是被陆地围着的水域，不能说四周没有陆地。"}, {"text": "湖水一直向东流。", "explanation": "这里应该用〈河〉。湖的水是积聚不动的，不说“一直向东流”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93446, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确答案。湖读作 hú，指被陆地围着的大片积水区域。"}, {"text": "福", "is_correct": false, "explanation": "fú（第二声）与 hú 声母不同（f 与 h），福的意思是福气。"}, {"text": "符", "is_correct": false, "explanation": "fú（第二声）与 hú 声母不同（f 与 h），符的意思是符号。"}, {"text": "伏", "is_correct": false, "explanation": "fú（第二声）与 hú 声母不同（f 与 h），伏的意思是趴下。"}], "explanations": {"湖": "正确答案。湖读作 hú，指被陆地围着的大片积水区域。", "福": "fú（第二声）与 hú 声母不同（f 与 h），福的意思是福气。", "符": "fú（第二声）与 hú 声母不同（f 与 h），符的意思是符号。", "伏": "fú（第二声）与 hú 声母不同（f 与 h），伏的意思是趴下。"}, "sentence_index": null, "correct_answer": "湖"}, "level_3": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确。“中国最大的湖”指规模最大的湖泊，与“最大”相合。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”不能用“最大”来比较地理规模，句子说的是湖。"}, {"text": "歌", "is_correct": false, "explanation": "语义：“歌”不是地理实体，不能说“中国最大的歌”。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”是器官，不作“中国最大的”这种地理范围的修饰对象。"}], "explanations": {"湖": "正确。“中国最大的湖”指规模最大的湖泊，与“最大”相合。", "饭": "语义：“饭”不能用“最大”来比较地理规模，句子说的是湖。", "歌": "语义：“歌”不是地理实体，不能说“中国最大的歌”。", "眼睛": "搭配：“眼睛”是器官，不作“中国最大的”这种地理范围的修饰对象。"}, "sentence_index": 6, "correct_answer": "湖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条湖的水一直流到山下。", "explanation": "这里应该用〈溪流〉。湖是积水的大片水域，不会一直流到山下。"}, {"text": "湖里涨潮了，岸边的船都漂起来了。", "explanation": "这里应该用〈海〉。涨潮是海水的现象，湖里没有潮汐。"}, {"text": "湖很薄，可以夹在书里。", "explanation": "这里应该用〈纸〉。湖是大片积水，不可能很薄、夹在书里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一条湖边钓了一个下午的鱼。", "corrected_sentence": "我们在湖边钓了一个下午的鱼。", "error_description": "量词错误：“湖”前不能加“一条”，“条”不用于湖。正确说法是“我们在湖边钓了一个下午的鱼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天去那位湖钓鱼。", "corrected_sentence": "我们明天去那个湖钓鱼。", "error_description": "量词错误：“湖”前应该用“个”，“位”用于人，不用于湖。正确说法是“我们明天去那个湖钓鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
