INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93447, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "即时是马上，不用等。", "primary_collocate": null, "pronunciation": "jí shí", "ipa": "tɕi˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "有问题请即时告诉我。", "target_word": "即时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "客人来了，服务员即时送上茶水。", "target_word": "即时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "收到短信后，他即时给我回了电话。", "target_word": "即时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机会即时提醒你明天的会议。", "target_word": "即时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师希望大家发现问题后即时反馈。", "target_word": "即时", "complexity_tier": "T3", "furigana": "jí shí", "sentence_source": "generated"}, {"text": "发现水管坏了，工人即时来修。", "target_word": "即时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛的结果会即时出现在屏幕上。", "target_word": "即时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件能即时把中文翻成英文，很方便。", "target_word": "即时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见朋友摔倒了，即时跑过去扶他。", "target_word": "即时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司会即时处理客户的投诉。", "target_word": "即时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "即时通讯", "label": "复合"}, {"form": "即时消息", "label": "复合"}], "register": "中性", "sense_fingerprint": "副词，表示事情一发生就马上做，中间不等待", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d689ef-f29c-47a1-838b-0acd26167009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93447, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "即时", "is_correct": true, "explanation": "正确：即时（jí shí）是马上、不等待的意思。"}, {"text": "集市", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，“集市”指定期的市场。"}, {"text": "基石", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，“基石”比喻基础。"}, {"text": "技师", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，shī（第一声）与 shí（第二声）也不同，“技师”指有技术的人。"}, {"text": "计时", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，“计时”指计算时间。"}], "explanations": {"即时": "正确：即时（jí shí）是马上、不等待的意思。", "集市": "shì（第四声）与 shí（第二声）声调不同，“集市”指定期的市场。", "基石": "jī（第一声）与 jí（第二声）声调不同，“基石”比喻基础。", "技师": "jì（第四声）与 jí（第二声）声调不同，shī（第一声）与 shí（第二声）也不同，“技师”指有技术的人。", "计时": "jì（第四声）与 jí（第二声）声调不同，“计时”指计算时间。"}, "sentence_index": null, "correct_answer": "即时"}, "level_3": {"options": [{"text": "即时", "is_correct": true, "explanation": "正确：“请即时告诉我”表示有问题一出现就马上说，符合句意。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过很久才发生，与“请”的催促语气不合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经完成，不能用于请人马上做的句子。"}, {"text": "遂", "is_correct": false, "explanation": "语域：“遂”是书面语，口语的请求中不自然。"}], "explanations": {"即时": "正确：“请即时告诉我”表示有问题一出现就马上说，符合句意。", "终于": "语义：“终于”表示经过很久才发生，与“请”的催促语气不合。", "已经": "语义：“已经”表示已经完成，不能用于请人马上做的句子。", "遂": "语域：“遂”是书面语，口语的请求中不自然。"}, "sentence_index": 0, "correct_answer": "即时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场雨来得很即时。", "explanation": "这里应该用〈及时〉。“来得及时”指正好赶上需要，“即时”指马上做，不用来描述时机。"}, {"text": "我即时住在朋友家。", "explanation": "这里应该用〈暂时〉。“暂时”指一段时间内的状态，“即时”指马上去做，不能用来说明住的时长。"}, {"text": "我们即时认识了十年。", "explanation": "这里应该用〈早就〉。“即时”指马上，与“认识了十年”的长时间矛盾，应说“早就认识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93447, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "即时", "is_correct": true, "explanation": "正确：即时（jí shí）是马上、不等待的意思。"}, {"text": "急事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，“急事”指紧急的事情。"}, {"text": "纪实", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，“纪实”指如实记录。"}, {"text": "记事", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，shì（第四声）与 shí（第二声）也不同，“记事”指记录事情。"}, {"text": "即使", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，“即使”表示假设或让步。"}], "explanations": {"即时": "正确：即时（jí shí）是马上、不等待的意思。", "急事": "shì（第四声）与 shí（第二声）声调不同，“急事”指紧急的事情。", "纪实": "jì（第四声）与 jí（第二声）声调不同，“纪实”指如实记录。", "记事": "jì（第四声）与 jí（第二声）声调不同，shì（第四声）与 shí（第二声）也不同，“记事”指记录事情。", "即使": "shǐ（第三声）与 shí（第二声）声调不同，“即使”表示假设或让步。"}, "sentence_index": null, "correct_answer": "即时"}, "level_3": {"options": [{"text": "即时", "is_correct": true, "explanation": "正确：“即时显示”表示结果一产生就马上出现，符合句意。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”指暗中进行，与在屏幕上公开显示的情形矛盾。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要求有人作主语，“结果”不能亲自出现。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”指有意为之，比赛结果不能故意出现。"}], "explanations": {"即时": "正确：“即时显示”表示结果一产生就马上出现，符合句意。", "偷偷": "语义：“偷偷”指暗中进行，与在屏幕上公开显示的情形矛盾。", "亲自": "搭配：“亲自”要求有人作主语，“结果”不能亲自出现。", "故意": "语义：“故意”指有意为之，比赛结果不能故意出现。"}, "sentence_index": 6, "correct_answer": "即时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项工程要在三个月内即时完成。", "explanation": "这里应该用〈逐步〉。“即时”指马上，与“三个月内”的期限不合，这类工程要逐步完成。"}, {"text": "这个问题我即时想了三天。", "explanation": "这里应该用〈一直〉。“即时”指马上，与“想了三天”的持续时间矛盾，应说“一直想”。"}, {"text": "这棵树要即时长大。", "explanation": "这里应该用〈慢慢〉。树长大要很长时间，“即时”指马上，不能用于这种逐渐发生的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他即时的赶过去扶起了孩子。", "corrected_sentence": "他即时赶过去扶起了孩子。", "error_description": "错误形式：“即时的赶过去”。正确形式：“即时赶过去”。“即时”是副词，直接修饰动词，后面不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司会即时得处理顾客的投诉。", "corrected_sentence": "公司会即时处理顾客的投诉。", "error_description": "错误形式：“即时得处理”。正确形式：“即时处理”。副词“即时”修饰动词时后面不能加“得”，应直接说“即时处理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "奖金是做得好时，得到的额外的钱。", "primary_collocate": null, "pronunciation": "jiǎng jīn", "ipa": "tɕjɑŋ˨˩˦ tɕin˥˥", "syllable_count": 2, "sentences": [{"text": "我这个月工作做得好，拿到了奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他东西卖得多，所以得到一笔奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用奖金给我买了新手机。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做得好的人，月底会有奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿了奖金，请大家吃饭。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月我多拿了两百元奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她努力工作，年底拿了很多奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "拿到奖金以后，我马上告诉了家人。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把奖金存进了银行。", "target_word": "奖金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这个月的奖金比上个月少。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔奖金", "label": "量词"}, {"form": "年终奖金", "label": "复合"}, {"form": "獎金", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工作做得好时额外拿到的钱，从得到的人角度说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df811bf5-9274-44e9-838a-6aef24dd96b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学费", "is_correct": false, "explanation": "语义：学费是学生交给学校的钱，与“工作做得好”无关。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的学习任务，与“工作做得好”不搭配。"}, {"text": "奖金", "is_correct": true, "explanation": "正确：“拿到奖金”指工作表现好而得到的额外的钱，符合语境。"}, {"text": "病假", "is_correct": false, "explanation": "搭配：病假是请假的时间，不说“拿到病假”。"}], "explanations": {"学费": "语义：学费是学生交给学校的钱，与“工作做得好”无关。", "作业": "语义：作业是学生的学习任务，与“工作做得好”不搭配。", "奖金": "正确：“拿到奖金”指工作表现好而得到的额外的钱，符合语境。", "病假": "搭配：病假是请假的时间，不说“拿到病假”。"}, "sentence_index": 0, "correct_answer": "奖金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板给他的奖金是一张表扬信。", "explanation": "这里应该用〈奖励〉。奖金只指钱，表扬信属于奖励，不能说成奖金。"}, {"text": "他违约了，要付一笔奖金。", "explanation": "这里应该用〈违约金〉。奖金是做得好时得到的钱，违约金是违约后要付给对方的钱，不能说“要付一笔奖金”。"}, {"text": "商家道歉后，他拿到了一笔奖金。", "explanation": "这里应该用〈赔偿〉（或〈退款〉）。奖金是因工作、成绩得到的奖励，因商家过失得到的钱不叫奖金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评", "is_correct": false, "explanation": "语义：努力工作的人不会得到批评，与“努力工作”的句意矛盾。"}, {"text": "工伤", "is_correct": false, "explanation": "搭配：工伤是工作中受的伤，不说“拿了很多工伤”。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：感冒是疾病，不能说“拿了很多感冒”。"}, {"text": "奖金", "is_correct": true, "explanation": "正确：“拿了很多奖金”指年底得到很多额外的钱，符合语境。"}], "explanations": {"批评": "语义：努力工作的人不会得到批评，与“努力工作”的句意矛盾。", "工伤": "搭配：工伤是工作中受的伤，不说“拿了很多工伤”。", "感冒": "搭配：感冒是疾病，不能说“拿了很多感冒”。", "奖金": "正确：“拿了很多奖金”指年底得到很多额外的钱，符合语境。"}, "sentence_index": 6, "correct_answer": "奖金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个学期都要交一笔奖金。", "explanation": "这里应该用〈学费〉。奖金是工作做得好时得到的钱，不是要交给学校的钱。"}, {"text": "他租房子时，交给房东一笔奖金。", "explanation": "这里应该用〈押金〉。奖金是奖励，不能用来指租房时交给房东的钱。"}, {"text": "车祸后，他拿到了一笔奖金。", "explanation": "这里应该用〈赔偿金〉。奖金是对工作表现的奖励，因车祸得到的钱叫赔偿金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个月拿到了一个奖金。", "corrected_sentence": "他这个月拿到了一笔奖金。", "error_description": "“奖金”前的量词应为“笔”，说“一笔奖金”；“个”不能用来计量钱款，这是学习者常见的量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年底，她终于拿了到奖金。", "corrected_sentence": "年底，她终于拿到了奖金。", "error_description": "“拿到”是动词加结果补语，“了”应放在“拿到”之后；“拿了到”把“了”插在补语前，属于补语与“了”的语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
