INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "作为奖励发给的钱。", "primary_collocate": null, "pronunciation": "jiǎng jīn", "ipa": "tɕjɑŋ˨˩˦ tɕin˥˥", "syllable_count": 2, "sentences": [{"text": "公司今天给大家发了奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板给每个人发了一笔奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "财务部下午会把奖金发给大家。", "target_word": "奖金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的奖金是五千元。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校给第一名的同学发奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每年年底都会发奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理已经把奖金放进了信封里。", "target_word": "奖金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛的奖金由主办方发给选手。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们在办公室门口排队领奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年发的奖金比去年多。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔奖金", "label": "量词"}, {"form": "年终奖金", "label": "复合"}, {"form": "獎金", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公司、学校、比赛主办方作为奖励发出的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df811bf5-9274-44e9-838a-6aef24dd96b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奖学金", "is_correct": false, "explanation": "语义：奖学金只发给在校学生，公司不会向员工发奖学金，与“公司给大家”不符。"}, {"text": "奖金", "is_correct": true, "explanation": "正确：“发奖金”指公司把钱作为奖励发给员工，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是老师布置给学生的学习任务，公司不会给大家发作业。"}, {"text": "病假", "is_correct": false, "explanation": "搭配：病假是请假的时间，只说“批准病假”，不说“发病假”。"}], "explanations": {"奖学金": "语义：奖学金只发给在校学生，公司不会向员工发奖学金，与“公司给大家”不符。", "奖金": "正确：“发奖金”指公司把钱作为奖励发给员工，符合句意。", "作业": "语义：作业是老师布置给学生的学习任务，公司不会给大家发作业。", "病假": "搭配：病假是请假的时间，只说“批准病假”，不说“发病假”。"}, "sentence_index": 0, "correct_answer": "奖金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的奖金是一台电视机。", "explanation": "这里应该用〈奖品〉。奖金指发的钱，实物奖励要用奖品，不能说奖金是一台电视机。"}, {"text": "他因为闯红灯，被交警处以一笔奖金。", "explanation": "这里应该用〈罚款〉。奖金是对做得好的人发的奖励，罚款是对违规的处罚，不能说“处以一笔奖金”。"}, {"text": "那位工人因为工伤，获得了一笔奖金。", "explanation": "这里应该用〈赔偿金〉。奖金是对工作或成绩的奖励，因工伤得到的钱叫赔偿金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱体积太大，装不进信封，句子不成立。"}, {"text": "奖金", "is_correct": true, "explanation": "正确：奖金是钱，可以装进信封，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子远比信封大，根本装不进去。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：友谊是抽象的情感，不能像物品一样“放进”信封。"}], "explanations": {"冰箱": "语义：冰箱体积太大，装不进信封，句子不成立。", "奖金": "正确：奖金是钱，可以装进信封，符合句意。", "房子": "语义：房子远比信封大，根本装不进去。", "友谊": "搭配：友谊是抽象的情感，不能像物品一样“放进”信封。"}, "sentence_index": 6, "correct_answer": "奖金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他租房子时交了一笔奖金。", "explanation": "这里应该用〈押金〉。奖金是对工作或成绩的奖励，不是租房时交给房东的钱。"}, {"text": "他每个学期都要交一笔奖金。", "explanation": "这里应该用〈学费〉。奖金是奖励，不是学生要交给学校的钱。"}, {"text": "他向银行借了一笔奖金。", "explanation": "这里应该用〈贷款〉。奖金是奖励，是发给人的钱，不是借来要还的钱，向银行借钱要说贷款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司给了我一个奖金。", "corrected_sentence": "公司给了我一笔奖金。", "error_description": "“奖金”前的量词应为“笔”，说“一笔奖金”；“个”不能用来计量钱款，这是学习者常见的量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司已经把奖金发了完。", "corrected_sentence": "公司已经把奖金发完了。", "error_description": "结果补语“完”应紧接动词，说“发完”，再加“了”；“发了完”把补语放错了位置，属于补语语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
