INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93457, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "又名是同一个东西的另一个名字。", "primary_collocate": null, "pronunciation": "yòu míng", "ipa": "joʊ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "西红柿又名番茄，可以做菜，也可以当水果吃。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆又名马铃薯，是常见的食物。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米又名苞米，北方人常这样叫。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "端午节又名端阳节，在五月初五。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西湖又名西子湖，风景很美。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向日葵又名朝阳花，总是朝着太阳。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菠萝又名凤梨，在南方很常见。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大黄鱼又名黄花鱼，肉很鲜。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说又名《少年的梦》。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山又名凤凰山，当地人常常这样叫。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "同一事物的另一个名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e6d86ab-0aec-443b-942c-15f3d782f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93457, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "又名", "is_correct": true, "explanation": "又名：表示同一种东西的另一个名字，与“番茄”指同一种蔬菜相符。"}, {"text": "学名", "is_correct": false, "explanation": "语义：“学名”指科学上统一规定的名称，番茄只是日常叫法，不是学名。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，与事物的命名无关，句意不通。"}, {"text": "全名", "is_correct": false, "explanation": "语义：“全名”指完整的名字，与“另一个名字”的语境不符。"}], "explanations": {"又名": "又名：表示同一种东西的另一个名字，与“番茄”指同一种蔬菜相符。", "学名": "语义：“学名”指科学上统一规定的名称，番茄只是日常叫法，不是学名。", "重量": "语义：“重量”指物体的轻重，与事物的命名无关，句意不通。", "全名": "语义：“全名”指完整的名字，与“另一个名字”的语境不符。"}, "sentence_index": 0, "correct_answer": "又名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他嫌自己的名字不好听，就又名了一次。", "explanation": "这里应该用〈改名〉。“又名”指同一个人的另一个名字，表示给自己换名字要说“改名”，不能说“又名了一次”。"}, {"text": "他因为这次演讲又名了，很多人都认识他。", "explanation": "这里应该用〈出名〉。“又名”指同一事物的另一个名字，表示名气变大要说“又出名”，不能说“又名了”。"}, {"text": "同学们给他起了又名，叫他“小胖”。", "explanation": "这里应该用〈外号〉。又名是正式的另一个名字，私下给人起的绰号要用外号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93457, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "又名", "is_correct": true, "explanation": "又名：表示同一种水果的另一个名字，与“凤梨”指同一种植物相符。"}, {"text": "品种", "is_correct": false, "explanation": "语义：菠萝和凤梨是同一种水果，“品种”指同类中的不同种类，与此语境不符。"}, {"text": "类型", "is_correct": false, "explanation": "语义：“类型”指事物的类别，菠萝与凤梨并不是两个类别。"}, {"text": "绰号", "is_correct": false, "explanation": "搭配：“绰号”多用来称呼人，不用来说水果的另一个名字。"}], "explanations": {"又名": "又名：表示同一种水果的另一个名字，与“凤梨”指同一种植物相符。", "品种": "语义：菠萝和凤梨是同一种水果，“品种”指同类中的不同种类，与此语境不符。", "类型": "语义：“类型”指事物的类别，菠萝与凤梨并不是两个类别。", "绰号": "搭配：“绰号”多用来称呼人，不用来说水果的另一个名字。"}, "sentence_index": 6, "correct_answer": "又名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的又名是经理，负责公司的业务。", "explanation": "这里应该用〈职务〉。又名指另一个名称，不能用来说明职务。"}, {"text": "他的又名是十八岁，还在上高中。", "explanation": "这里应该用〈年龄〉。“又名”指另一个名字，说明人的岁数要用年龄，不能说“又名是十八岁”。"}, {"text": "他获得了“最佳员工”的又名。", "explanation": "这里应该用〈称号〉。又名指同一事物的另一个名字，荣誉头衔要用称号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种花又名了三色堇，颜色很鲜艳。", "corrected_sentence": "这种花又名三色堇，颜色很鲜艳。", "error_description": "“又名”后面不能加“了”。应说“这种花又名三色堇”，“了”不能接在“又名”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座湖很又名青湖，风景很美。", "corrected_sentence": "这座湖又名青湖，风景很美。", "error_description": "“很”不能放在“又名”前面。应说“这座湖又名青湖”，“很”只用于修饰形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
