INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93458, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "除本名以外的另一个名称。", "primary_collocate": null, "pronunciation": "yòu míng", "ipa": "joʊ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他本名叫王平，又名王小平。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周树人又名鲁迅，是有名的作家。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子本名叫东河，又名小桥村。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店本名叫“好运来”，又名“老王面馆”。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的本名叫王军，又名大军，同事们都这样称呼他。", "target_word": "又名", "complexity_tier": "T3", "furigana": "tā de běnmíng jiào Wáng Jūn, yòu míng Dà Jūn, tóngshìmen dōu zhèyàng chēnghu tā.", "sentence_source": "generated"}, {"text": "她本名叫林雪，又名小雪。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河本名叫清水河，又名小溪河。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书本名叫《春天》，又名《新的开始》。", "target_word": "又名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学生本名李强，又名小强，老师点名时也这样叫他。", "target_word": "又名", "complexity_tier": "T3", "furigana": "zhè wèi xuéshēng běnmíng Lǐ Qiáng, yòu míng Xiǎo Qiáng, lǎoshī diǎnmíng shí yě zhèyàng jiào tā.", "sentence_source": "generated"}, {"text": "这座城市本名青城，又名绿城，市民常这样叫它。", "target_word": "又名", "complexity_tier": "T3", "furigana": "zhè zuò chéngshì běnmíng Qīngchéng, yòu míng Lǜchéng, shìmín cháng zhèyàng jiào tā.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "本名之外的另一个名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e6d86ab-0aec-443b-942c-15f3d782f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "又名", "is_correct": true, "explanation": "又名：表示同一个人的另一个名字，与前面的“本名”形成对照。"}, {"text": "学号", "is_correct": false, "explanation": "语义：“学号”是学生的编号，不是人名，与“王小平”不能并列。"}, {"text": "籍贯", "is_correct": false, "explanation": "语义：“籍贯”指祖籍所在地，不是名字，与此语境不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”后面不能接人名，不能用来指另一个名字。"}], "explanations": {"又名": "又名：表示同一个人的另一个名字，与前面的“本名”形成对照。", "学号": "语义：“学号”是学生的编号，不是人名，与“王小平”不能并列。", "籍贯": "语义：“籍贯”指祖籍所在地，不是名字，与此语境不符。", "年龄": "搭配：“年龄”后面不能接人名，不能用来指另一个名字。"}, "sentence_index": 0, "correct_answer": "又名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛他的又名是第二。", "explanation": "这里应该用〈名次〉。“又名”指同一事物的另一个名称，比赛的排位要用名次，不能说“又名是第二”。"}, {"text": "他因为这次比赛又名了，大家都认识他。", "explanation": "这里应该用〈出名〉。“又名”指另一个名字，表示名气变大要说“又出名”，不能说“又名了”。"}, {"text": "她拿到了“优秀教师”的又名。", "explanation": "这里应该用〈称号〉。“又名”指同一个人的另一个名字，荣誉头衔要用称号，不能说“的又名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "又名", "is_correct": true, "explanation": "又名：表示同一条河的另一个名字，与“清水河”形成对照。"}, {"text": "河源", "is_correct": false, "explanation": "语义：“河源”指河流的发源地，不是河的名字，与此语境不符。"}, {"text": "河宽", "is_correct": false, "explanation": "体貌：“河宽”描述河面的宽窄，是外形特征，不能用来指另一个名字。"}, {"text": "河床", "is_correct": false, "explanation": "搭配：“河床”是河底的地面，不能用来称呼这条河。"}], "explanations": {"又名": "又名：表示同一条河的另一个名字，与“清水河”形成对照。", "河源": "语义：“河源”指河流的发源地，不是河的名字，与此语境不符。", "河宽": "体貌：“河宽”描述河面的宽窄，是外形特征，不能用来指另一个名字。", "河床": "搭配：“河床”是河底的地面，不能用来称呼这条河。"}, "sentence_index": 6, "correct_answer": "又名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的又名是经理，负责公司的业务。", "explanation": "这里应该用〈职务〉。又名指另一个名称，不能用来说明职务。"}, {"text": "这件衣服的又名是三百元。", "explanation": "这里应该用〈价格〉。“又名”指事物的另一个名称，衣服的价钱要用价格，不能说“又名是三百元”。"}, {"text": "这批货物的又名是A103。", "explanation": "这里应该用〈编号〉。又名是事物的另一个名称，货物的代码要用编号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书又名了《海上》，很受欢迎。", "corrected_sentence": "这本书又名《海上》，很受欢迎。", "error_description": "“了”不能加在“又名”后面。应说“这本书又名《海上》”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座公园很又名青园，夏天很多人来散步。", "corrected_sentence": "这座公园又名青园，夏天很多人来散步。", "error_description": "“很”不能放在“又名”前面。应说“这座公园又名青园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
