INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书籍或文件中按顺序排列的篇章名称及页码清单。", "primary_collocate": null, "pronunciation": "mù lù", "ipa": "mu˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这份报告的目录有两页。", "target_word": "目录", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把报告的目录打印出来。", "target_word": "目录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书的目录很清楚，一找就到。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "论文的目录要写清楚每一章的页码。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在合同的目录里找到了付款条款。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理要求每份计划书都要加上目录。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本杂志的目录按栏目排列。", "target_word": "目录", "complexity_tier": "T3", "furigana": "mù lù", "sentence_source": "generated"}, {"text": "文章太长，最好先做一个目录。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他核对了目录和正文的页码。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本词典的目录写着每个部分的名称。", "target_word": "目录", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份目录", "label": "量词搭配"}, {"form": "目录页", "label": "复合词"}, {"form": "目錄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "报告、论文、说明书等按顺序列出篇章名称和页码的清单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a469138-6fb8-45ff-8b3c-19ee085e4330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93460, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "目录", "is_correct": true, "explanation": "目录（mù lù）：报告、论文等按顺序列出篇章名称和页码的清单。"}, {"text": "母鹿", "is_correct": false, "explanation": "mǔ（第三声）与 mù（第四声）声调不同，母鹿指雌性的鹿，不是报告中的目录。"}, {"text": "附录", "is_correct": false, "explanation": "fù（第四声）与 mù（第四声）声母不同，附录指附在报告后的补充材料。"}, {"text": "木炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，木炉指木制的炉子。"}], "explanations": {"目录": "目录（mù lù）：报告、论文等按顺序列出篇章名称和页码的清单。", "母鹿": "mǔ（第三声）与 mù（第四声）声调不同，母鹿指雌性的鹿，不是报告中的目录。", "附录": "fù（第四声）与 mù（第四声）声母不同，附录指附在报告后的补充材料。", "木炉": "lú（第二声）与 lù（第四声）声调不同，木炉指木制的炉子。"}, "sentence_index": null, "correct_answer": "目录"}, "level_3": {"options": [{"text": "目录", "is_correct": true, "explanation": "目录：报告中按顺序列出篇章和页码的清单，可以数出两页。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“页”是量词，不能用来计量“性格”，“性格有两页”不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不是纸质文件，没有页数可言。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不是文件内容，不会分成两页。"}], "explanations": {"目录": "目录：报告中按顺序列出篇章和页码的清单，可以数出两页。", "性格": "搭配：“页”是量词，不能用来计量“性格”，“性格有两页”不通。", "咖啡": "语义：咖啡不是纸质文件，没有页数可言。", "星星": "语义：星星不是文件内容，不会分成两页。"}, "sentence_index": 0, "correct_answer": "目录"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "论文的目录写在最前面，只有几百字。", "explanation": "这里应该用〈摘要〉。目录只列篇章名称和页码，不写几百字的内容概要。"}, {"text": "这份报告的目录里附有每个图表的详细说明。", "explanation": "这里应该用〈附录〉。目录只列篇章名称和页码，不写图表说明。"}, {"text": "这份报告有三根目录，很清楚。", "explanation": "这里量词不对。目录用〈份〉，〈根〉用于细长的东西，不能用于目录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93460, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "目录", "is_correct": true, "explanation": "目录（mù lù）：报告、论文等按顺序列出篇章名称和页码的清单。"}, {"text": "牡鹿", "is_correct": false, "explanation": "mǔ（第三声）与 mù（第四声）声调不同，牡鹿指雄性的鹿，不是报告中的目录。"}, {"text": "木橹", "is_correct": false, "explanation": "lǔ（第三声）与 lù（第四声）声调不同，木橹指划船用的木桨。"}, {"text": "木楼", "is_correct": false, "explanation": "lóu（第二声）与 lù（第四声）韵母与声调都不同，木楼指木制的楼房，与报告无关。"}], "explanations": {"目录": "目录（mù lù）：报告、论文等按顺序列出篇章名称和页码的清单。", "牡鹿": "mǔ（第三声）与 mù（第四声）声调不同，牡鹿指雄性的鹿，不是报告中的目录。", "木橹": "lǔ（第三声）与 lù（第四声）声调不同，木橹指划船用的木桨。", "木楼": "lóu（第二声）与 lù（第四声）韵母与声调都不同，木楼指木制的楼房，与报告无关。"}, "sentence_index": null, "correct_answer": "目录"}, "level_3": {"options": [{"text": "目录", "is_correct": true, "explanation": "目录：按顺序列出篇章名称和页码的清单，可以按栏目编排。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是数额，不是篇章，不能按栏目排列。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“按……排列”搭配的是内容或次序，“颜色”不这样说。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是穿戴物，不是印刷内容，无法按栏目排列。"}], "explanations": {"目录": "目录：按顺序列出篇章名称和页码的清单，可以按栏目编排。", "价格": "语义：价格是数额，不是篇章，不能按栏目排列。", "颜色": "搭配：“按……排列”搭配的是内容或次序，“颜色”不这样说。", "鞋子": "语义：鞋子是穿戴物，不是印刷内容，无法按栏目排列。"}, "sentence_index": 6, "correct_answer": "目录"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本词典的目录里写着每个词的读音、意思和例句。", "explanation": "这里应该用〈词条〉。目录只列各部分名称和页码，不写每个词的读音、意思和例句。"}, {"text": "这本词典的目录里收了一百多个常用词。", "explanation": "这里应该用〈词表〉。目录只列各部分名称和页码，不收录词语。"}, {"text": "这本词典有一台目录。", "explanation": "这里量词不对。目录用〈份〉或〈本〉，〈台〉用于机器，不用于目录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看了一根目录，很快找到了第三章。", "corrected_sentence": "我看了一份目录，很快找到了第三章。", "error_description": "量词错误：“目录”应用“份”计量，“根”用于细长的东西，不能说“一根目录”；应说“一份目录”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一扇目录整理好了。", "corrected_sentence": "他把一份目录整理好了。", "error_description": "量词错误：“目录”应用“份”，“扇”用于门窗，不能用于目录。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
