INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93468, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "刻录有声音、可用唱机播放的圆盘。", "primary_collocate": null, "pronunciation": "chàng piàn", "ipa": "tʂʰɑŋ˥˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这张唱片要用唱机来播放。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张唱片的声音很温暖。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最喜欢收集老唱片。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手新出了一张唱片。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱片上刻着一圈细细的纹路。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把唱片放回封套里。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把唱片放到唱机上。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张唱片已经卖完了。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手在我的唱片上签了名。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱片掉在地上，裂开了。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "黑胶唱片", "label": "复合"}], "register": "中性", "sense_fingerprint": "刻录有声音、可用唱机播放的圆盘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d689ef-f29c-47a1-838b-0acd26167009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱片", "is_correct": true, "explanation": "正确：唱片能用唱机播放，量词“张”也对，句子通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能用唱机播放。"}, {"text": "画", "is_correct": false, "explanation": "语义：画是给人看的，不能用唱机播放。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”的量词是“本”，不说“这张书”；而且书也不能用唱机播放。"}], "explanations": {"唱片": "正确：唱片能用唱机播放，量词“张”也对，句子通顺。", "桌子": "语义：桌子是家具，不能用唱机播放。", "画": "语义：画是给人看的，不能用唱机播放。", "书": "搭配：“书”的量词是“本”，不说“这张书”；而且书也不能用唱机播放。"}, "sentence_index": 0, "correct_answer": "唱片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手新出了一本唱片。", "explanation": "这里应该用〈张〉。“本”用于书籍，唱片要用“张”来数。"}, {"text": "我昨天买了两只唱片。", "explanation": "这里应该用〈张〉。“只”不用于唱片，唱片的量词是“张”。"}, {"text": "爸爸送了我一台唱片。", "explanation": "这里应该用〈张〉。“台”用于机器，唱片要用“张”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱片", "is_correct": true, "explanation": "正确：“放到唱机上”的是唱片，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，不能放到唱机上。"}, {"text": "思想", "is_correct": false, "explanation": "配价：“放”要求具体的物体作宾语，“思想”是抽象的，不能放。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“把……放到”搭配具体的物体，不说把声音放到唱机上。"}], "explanations": {"唱片": "正确：“放到唱机上”的是唱片，符合句意。", "空气": "语义：空气看不见摸不着，不能放到唱机上。", "思想": "配价：“放”要求具体的物体作宾语，“思想”是抽象的，不能放。", "声音": "搭配：“把……放到”搭配具体的物体，不说把声音放到唱机上。"}, "sentence_index": 6, "correct_answer": "唱片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用这张唱片扇风。", "explanation": "这里应该用〈扇子〉。唱片是圆盘，不能扇风，扇风要用扇子。"}, {"text": "我用这张唱片看了一部电影。", "explanation": "这里应该用〈影碟〉。唱片只放声音，看电影要用影碟。"}, {"text": "我把论文存在这张唱片里。", "explanation": "这里应该用〈磁盘〉。唱片是音乐载体，不能存文件，存论文要用磁盘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸的每个唱片都要用唱机播放。", "corrected_sentence": "爸爸的每张唱片都要用唱机播放。", "error_description": "错误形式：“每个唱片”。正确形式：“每张唱片”。“唱片”的量词是“张”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "唱片从桌上掉下来，裂了开。", "corrected_sentence": "唱片从桌上掉下来，裂开了。", "error_description": "错误形式：“裂了开”。正确形式：“裂开了”。“裂开”是动词加补语的固定结构，不能把“了”插进中间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗", "is_correct": true, "explanation": "“粗”与“精”（做工细致）相对，指做工粗糙、不细致。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”与“精”没有反义关系，不能用来与做工的精细相对。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”与“精”没有反义关系，句中说的是做工，不是重量。"}, {"text": "暖", "is_correct": false, "explanation": "“暖”与“精”没有反义关系，不能用来评价做工。"}], "correct_answer": "粗", "explanations": {"粗": "“粗”与“精”（做工细致）相对，指做工粗糙、不细致。", "慢": "“慢”与“精”没有反义关系，不能用来与做工的精细相对。", "轻": "“轻”与“精”没有反义关系，句中说的是做工，不是重量。", "暖": "“暖”与“精”没有反义关系，不能用来评价做工。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗", "is_correct": true, "explanation": "“粗”与“精”（做工细致）相对，指做工粗糙、不细致。"}, {"text": "远", "is_correct": false, "explanation": "“远”与“精”没有反义关系，不能用来形容做工。"}, {"text": "深", "is_correct": false, "explanation": "“深”与“精”没有反义关系，不能用来与做工相对。"}, {"text": "热", "is_correct": false, "explanation": "“热”与“精”没有反义关系，与此词的意思无关。"}], "correct_answer": "粗", "explanations": {"粗": "“粗”与“精”（做工细致）相对，指做工粗糙、不细致。", "远": "“远”与“精”没有反义关系，不能用来形容做工。", "深": "“深”与“精”没有反义关系，不能用来与做工相对。", "热": "“热”与“精”没有反义关系，与此词的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "精是做工、手艺细致讲究，一点都不马虎。", "primary_collocate": null, "pronunciation": "jīng", "ipa": "tɕiŋ˥", "syllable_count": 1, "sentences": [{"text": "这件衣服的做工很精。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手艺很精，做得一点不马虎。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画画得很精。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶绣的花又细又精。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅干活儿很精，从不出错。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套茶具做得真精。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他切菜的刀工特别精。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个模型的零件拼得很精，连缝隙都看不出来。", "target_word": "精", "complexity_tier": "T3", "furigana": "zhè ge mó xíng de líng jiàn pīn de hěn jīng, lián fèng xì dōu kàn bù chū lái.", "sentence_source": "generated"}, {"text": "这个表修得很精，一点毛病也没有。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这活儿干得精，客人都很满意。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精细", "label": "复合"}], "register": "口语", "sense_fingerprint": "做工、手艺细致讲究，不马虎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab46821f-b651-4563-9f21-fba4344ba828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精", "is_correct": true, "explanation": "精（jīng）指做工细致、不马虎，正是本词的意思。"}, {"text": "静", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是安静。"}, {"text": "景", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是风景。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。"}, {"text": "星", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是星星。"}], "explanations": {"精": "精（jīng）指做工细致、不马虎，正是本词的意思。", "静": "jìng（第四声）与 jīng（第一声）声调不同，意思是安静。", "景": "jǐng（第三声）与 jīng（第一声）声调不同，意思是风景。", "金": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。", "星": "xīng 与 jīng 声母不同（x 与 j），意思是星星。"}, "sentence_index": null, "correct_answer": "精"}, "level_3": {"options": [{"text": "精", "is_correct": true, "explanation": "“精”指做工细致、不马虎，正好描述“做工”。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”说厚度，不能用来评价做工是否细致。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线或颜色，与做工是否细致无关。"}, {"text": "大", "is_correct": false, "explanation": "体貌：“大”说体积，不能用来评价做工是否细致。"}], "explanations": {"精": "“精”指做工细致、不马虎，正好描述“做工”。", "厚": "搭配：“厚”说厚度，不能用来评价做工是否细致。", "亮": "语义：“亮”说光线或颜色，与做工是否细致无关。", "大": "体貌：“大”说体积，不能用来评价做工是否细致。"}, "sentence_index": 0, "correct_answer": "精"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市很精，晚上的灯光特别好看。", "explanation": "这里应该用〈美丽〉。“精”形容做工或技艺细致，不用来形容城市的样子，形容景色要用美丽。"}, {"text": "这朵花的颜色很精。", "explanation": "这里应该用〈漂亮〉。“精”说做工细致，不说颜色好看，形容颜色要用漂亮。"}, {"text": "今天的天气很精，适合去公园散步。", "explanation": "这里应该用〈晴朗〉。“精”形容做工或技艺细致，不用来形容天气，形容天气好要用晴朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "精", "is_correct": true, "explanation": "精（jīng）指做工细致、不马虎，正是本词的意思。"}, {"text": "净", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是干净。"}, {"text": "井", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。"}, {"text": "兴", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是兴旺。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。"}, {"text": "轻", "is_correct": false, "explanation": "qīng 与 jīng 声母不同（q 与 j），声调相同，意思是轻重的轻。"}], "explanations": {"精": "精（jīng）指做工细致、不马虎，正是本词的意思。", "净": "jìng（第四声）与 jīng（第一声）声调不同，意思是干净。", "井": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。", "兴": "xīng 与 jīng 声母不同（x 与 j），意思是兴旺。", "金": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。", "轻": "qīng 与 jīng 声母不同（q 与 j），声调相同，意思是轻重的轻。"}, "sentence_index": null, "correct_answer": "精"}, "level_3": {"options": [{"text": "精", "is_correct": true, "explanation": "“精”指做工细致、不马虎，符合“刀工”的语境。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地，不能用来评价刀工。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”说距离，与刀工的水平无关。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”说宽度或空间，不能用来形容刀工。"}], "explanations": {"精": "“精”指做工细致、不马虎，符合“刀工”的语境。", "软": "搭配：“软”说质地，不能用来评价刀工。", "远": "语义：“远”说距离，与刀工的水平无关。", "窄": "搭配：“窄”说宽度或空间，不能用来形容刀工。"}, "sentence_index": 6, "correct_answer": "精"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件东西很精，只要十块钱。", "explanation": "这里应该用〈便宜〉。“精”形容做工或技艺细致，不用来说价格，说价格低要用便宜。"}, {"text": "这间屋子很精，夏天住着很舒服。", "explanation": "这里应该用〈凉快〉。“精”形容做工细致，不用来形容屋子的温度，这里要用凉快。"}, {"text": "这辆车很精，一小时能开一百公里。", "explanation": "这里应该用〈快〉。“精”形容人精明或做工细致，不用来形容车的速度，形容车快要用快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件家具做很精。", "corrected_sentence": "这件家具做得很精。", "error_description": "“做很精”漏掉了补语标记“得”，应说“做得很精”。形容做的结果怎样，要用“动词＋得＋形容词”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做的木雕比我最精，连纹路都清清楚楚。", "corrected_sentence": "他做的木雕比我精，连纹路都清清楚楚。", "error_description": "错误在“最”：“比”字句已经表示比较，不能再用“最”，应说“比我精”；要强调程度可用“更”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93474, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糊涂", "is_correct": true, "explanation": "“糊涂”与“精明”相反，指不明事理、不会算计。"}, {"text": "远", "is_correct": false, "explanation": "“远”与“精”没有反义关系，不能与精明相对。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”与“精”没有反义关系，不能与精明相对。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”与“精”没有反义关系，说的是光线。"}], "correct_answer": "糊涂", "explanations": {"糊涂": "“糊涂”与“精明”相反，指不明事理、不会算计。", "远": "“远”与“精”没有反义关系，不能与精明相对。", "厚": "“厚”与“精”没有反义关系，不能与精明相对。", "亮": "“亮”与“精”没有反义关系，说的是光线。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
