INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93474, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "精明会算；在某方面技艺纯熟、优秀。", "primary_collocate": null, "pronunciation": "jīng", "ipa": "tɕiŋ˥", "syllable_count": 1, "sentences": [{"text": "他做生意很精，从不吃亏。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人精得很，很难骗到他。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买东西特别精，总能买到便宜的。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在钱上很精，一分钱也算得清。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这方面比我精多了。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈很精，菜价她都记得。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别看他年轻，其实精得很。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下棋比我精，我总是输。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张的手艺很精，大家都找他。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这孩子从小就精，什么事都瞒不过他。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精明", "label": "复合"}], "register": "口语", "sense_fingerprint": "精明会算；在某方面技艺熟练", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab46821f-b651-4563-9f21-fba4344ba828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93474, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精", "is_correct": true, "explanation": "精（jīng）指精明会算，或在某方面技艺熟练，正是本词的意思。"}, {"text": "净", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是干净。"}, {"text": "井", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。"}, {"text": "兴", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是兴旺。"}, {"text": "轻", "is_correct": false, "explanation": "qīng 与 jīng 声母不同（q 与 j），声调相同，意思是轻重的轻。"}], "explanations": {"精": "精（jīng）指精明会算，或在某方面技艺熟练，正是本词的意思。", "净": "jìng（第四声）与 jīng（第一声）声调不同，意思是干净。", "井": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。", "金": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。", "兴": "xīng 与 jīng 声母不同（x 与 j），意思是兴旺。", "轻": "qīng 与 jīng 声母不同（q 与 j），声调相同，意思是轻重的轻。"}, "sentence_index": null, "correct_answer": "精"}, "level_3": {"options": [{"text": "精", "is_correct": true, "explanation": "“精”指精明会算，符合“做生意”的语境。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地，不能用来形容做生意。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”说身形，不能用来形容做生意。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”说身高，与做生意无关。"}], "explanations": {"精": "“精”指精明会算，符合“做生意”的语境。", "软": "搭配：“软”说质地，不能用来形容做生意。", "瘦": "体貌：“瘦”说身形，不能用来形容做生意。", "矮": "体貌：“矮”说身高，与做生意无关。"}, "sentence_index": 0, "correct_answer": "精"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身体很精，每天都能跑步。", "explanation": "这里应该用〈健康〉。“精”形容人精明或技艺熟练，不用来形容身体状况，要用健康。"}, {"text": "教室里很精，大家都在认真读书。", "explanation": "这里应该用〈安静〉。“精”形容人精明或技艺熟练，不用来形容教室的状态，要用安静。"}, {"text": "这场雨很精，下了一整天。", "explanation": "这里应该用〈大〉。“精”形容人的精明或技艺纯熟，不用来形容雨的大小，要用“大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93474, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "精", "is_correct": true, "explanation": "精（jīng）指精明会算，或在某方面技艺熟练，正是本词的意思。"}, {"text": "静", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是安静。"}, {"text": "景", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是风景。"}, {"text": "星", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是星星。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。"}], "explanations": {"精": "精（jīng）指精明会算，或在某方面技艺熟练，正是本词的意思。", "静": "jìng（第四声）与 jīng（第一声）声调不同，意思是安静。", "景": "jǐng（第三声）与 jīng（第一声）声调不同，意思是风景。", "星": "xīng 与 jīng 声母不同（x 与 j），意思是星星。", "金": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。"}, "sentence_index": null, "correct_answer": "精"}, "level_3": {"options": [{"text": "精", "is_correct": true, "explanation": "“精”指精明会算，符合“其实……得很”的语境。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”说水分，与人的精明程度无关。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”说空间或宽度，不能用来形容人。"}, {"text": "扁", "is_correct": false, "explanation": "体貌：“扁”说形状，不能用来形容人的状态。"}], "explanations": {"精": "“精”指精明会算，符合“其实……得很”的语境。", "湿": "语义：“湿”说水分，与人的精明程度无关。", "窄": "搭配：“窄”说空间或宽度，不能用来形容人。", "扁": "体貌：“扁”说形状，不能用来形容人的状态。"}, "sentence_index": 6, "correct_answer": "精"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个广场很精，走一圈要一个小时。", "explanation": "这里应该用〈宽阔〉。“精”形容人精明或技艺熟练，不用来形容场地的大小，要用宽阔。"}, {"text": "我的家乡很精，坐飞机要三天。", "explanation": "这里应该用〈遥远〉。“精”不用来形容距离，形容距离远要用遥远。"}, {"text": "这个西瓜很精，只要两块钱一斤。", "explanation": "这里应该用〈便宜〉。“精”形容人精明或技艺熟练，不用来说价格，说价格低要用便宜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他算账算很精，一分钱也不差。", "corrected_sentence": "他算账算得很精，一分钱也不差。", "error_description": "“算很精”漏掉了补语标记“得”，应说“算得很精”，表示算的结果精明。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个很精生意人，谁都占不到便宜。", "corrected_sentence": "他是个很精的生意人，谁都占不到便宜。", "error_description": "漏掉了定语标记“的”，应说“很精的生意人”。形容词修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
