INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93475, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国别是说这是哪个国家的。", "primary_collocate": null, "pronunciation": "guó bié", "ipa": "kwɔ˧˥ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "请在表格里写上你的国别。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些电影的国别各不相同。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里的书按国别排好了。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们的国别是什么？", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛名单上有名字和国别。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张票上没写国别。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢看不同国别的电影。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让来自不同国别的同学分开坐。", "target_word": "国别", "complexity_tier": "T3", "furigana": "lǎoshī ràng láizì bùtóng guóbié de tóngxué fēnkāi zuò", "sentence_source": "generated"}, {"text": "这家店卖不同国别的茶。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表上的国别那一栏是空的。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "国别：某人或某物属于哪个国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1016e2b9-ce54-4dd3-a2ce-4913bc82850b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93475, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：表格要的是个人信息，天气不能作为写上去的个人信息。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：表格上一般不要求填写脾气，“写上你的脾气”不合句意。"}, {"text": "字迹", "is_correct": false, "explanation": "搭配：“写上”的宾语应是要写的内容，“字迹”是写出来的结果，不能被写上。"}, {"text": "国别", "is_correct": true, "explanation": "国别指某人或某物属于哪个国家，正是表格要求填写的内容。"}], "explanations": {"天气": "语义：表格要的是个人信息，天气不能作为写上去的个人信息。", "脾气": "语义：表格上一般不要求填写脾气，“写上你的脾气”不合句意。", "字迹": "搭配：“写上”的宾语应是要写的内容，“字迹”是写出来的结果，不能被写上。", "国别": "国别指某人或某物属于哪个国家，正是表格要求填写的内容。"}, "sentence_index": 0, "correct_answer": "国别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿到了美国国别。", "explanation": "这里应该用〈国籍〉。国籍是法律上的国家身份，可以“拿到”；国别只是说明所属国家的类别，不能这样说。"}, {"text": "我去了三个国别旅行。", "explanation": "这里应该用〈国家〉。国别不指具体的国家，不能用来计数，也不能作为旅行的地点。"}, {"text": "他是一名中国国别。", "explanation": "这里应该用〈国民〉。国别是说明“属于哪个国家”的类别，不是指人的名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93475, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“不同颜色的电影”说的是颜色，不是电影所属的国家，句意不符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：电影没有味道，“不同味道的电影”讲不通。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”多用于饮食，不能说“不同口味的电影”。"}, {"text": "国别", "is_correct": true, "explanation": "国别指所属的国家，“不同国别的电影”指来自不同国家的电影，符合句意。"}], "explanations": {"颜色": "语义：“不同颜色的电影”说的是颜色，不是电影所属的国家，句意不符。", "味道": "语义：电影没有味道，“不同味道的电影”讲不通。", "口味": "搭配：“口味”多用于饮食，不能说“不同口味的电影”。", "国别": "国别指所属的国家，“不同国别的电影”指来自不同国家的电影，符合句意。"}, "sentence_index": 6, "correct_answer": "国别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他越过了国别。", "explanation": "这里应该用〈国界〉。越过的是国家之间的界线；国别只说明所属国家，不是地理边界，不能被越过。"}, {"text": "我家的国别在北京。", "explanation": "这里应该用〈地址〉。国别说明所属国家，不能用来说明住在什么地方。"}, {"text": "他的国别是汉族。", "explanation": "这里应该用〈民族〉。汉族是民族，国别指国家所属的类别，两者不能混用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位选手国别是什么？", "corrected_sentence": "这位选手的国别是什么？", "error_description": "结构错误：定语“选手”与中心语“国别”之间要用“的”连接，应写作“选手的国别”，漏掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些国别们都不同。", "corrected_sentence": "这些国别都不同。", "error_description": "“们”用法错误：“们”只加在指人的名词或代词后面，“国别”是抽象名词，不能加“们”，应写作“这些国别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
