INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93479, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93479, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国书是一个国家写给另一个国家的重要信。", "primary_collocate": null, "pronunciation": "guó shū", "ipa": "kwɔ˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "国书是一个国家写给另一个国家的信。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统把国书交给了对方的外交官。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封国书写得很正式，用词也很客气。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国关系很好，国书里写了不少好话。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上读了那封国书。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国书要用最正式的语言来写。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份国书会由大使亲自送去。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一封一百年前的国书。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国书上有国王的名字和印章。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方收到国书后，很快就回信了。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词，国与国之间往来的正式重要信件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c11b62-a391-4e78-aa2c-8e0c8aef0aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93479, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国书", "is_correct": true, "explanation": "正确答案。国书（guó shū）指国家之间递交的正式文书。"}, {"text": "果蔬", "is_correct": false, "explanation": "guǒ（第三声）与 guó（第二声）的声调不同，第二个音节相同，意思是蔬菜水果。"}, {"text": "国术", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）的声调不同，意思是中国武术。"}, {"text": "国初", "is_correct": false, "explanation": "chū（第一声）与 shū（第一声）的声母不同（ch 与 sh），意思是建国初期。"}], "explanations": {"国书": "正确答案。国书（guó shū）指国家之间递交的正式文书。", "果蔬": "guǒ（第三声）与 guó（第二声）的声调不同，第二个音节相同，意思是蔬菜水果。", "国术": "shù（第四声）与 shū（第一声）的声调不同，意思是中国武术。", "国初": "chū（第一声）与 shū（第一声）的声母不同（ch 与 sh），意思是建国初期。"}, "sentence_index": null, "correct_answer": "国书"}, "level_3": {"options": [{"text": "国书", "is_correct": true, "explanation": "正确。国书指国家之间递交的正式信件，可以“写给”另一个国家。"}, {"text": "护照", "is_correct": false, "explanation": "语义：护照是国家签发给公民的证件，不是国与国之间的信件。"}, {"text": "大使", "is_correct": false, "explanation": "语义：大使指人，不是可以书写、可以寄出的文书。"}, {"text": "国旗", "is_correct": false, "explanation": "搭配：“写给”需要可以书写的内容，国旗不能被“写”。"}], "explanations": {"国书": "正确。国书指国家之间递交的正式信件，可以“写给”另一个国家。", "护照": "语义：护照是国家签发给公民的证件，不是国与国之间的信件。", "大使": "语义：大使指人，不是可以书写、可以寄出的文书。", "国旗": "搭配：“写给”需要可以书写的内容，国旗不能被“写”。"}, "sentence_index": 0, "correct_answer": "国书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给远方的朋友写了一封国书，讲了这一年的变化。", "explanation": "这里应该用〈书信〉。国书是国家之间的正式文书，写给朋友的私人信件要用〈书信〉。"}, {"text": "我们签了一份国书，三年有效。", "explanation": "这里应该用〈合同〉。合同是双方商定权利义务的书面文件；国书是一国写给另一国的信，不用来商定权利义务。"}, {"text": "这家公司的老板向全体员工发出了国书，要大家下周加班。", "explanation": "语义：国书只用于国家之间，公司向员工发通知不能用“国书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93479, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "国书", "is_correct": true, "explanation": "正确答案。国书（guó shū）指国家之间递交的正式文书。"}, {"text": "果树", "is_correct": false, "explanation": "guǒ（第三声）与 guó（第二声）、shù（第四声）与 shū（第一声）的声调均不同，音节组成相同，意思是果树。"}, {"text": "古书", "is_correct": false, "explanation": "gǔ（第三声）与 guó（第二声）只差一个元音（u 与 o）且声调不同，后一音节 shū 相同，意思是古代的书。"}, {"text": "国树", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）的声调不同，意思是国家的树。"}], "explanations": {"国书": "正确答案。国书（guó shū）指国家之间递交的正式文书。", "果树": "guǒ（第三声）与 guó（第二声）、shù（第四声）与 shū（第一声）的声调均不同，音节组成相同，意思是果树。", "古书": "gǔ（第三声）与 guó（第二声）只差一个元音（u 与 o）且声调不同，后一音节 shū 相同，意思是古代的书。", "国树": "shù（第四声）与 shū（第一声）的声调不同，意思是国家的树。"}, "sentence_index": null, "correct_answer": "国书"}, "level_3": {"options": [{"text": "国书", "is_correct": true, "explanation": "正确。国书是正式文书，可以由大使亲自送去。"}, {"text": "试卷", "is_correct": false, "explanation": "语义：试卷是学生考试用的纸，不是需要大使亲自递送的文书。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与“由大使亲自送去”的正式语境不合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的练习，与外交文书无关。"}], "explanations": {"国书": "正确。国书是正式文书，可以由大使亲自送去。", "试卷": "语义：试卷是学生考试用的纸，不是需要大使亲自递送的文书。", "玩意儿": "语域：“玩意儿”是口语说法，与“由大使亲自送去”的正式语境不合。", "作业": "语义：作业是学生的练习，与外交文书无关。"}, "sentence_index": 6, "correct_answer": "国书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市政府给学校发了一份国书，通知下周放假。", "explanation": "这里应该用〈公函〉。市政府对学校的公事往来用〈公函〉，国书只在国家之间使用。"}, {"text": "他收到一份国书，回家慢慢看。", "explanation": "这里应该用〈信件〉。国书是国家之间的正式文书，个人收到的普通来信应称〈信件〉。"}, {"text": "我和同学每天互相寄国书，聊聊天。", "explanation": "语义：国书是国家元首之间的文书，同学之间聊天不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只国书是两国元首之间的正式文件。", "corrected_sentence": "这封国书是两国元首之间的正式文件。", "error_description": "量词错误：国书应用“封”或“份”，“只”用于动物或成对的物品，不能说“这只国书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国元首共同签署了那只国书。", "corrected_sentence": "两国元首共同签署了那份国书。", "error_description": "量词错误：国书应用“份”或“封”，“只”用于动物或成对的物品，不能说“那只国书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
