INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93480, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "派遣或召回大使时，国家元首致送对方国家元首的正式文书。", "primary_collocate": null, "pronunciation": "guó shū", "ipa": "kwɔ˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "新大使到了以后，要先递交国书。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使向总统递交了国书。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国书由国家元首签名，交给新大使。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使要回国时，国家会发出召回国书。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有国书，大使就不能正式工作。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使带着国书坐飞机去了那个国家。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王接过国书，欢迎新大使上任。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "递交国书是大使上任时的重要仪式。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大使今天上午向女王递交了国书。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国书写明了这位大使的名字和职务。", "target_word": "国书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词，大使上任或离任时元首之间递送的正式文书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c11b62-a391-4e78-aa2c-8e0c8aef0aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93480, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国书", "is_correct": true, "explanation": "正确答案。国书（guó shū）指派遣大使时元首之间递送的正式文书。"}, {"text": "果蔬", "is_correct": false, "explanation": "guǒ（第三声）与 guó（第二声）的声调不同，第二个音节相同，意思是蔬菜水果。"}, {"text": "国术", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）的声调不同，意思是中国武术。"}, {"text": "国初", "is_correct": false, "explanation": "chū（第一声）与 shū（第一声）的声母不同（ch 与 sh），意思是建国初期。"}], "explanations": {"国书": "正确答案。国书（guó shū）指派遣大使时元首之间递送的正式文书。", "果蔬": "guǒ（第三声）与 guó（第二声）的声调不同，第二个音节相同，意思是蔬菜水果。", "国术": "shù（第四声）与 shū（第一声）的声调不同，意思是中国武术。", "国初": "chū（第一声）与 shū（第一声）的声母不同（ch 与 sh），意思是建国初期。"}, "sentence_index": null, "correct_answer": "国书"}, "level_3": {"options": [{"text": "国书", "is_correct": true, "explanation": "正确。新大使到任后要先递交国书，这是大使上任的正式文书。"}, {"text": "辞呈", "is_correct": false, "explanation": "语义：辞呈是辞职时递交的文书，与新大使上任的情境相反。"}, {"text": "欠条", "is_correct": false, "explanation": "语义：欠条是还钱的凭证，不是上任时要递交的文书。"}, {"text": "检讨书", "is_correct": false, "explanation": "语域：检讨书是认错用的文书，口吻带有惩戒色彩，与外交场合不合。"}], "explanations": {"国书": "正确。新大使到任后要先递交国书，这是大使上任的正式文书。", "辞呈": "语义：辞呈是辞职时递交的文书，与新大使上任的情境相反。", "欠条": "语义：欠条是还钱的凭证，不是上任时要递交的文书。", "检讨书": "语域：检讨书是认错用的文书，口吻带有惩戒色彩，与外交场合不合。"}, "sentence_index": 0, "correct_answer": "国书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外交部会发出国书，要求对方说明情况。", "explanation": "这里应该用〈照会〉。照会是外交部门之间提出交涉的书面文件，国书只用于元首致送的上任或召回。"}, {"text": "家里来了一份国书，要他尽快回国。", "explanation": "这里应该用〈电报〉。电报用于传递紧急消息，国书只是国家元首之间致送的正式文书，不能用来传达一般通知。"}, {"text": "大使要回国时，他会向邻居递交召回国书。", "explanation": "语义：召回国书只能由国家元首致送给对方元首，大使不能向邻居递交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93480, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "国书", "is_correct": true, "explanation": "正确答案。国书（guó shū）指派遣大使时元首之间递送的正式文书。"}, {"text": "果树", "is_correct": false, "explanation": "guǒ（第三声）与 guó（第二声）、shù（第四声）与 shū（第一声）的声调均不同，音节组成相同，意思是果树。"}, {"text": "古书", "is_correct": false, "explanation": "gǔ（第三声）与 guó（第二声）只差一个元音（u 与 o）且声调不同，后一音节 shū 相同，意思是古代的书。"}, {"text": "国树", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）的声调不同，意思是国家的树。"}], "explanations": {"国书": "正确答案。国书（guó shū）指派遣大使时元首之间递送的正式文书。", "果树": "guǒ（第三声）与 guó（第二声）、shù（第四声）与 shū（第一声）的声调均不同，音节组成相同，意思是果树。", "古书": "gǔ（第三声）与 guó（第二声）只差一个元音（u 与 o）且声调不同，后一音节 shū 相同，意思是古代的书。", "国树": "shù（第四声）与 shū（第一声）的声调不同，意思是国家的树。"}, "sentence_index": null, "correct_answer": "国书"}, "level_3": {"options": [{"text": "国书", "is_correct": true, "explanation": "正确。国王接过国书，是为了欢迎新大使上任。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是付款用的单据，国王接过它后“欢迎新大使上任”不成立。"}, {"text": "罚单", "is_correct": false, "explanation": "搭配：“接过”多用于可以拿在手里的礼物或文件，罚单一般说“收到”或“开”。"}, {"text": "通缉令", "is_correct": false, "explanation": "语义：通缉令是抓捕罪犯的命令，与欢迎新大使的语境相反。"}], "explanations": {"国书": "正确。国王接过国书，是为了欢迎新大使上任。", "账单": "语义：账单是付款用的单据，国王接过它后“欢迎新大使上任”不成立。", "罚单": "搭配：“接过”多用于可以拿在手里的礼物或文件，罚单一般说“收到”或“开”。", "通缉令": "语义：通缉令是抓捕罪犯的命令，与欢迎新大使的语境相反。"}, "sentence_index": 6, "correct_answer": "国书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份国书写着我的购物清单。", "explanation": "语义：国书是国家元首之间的正式文书，不可能记录购物清单。"}, {"text": "学校发出国书，告诉大家放假。", "explanation": "这里应该用〈通知〉。学校发放假消息用〈通知〉，国书只在国家元首之间使用。"}, {"text": "我把国书贴在冰箱上当作便条。", "explanation": "语义：国书是正式的外交文件，不能当作便条贴在冰箱上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新任大使昨天向王后递交了一只国书。", "corrected_sentence": "新任大使昨天向王后递交了一份国书。", "error_description": "量词错误：国书应用“份”或“封”，“只”用于动物或成对的物品，不能说“一只国书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "王后接过那只国书，当场打开读了起来。", "corrected_sentence": "王后接过那封国书，当场打开读了起来。", "error_description": "量词错误：国书应用“封”或“份”，“只”用于动物或成对的物品，不能说“那只国书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
