INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93482, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行政区划中介于省级与县级之间的一级。", "primary_collocate": null, "pronunciation": "dì jí", "ipa": "ti˥˩ t͡ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "地级在省级和县级中间。", "target_word": "地级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方不是省级，也不是县级，而是地级。", "target_word": "地级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先在县级工作，后来调到地级的政府部门。", "target_word": "地级", "complexity_tier": "T3", "furigana": "tā xiān zài xiàn jí gōng zuò, hòu lái diào dào dì jí de zhèng fǔ bù mén.", "sentence_source": "generated"}, {"text": "这里的行政区分为省级、地级、县级。", "target_word": "地级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地级的下一级是县级。", "target_word": "地级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市升为地级以后，发展很快。", "target_word": "地级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地级排在省级后面，县级前面。", "target_word": "地级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个市的级别是地级，不是县级。", "target_word": "地级", "complexity_tier": "T3", "furigana": "zhè ge shì de jí bié shì dì jí, bú shì xiàn jí.", "sentence_source": "generated"}, {"text": "这个地方是地级，归省管理。", "target_word": "地级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，地级比县级高一级。", "target_word": "地级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地级市", "label": "复合"}], "register": "书面语", "sense_fingerprint": "行政区划中省级与县级之间的一级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08cebff2-181f-4f57-a972-8a5dfd43b209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93482, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地级", "is_correct": true, "explanation": "地级：行政区划中介于省级与县级之间的一级。"}, {"text": "低级", "is_correct": false, "explanation": "dī（第一声）与 dì（第四声）的第一个音节声调不同，意思是层次低或品质差。"}, {"text": "地基", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）的第二个音节声调不同，意思是建筑物的基础。"}, {"text": "第几", "is_correct": false, "explanation": "第二个音节 jǐ（第三声）与 jí（第二声）声调不同，意思是第几个。"}], "explanations": {"地级": "地级：行政区划中介于省级与县级之间的一级。", "低级": "dī（第一声）与 dì（第四声）的第一个音节声调不同，意思是层次低或品质差。", "地基": "jī（第一声）与 jí（第二声）的第二个音节声调不同，意思是建筑物的基础。", "第几": "第二个音节 jǐ（第三声）与 jí（第二声）声调不同，意思是第几个。"}, "sentence_index": null, "correct_answer": "地级"}, "level_3": {"options": [{"text": "地级", "is_correct": true, "explanation": "地级：介于省级与县级之间的行政等级，与句意相符。"}, {"text": "省级", "is_correct": false, "explanation": "语义：省级不能位于省级与县级之间，“省级在省级和县级中间”与句意矛盾。"}, {"text": "县级", "is_correct": false, "explanation": "语义：县级本身是县级，不能位于省级和县级之间，句意不通。"}, {"text": "国家", "is_correct": false, "explanation": "搭配：“国家”不是行政区划的等级，不能与省级、县级并列描述层级。"}], "explanations": {"地级": "地级：介于省级与县级之间的行政等级，与句意相符。", "省级": "语义：省级不能位于省级与县级之间，“省级在省级和县级中间”与句意矛盾。", "县级": "语义：县级本身是县级，不能位于省级和县级之间，句意不通。", "国家": "搭配：“国家”不是行政区划的等级，不能与省级、县级并列描述层级。"}, "sentence_index": 0, "correct_answer": "地级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个县的人口是地级。", "explanation": "这里应该用〈规模〉。地级只指行政区划的等级，不能用来说人口多少。"}, {"text": "我们学校的地级很高，每个人都很努力。", "explanation": "这里应该用〈档次〉。地级只指行政区划的等级，不能用来说学校的档次。"}, {"text": "这首歌的级别是地级。", "explanation": "这里应该用〈档次〉。地级只指行政区划的等级，不能用来说歌曲的档次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地级", "is_correct": true, "explanation": "地级：排在省级之后、县级之前的行政等级，与句意相符。"}, {"text": "中央", "is_correct": false, "explanation": "语义：中央不属于地方行政等级，不能排在省级后面，句意矛盾。"}, {"text": "名次", "is_correct": false, "explanation": "搭配：“名次”指排列的位次，不用于行政等级的排列，“排在省级后面”不通。"}, {"text": "乡镇", "is_correct": false, "explanation": "语义：乡镇的级别低于县级，不能排在县级前面，与句意矛盾。"}], "explanations": {"地级": "地级：排在省级之后、县级之前的行政等级，与句意相符。", "中央": "语义：中央不属于地方行政等级，不能排在省级后面，句意矛盾。", "名次": "搭配：“名次”指排列的位次，不用于行政等级的排列，“排在省级后面”不通。", "乡镇": "语义：乡镇的级别低于县级，不能排在县级前面，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "地级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的地级很高，员工都很努力。", "explanation": "这里应该用〈档次〉。地级只指行政区划的等级，不能用来说公司的档次。"}, {"text": "他的爱好是地级。", "explanation": "这里是把〈地级〉当作〈兴趣〉来用，但地级只指行政区划的等级，不能用来指兴趣爱好。"}, {"text": "妈妈说，她的地级很高。", "explanation": "这里应该用〈身份〉。地级只指行政区划的等级，不能用来说一个人的身份或地位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个市地级，归省管理。", "corrected_sentence": "这个市是地级，归省管理。", "error_description": "错误在漏掉“是”：判断句中“是”不能省略，应说“这个市是地级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市升地级后，发展很快。", "corrected_sentence": "这座城市升为地级后，发展很快。", "error_description": "错误在漏掉“为”：“升为地级”是固定说法，“升地级”不成立，应说“升为地级后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
