INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "猛烈燃烧的大面积火灾；也指烹饪时的旺火。", "primary_collocate": null, "pronunciation": "dà huǒ", "ipa": "ta˥˩ xuo˨˩˦", "syllable_count": 2, "sentences": [{"text": "昨天夜里，山上起了大火。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场大火烧了三天三夜。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员很快就把大火扑灭了。", "target_word": "大火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里发生了大火，很多动物受伤。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "炒青菜要用大火，很快就熟。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先用大火把水烧开，再用小火煮。", "target_word": "大火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火过后，那片树林变黑了。", "target_word": "大火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火把整个仓库都烧光了。", "target_word": "大火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煮汤时先开大火，水开后再关小。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻说大火已经灭了，没有人受伤。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场大火", "label": "量词"}, {"form": "森林大火", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指大面积猛烈燃烧的火灾，也指做饭时火力最旺的火", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d689ef-f29c-47a1-838b-0acd26167009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93488, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大火", "is_correct": true, "explanation": "正确：大火，dà huǒ，指猛烈燃烧的大面积火灾。"}, {"text": "大祸", "is_correct": false, "explanation": "dà 相同，huò（第四声）与 huǒ（第三声）只有声调不同，意思是大祸，指重大灾祸。"}, {"text": "打火", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）只有声调不同，意思是打火，即点火。"}, {"text": "大号", "is_correct": false, "explanation": "dà 相同，hào（第四声）与 huǒ（第三声）韵母与声调都不同（ao 与 uo），意思是大号，指尺寸大。"}], "explanations": {"大火": "正确：大火，dà huǒ，指猛烈燃烧的大面积火灾。", "大祸": "dà 相同，huò（第四声）与 huǒ（第三声）只有声调不同，意思是大祸，指重大灾祸。", "打火": "dǎ（第三声）与 dà（第四声）只有声调不同，意思是打火，即点火。", "大号": "dà 相同，hào（第四声）与 huǒ（第三声）韵母与声调都不同（ao 与 uo），意思是大号，指尺寸大。"}, "sentence_index": null, "correct_answer": "大火"}, "level_3": {"options": [{"text": "大火", "is_correct": true, "explanation": "大火指猛烈燃烧的大面积火灾，与“昨天夜里，山上起了”相符。"}, {"text": "风波", "is_correct": false, "explanation": "语义：风波指纷争或波折，与山上夜里发生的情况无关。"}, {"text": "浪", "is_correct": false, "explanation": "搭配：“起浪”多用于海面或水面，不能说山上起浪。"}, {"text": "泡", "is_correct": false, "explanation": "搭配：“起泡”指液体或皮肤表面鼓起，不能用于描述山上的情况。"}], "explanations": {"大火": "大火指猛烈燃烧的大面积火灾，与“昨天夜里，山上起了”相符。", "风波": "语义：风波指纷争或波折，与山上夜里发生的情况无关。", "浪": "搭配：“起浪”多用于海面或水面，不能说山上起浪。", "泡": "搭配：“起泡”指液体或皮肤表面鼓起，不能用于描述山上的情况。"}, "sentence_index": 0, "correct_answer": "大火"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "森林里闪着大火，很多动物受伤。", "explanation": "这里应该用〈火光〉。大火指猛烈燃烧的火灾，不能像火光那样闪烁。"}, {"text": "夜空中绽放着一场大火，人们都抬头看。", "explanation": "这里应该用〈烟火〉。大火指猛烈燃烧的火灾，不能像烟花一样绽放；绽放的光亮应说烟火。"}, {"text": "森林里发生了一只大火，很多动物受伤。", "explanation": "这里应该用〈场〉。大火是事件，计量用“场”；“只”用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93488, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大火", "is_correct": true, "explanation": "正确：大火，dà huǒ，指猛烈燃烧的大面积火灾。"}, {"text": "大会", "is_correct": false, "explanation": "dà 相同，huì（第四声）与 huǒ（第三声）韵母与声调都不同，意思是大会。"}, {"text": "大好", "is_correct": false, "explanation": "dà 相同，hǎo 与 huǒ 韵母不同（ao 与 uo），声调相同，意思是大好。"}, {"text": "大户", "is_correct": false, "explanation": "dà 相同，hù（第四声）与 huǒ（第三声）韵母与声调都不同，意思是大户。"}], "explanations": {"大火": "正确：大火，dà huǒ，指猛烈燃烧的大面积火灾。", "大会": "dà 相同，huì（第四声）与 huǒ（第三声）韵母与声调都不同，意思是大会。", "大好": "dà 相同，hǎo 与 huǒ 韵母不同（ao 与 uo），声调相同，意思是大好。", "大户": "dà 相同，hù（第四声）与 huǒ（第三声）韵母与声调都不同，意思是大户。"}, "sentence_index": null, "correct_answer": "大火"}, "level_3": {"options": [{"text": "大火", "is_correct": true, "explanation": "大火指猛烈燃烧的火灾，烧过后树林才会变黑，与“大火过后”相符。"}, {"text": "大雪", "is_correct": false, "explanation": "语义：雪是白色的，“大雪过后树林变黑”与雪后景象相悖。"}, {"text": "大浪", "is_correct": false, "explanation": "语义：大浪发生在水面，与树林变黑的情况无关。"}, {"text": "大典", "is_correct": false, "explanation": "语义：大典是隆重的仪式，不会使树林变黑，与“大火过后”的情境不符。"}], "explanations": {"大火": "大火指猛烈燃烧的火灾，烧过后树林才会变黑，与“大火过后”相符。", "大雪": "语义：雪是白色的，“大雪过后树林变黑”与雪后景象相悖。", "大浪": "语义：大浪发生在水面，与树林变黑的情况无关。", "大典": "语义：大典是隆重的仪式，不会使树林变黑，与“大火过后”的情境不符。"}, "sentence_index": 6, "correct_answer": "大火"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "灶上的大火很小，锅里的水还没开。", "explanation": "这里应该用〈火苗〉。大火本指火势猛烈，不能说“很小”；“很小”应形容火苗。"}, {"text": "他用大火点着了煤炉。", "explanation": "这里应该用〈火柴〉。大火是猛烈燃烧的火，不能当作点火的工具；点火要用火柴。"}, {"text": "炖汤要用大火，慢慢熬一个下午。", "explanation": "这里应该用〈小火〉。慢慢熬汤要用小火，大火会让汤迅速烧干，与“慢慢熬”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员很快就扑灭了这只大火。", "corrected_sentence": "消防员很快就扑灭了这场大火。", "error_description": "错误：“大火”的量词用错。火灾是事件，应用“场”，“只”用于动物。正确说法是“这场大火”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "消防员很快就这场大火扑灭了。", "corrected_sentence": "消防员很快就把这场大火扑灭了。", "error_description": "错误：漏掉介词“把”。“扑灭”要求把受事“这场大火”提到动词前，应说“把这场大火扑灭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
