INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93506, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词，用在名词或代词后，表示“像……一样”。", "primary_collocate": null, "pronunciation": "bān", "ipa": "pan˥", "syllable_count": 1, "sentences": [{"text": "老师像母亲般照顾我们。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她像春天般温暖。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "掌声雷鸣般响起来。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给了我家人般的温暖。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我如兄长般关心。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子弹雨点般飞来。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们像家人般住在一起。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她像天使般善良。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他像大山般站在门口。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们鸟儿般跑出教室。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "用在名词后，像……般，后接动词或的字短语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a469138-6fb8-45ff-8b3c-19ee085e4330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93506, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "般", "is_correct": true, "explanation": "般（bān）：助词，用在名词后，表示像……一样，如“母亲般”。"}, {"text": "板", "is_correct": false, "explanation": "bǎn（第三声）与 bān（第一声）声调不同，意思是木板。"}, {"text": "奔", "is_correct": false, "explanation": "bēn 与 bān 韵母不同（en 与 an），意思是奔跑。"}, {"text": "翻", "is_correct": false, "explanation": "fān 与 bān 声母不同（f 与 b），意思是翻动。"}], "explanations": {"般": "般（bān）：助词，用在名词后，表示像……一样，如“母亲般”。", "板": "bǎn（第三声）与 bān（第一声）声调不同，意思是木板。", "奔": "bēn 与 bān 韵母不同（en 与 an），意思是奔跑。", "翻": "fān 与 bān 声母不同（f 与 b），意思是翻动。"}, "sentence_index": null, "correct_answer": "般"}, "level_3": {"options": [{"text": "般", "is_correct": true, "explanation": "般：助词，用在名词后表示像……一样，此处表示老师像母亲一样照顾我们。"}, {"text": "的", "is_correct": false, "explanation": "语义：“母亲的”表示所属，句子变成老师像母亲的照顾，不表示像母亲一样。"}, {"text": "似", "is_correct": false, "explanation": "配价：“似”需要比较的对象，“母亲似照顾”不通，应说“像母亲似的”。"}, {"text": "着", "is_correct": false, "explanation": "搭配：“着”表示持续，“像母亲着照顾”不成话。"}], "explanations": {"般": "般：助词，用在名词后表示像……一样，此处表示老师像母亲一样照顾我们。", "的": "语义：“母亲的”表示所属，句子变成老师像母亲的照顾，不表示像母亲一样。", "似": "配价：“似”需要比较的对象，“母亲似照顾”不通，应说“像母亲似的”。", "着": "搭配：“着”表示持续，“像母亲着照顾”不成话。"}, "sentence_index": 0, "correct_answer": "般"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的笑容和阳光般温暖。", "explanation": "这里应该用〈一般〉。“般”不能与“和”连用，要说“和阳光一般温暖”。"}, {"text": "她收集了一个般玩具，都很精致。", "explanation": "这里应该用〈种〉。般不能与“一个”搭配，要说“一种玩具”。"}, {"text": "她跟妈妈般温柔，大家都喜欢她。", "explanation": "这里应该用〈一样〉。“般”不能与“跟”连用，要说“跟妈妈一样温柔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93506, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "般", "is_correct": true, "explanation": "般（bān）：助词，用在名词后，表示像……一样，如“家人般”。"}, {"text": "办", "is_correct": false, "explanation": "bàn（第四声）与 bān（第一声）声调不同，意思是办理。"}, {"text": "单", "is_correct": false, "explanation": "dān 与 bān 声母不同（d 与 b），意思是单独。"}, {"text": "帮", "is_correct": false, "explanation": "bāng 与 bān 韵母不同（ang 与 an），意思是帮助。"}, {"text": "干", "is_correct": false, "explanation": "gān 与 bān 声母不同（g 与 b），意思是干燥。"}], "explanations": {"般": "般（bān）：助词，用在名词后，表示像……一样，如“家人般”。", "办": "bàn（第四声）与 bān（第一声）声调不同，意思是办理。", "单": "dān 与 bān 声母不同（d 与 b），意思是单独。", "帮": "bāng 与 bān 韵母不同（ang 与 an），意思是帮助。", "干": "gān 与 bān 声母不同（g 与 b），意思是干燥。"}, "sentence_index": null, "correct_answer": "般"}, "level_3": {"options": [{"text": "般", "is_correct": true, "explanation": "般：助词，用在名词后表示像……一样，此处表示我们像家人一样住在一起。"}, {"text": "得", "is_correct": false, "explanation": "搭配：“得”引出补语，“像家人得住在一起”不通。"}, {"text": "了", "is_correct": false, "explanation": "语义：“了”表示完成，“像家人了住在一起”不表示像家人一样。"}, {"text": "过", "is_correct": false, "explanation": "语义：“过”表示经历，句子不表示像家人一样。"}], "explanations": {"般": "般：助词，用在名词后表示像……一样，此处表示我们像家人一样住在一起。", "得": "搭配：“得”引出补语，“像家人得住在一起”不通。", "了": "语义：“了”表示完成，“像家人了住在一起”不表示像家人一样。", "过": "语义：“过”表示经历，句子不表示像家人一样。"}, "sentence_index": 6, "correct_answer": "般"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫和小孩般淘气。", "explanation": "这里应该用〈一样〉。“般”不能与“和”连用，要说“和小孩一样淘气”。"}, {"text": "他同老师般严肃，大家都有点怕他。", "explanation": "这里应该用〈一样〉。“般”不能与“同”连用，要说“同老师一样严肃”。"}, {"text": "他买了两般糖果，都很甜。", "explanation": "这里应该用〈种〉。般只用于“诸般”“万般”这类词，不能接“两”作量词，要说“两种糖果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他像父亲般的关心我。", "corrected_sentence": "他像父亲般关心我。", "error_description": "助词误用：“般”后直接接动词，不能再加“的”。“像父亲般的关心我”不成句，应说“像父亲般关心我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她跟小鸟般自由。", "corrected_sentence": "她像小鸟般自由。", "error_description": "比较词误用：“般”表示“像……一样”，须与“像”或“如”搭配，不能与“跟”连用。应说“她像小鸟般自由”，不说“她跟小鸟般自由”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
