INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93527, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "度假是放假的时候出去玩，好好休息。", "primary_collocate": null, "pronunciation": "dù jià", "ipa": "tu˥˩ tɕia˥˩", "syllable_count": 2, "sentences": [{"text": "放假了，我们想出去度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暑假我和朋友去青岛度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她工作很忙，很少有时间度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国庆节我们不想在家，想出去度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸妈妈退休后，常常去海边度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们住在海边的小房子里度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们春节去哪儿度假？", "target_word": "度假", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想好好休息，所以订了机票去度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们放假了，一家人开车去山里度假。", "target_word": "度假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年夏天，我们在湖边度假，每天游泳。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "度了假", "label": "体标"}, {"form": "度过假", "label": "体标"}, {"form": "度假村", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，指放假时离开日常生活的地方，轻松地玩和休息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d689ef-f29c-47a1-838b-0acd26167009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93527, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "度假", "is_correct": true, "explanation": "正确：度假，dù jià，指放假时离开日常生活的地方，轻松地玩和休息。"}, {"text": "代价", "is_correct": false, "explanation": "dài 与 dù 只有韵母不同（ai 与 u），声调相同，意思是代价。"}, {"text": "地价", "is_correct": false, "explanation": "dì 与 dù 只有韵母不同（i 与 u），声调相同，意思是地价。"}, {"text": "对价", "is_correct": false, "explanation": "duì 与 dù 只有韵母不同（ui 与 u），声调相同，意思是对价。"}], "explanations": {"度假": "正确：度假，dù jià，指放假时离开日常生活的地方，轻松地玩和休息。", "代价": "dài 与 dù 只有韵母不同（ai 与 u），声调相同，意思是代价。", "地价": "dì 与 dù 只有韵母不同（i 与 u），声调相同，意思是地价。", "对价": "duì 与 dù 只有韵母不同（ui 与 u），声调相同，意思是对价。"}, "sentence_index": null, "correct_answer": "度假"}, "level_3": {"options": [{"text": "度假", "is_correct": true, "explanation": "度假指放假时外出休息游玩，与“放假了，我们想出去”相符。"}, {"text": "加班", "is_correct": false, "explanation": "语义：加班是延长工作时间，与“放假了”的休假语境矛盾。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：考试要去考场进行，与放假后想出去玩的语境不合。"}, {"text": "上课", "is_correct": false, "explanation": "语义：上课是学习活动，与“放假了”后想出去的意思相反。"}], "explanations": {"度假": "度假指放假时外出休息游玩，与“放假了，我们想出去”相符。", "加班": "语义：加班是延长工作时间，与“放假了”的休假语境矛盾。", "考试": "搭配：考试要去考场进行，与放假后想出去玩的语境不合。", "上课": "语义：上课是学习活动，与“放假了”后想出去的意思相反。"}, "sentence_index": 0, "correct_answer": "度假"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国庆节公司度假，员工都不用上班。", "explanation": "这里应该用〈放假〉。度假的主语应是个人，指个人离开日常生活去休息游玩；公司整体停工要用放假。"}, {"text": "国庆节我们去工厂度假，一起生产零件。", "explanation": "这里应该用〈上班〉。度假指假期中休息游玩，不是在工厂生产；在工厂干活应说上班。"}, {"text": "国庆节我们在海边度假了一小时，就回家了。", "explanation": "这里应该用〈游玩〉。度假指较长时间的假期休闲，不能用来描述一小时的短暂游玩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93527, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "度假", "is_correct": true, "explanation": "正确：度假，dù jià，指放假时离开日常生活的地方，轻松地玩和休息。"}, {"text": "独家", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）、jiā（第一声）与 jià（第四声）声调都不同，意思是独家。"}, {"text": "赌家", "is_correct": false, "explanation": "dǔ（第三声）与 dù（第四声）、jiā（第一声）与 jià（第四声）声调都不同，意思是赌徒。"}, {"text": "大家", "is_correct": false, "explanation": "dà 与 dù 韵母不同（a 与 u），jiā 与 jià 声调不同，意思是大家。"}], "explanations": {"度假": "正确：度假，dù jià，指放假时离开日常生活的地方，轻松地玩和休息。", "独家": "dú（第二声）与 dù（第四声）、jiā（第一声）与 jià（第四声）声调都不同，意思是独家。", "赌家": "dǔ（第三声）与 dù（第四声）、jiā（第一声）与 jià（第四声）声调都不同，意思是赌徒。", "大家": "dà 与 dù 韵母不同（a 与 u），jiā 与 jià 声调不同，意思是大家。"}, "sentence_index": null, "correct_answer": "度假"}, "level_3": {"options": [{"text": "度假", "is_correct": true, "explanation": "度假指假期中外出休息游玩，与“你们春节去哪儿”的问句相符。"}, {"text": "吵架", "is_correct": false, "explanation": "搭配：“吵架”不是可以“去哪儿”进行的出行或假期活动，与春节出游的问句不符。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧是身体不适，不是可以“去哪儿”做的活动，与问句不符。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：开学指学校学期开始，搭配的地点应是学校，不能说“去哪儿开学”。"}], "explanations": {"度假": "度假指假期中外出休息游玩，与“你们春节去哪儿”的问句相符。", "吵架": "搭配：“吵架”不是可以“去哪儿”进行的出行或假期活动，与春节出游的问句不符。", "发烧": "语义：发烧是身体不适，不是可以“去哪儿”做的活动，与问句不符。", "开学": "搭配：开学指学校学期开始，搭配的地点应是学校，不能说“去哪儿开学”。"}, "sentence_index": 6, "correct_answer": "度假"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他腿摔伤了，我们带他去医院度假。", "explanation": "这里应该用〈看病〉。度假是去风景地休息游玩，不能去医院；去医院应说看病。"}, {"text": "他在厨房度假，每天做饭洗碗。", "explanation": "这里应该用〈做家务〉。度假指假期中休息游玩，不是在家干活；做饭洗碗应说做家务。"}, {"text": "我们每天早上都去湖边度假。", "explanation": "这里应该用〈散步〉。度假指离开日常生活的较长假期，不能每天早上去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个假期我们去湖边度假着。", "corrected_sentence": "这个假期我们去湖边度假。", "error_description": "错误：“着”不能直接接在离合词“度假”后面；带“着”时应插在中间，说“度着假”。此句应删去“着”，说“去湖边度假”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f303f2a-c178-4185-b5fe-d85d6c8caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
