INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "初步是刚刚开始的，还不是最后完成的。", "primary_collocate": null, "pronunciation": "chū bù", "ipa": "ʈʂʰu˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这是我们的初步方案。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初步结果明天就出来了。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是我的初步想法，还要再改。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个城市有了初步印象。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份初步计划还不完整。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生先做了初步检查，还要等报告。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是初步的名单，最后还会改。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初步成绩已经出来了，但不是最后的。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看了我的初步设计，说还要修改。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个初步方案太简单，请再补充细节。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做定语，指刚开始、尚未最后完成的方案、结果、想法等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bdf063c-4c7f-4fb1-bb18-7cd2426d705d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初步", "is_correct": true, "explanation": "正确答案。“初步方案”指尚未最后完成的方案，修饰名词“方案”。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容嗓音，不能修饰“方案”，“我们的沙哑方案”说不通。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或物的体形，不能修饰“方案”这样的抽象事物。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”表示情绪，不能描述“方案”，与“我们的…方案”的说法不符。"}], "explanations": {"初步": "正确答案。“初步方案”指尚未最后完成的方案，修饰名词“方案”。", "沙哑": "语义：“沙哑”形容嗓音，不能修饰“方案”，“我们的沙哑方案”说不通。", "胖": "体貌：“胖”形容人或物的体形，不能修饰“方案”这样的抽象事物。", "悲伤": "语义：“悲伤”表示情绪，不能描述“方案”，与“我们的…方案”的说法不符。"}, "sentence_index": 0, "correct_answer": "初步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份方案很初步，可以直接用。", "explanation": "这里应该用〈完整〉。“可以直接用”说明方案已经完成，与“初步”（尚未最后完成）矛盾，应说“完整”。"}, {"text": "他很初步，做事总是不成熟。", "explanation": "这里应该用〈幼稚〉。“初步”描述事情的开始阶段，不能用来形容人的性格，形容人要用“幼稚”。"}, {"text": "这件衣服非常初步。", "explanation": "这里应该用〈完美〉。“初步”表示尚未完成，衣服是成品，不能用“初步”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初步", "is_correct": true, "explanation": "正确答案。“初步的名单”指尚未定稿的名单，与“最后还会改”的语境相符。"}, {"text": "最终", "is_correct": false, "explanation": "语义：“最终”表示定稿，与后半句“最后还会改”相矛盾。"}, {"text": "完整", "is_correct": false, "explanation": "语义：“完整”表示已经齐全，与“只是”和“还会改”的语境不合。"}, {"text": "精美", "is_correct": false, "explanation": "搭配：“精美”多用来修饰工艺品或印刷品，不用来修饰“名单”。"}], "explanations": {"初步": "正确答案。“初步的名单”指尚未定稿的名单，与“最后还会改”的语境相符。", "最终": "语义：“最终”表示定稿，与后半句“最后还会改”相矛盾。", "完整": "语义：“完整”表示已经齐全，与“只是”和“还会改”的语境不合。", "精美": "搭配：“精美”多用来修饰工艺品或印刷品，不用来修饰“名单”。"}, "sentence_index": 6, "correct_answer": "初步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我初步三十岁了，还没结婚。", "explanation": "这里应该用〈已经〉。“初步”表示尚在开始阶段，与三十岁的年龄矛盾；说年龄已经到某岁要用“已经”。"}, {"text": "他初步死了，大家都很难过。", "explanation": "这里应该用〈去世〉。“初步”表示刚开始，不能用来说人的死亡这种彻底结束，要说“去世”。"}, {"text": "这顿饭我初步吃了整整一个小时。", "explanation": "这里应该用〈一直〉。“初步”指刚开始的阶段，与“整整一个小时”的持续时间矛盾，要说“一直”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写了一份很初步报告。", "corrected_sentence": "他写了一份初步报告。", "error_description": "错误形式是“很初步报告”，在“初步”前加了程度副词“很”。“初步”作定语修饰名词时不能受“很”修饰，应直接说“一份初步报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份的初步计划有问题。", "corrected_sentence": "这份初步计划有问题。", "error_description": "错误形式是“这份的初步计划”，量词“份”后多加了“的”。量词短语“这份”后直接接修饰语“初步”，不加“的”，应说“这份初步计划”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彻底", "is_correct": true, "explanation": "反义：“初步解决”指只解决了一部分，“彻底解决”与之相对，指完全解决。"}, {"text": "慢慢", "is_correct": false, "explanation": "无关：“慢慢”描述动作的速度，与“初步”的程度义没有反义关系。"}, {"text": "悄悄", "is_correct": false, "explanation": "无关：“悄悄”描述动作的方式，与“初步”没有对立关系。"}, {"text": "偶尔", "is_correct": false, "explanation": "无关：“偶尔”表示频率，与“初步”没有反义关系。"}], "correct_answer": "彻底", "explanations": {"彻底": "反义：“初步解决”指只解决了一部分，“彻底解决”与之相对，指完全解决。", "慢慢": "无关：“慢慢”描述动作的速度，与“初步”的程度义没有反义关系。", "悄悄": "无关：“悄悄”描述动作的方式，与“初步”没有对立关系。", "偶尔": "无关：“偶尔”表示频率，与“初步”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彻底", "is_correct": true, "explanation": "反义：“初步稳定”指只是暂时稳定，“彻底稳定”与之相对，指完全稳定。"}, {"text": "仔细", "is_correct": false, "explanation": "无关：“仔细”描述做事的认真程度，与“初步”没有反义关系。"}, {"text": "匆忙", "is_correct": false, "explanation": "无关：“匆忙”描述速度，与“初步”没有对立关系。"}, {"text": "随意", "is_correct": false, "explanation": "无关：“随意”指不拘束，与“初步”的程度义没有反义关系。"}], "correct_answer": "彻底", "explanations": {"彻底": "反义：“初步稳定”指只是暂时稳定，“彻底稳定”与之相对，指完全稳定。", "仔细": "无关：“仔细”描述做事的认真程度，与“初步”没有反义关系。", "匆忙": "无关：“匆忙”描述速度，与“初步”没有对立关系。", "随意": "无关：“随意”指不拘束，与“初步”的程度义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "开始阶段的；尚不完善或不最终的。", "primary_collocate": null, "pronunciation": "chū bù", "ipa": "ʈʂʰu˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我对这个公司只有初步了解。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理初步确定了开会时间，还没告诉大家。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察初步判断，这不是意外。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我们已经初步解决了。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他初步学会了用电脑，还不太熟。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作初步完成，明天再检查一遍。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家初步认为，原因是天气太冷。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们初步选了三个地方，下周再决定。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划已初步做好，请你提意见。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的情况初步稳定了，但还要观察。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做状语，修饰动作，表示处在开始阶段、还不完善", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bdf063c-4c7f-4fb1-bb18-7cd2426d705d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初步", "is_correct": true, "explanation": "正确答案。“初步了解”指只有开始阶段的了解，与“只有”的限定语气相符。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”表示完全，与“只有”的限定语气相矛盾。"}, {"text": "大量", "is_correct": false, "explanation": "搭配：“大量”修饰数量，不能直接修饰“了解”。"}, {"text": "无限", "is_correct": false, "explanation": "语义：“无限”表示没有界限，与“只有”的限定意思相反，句意不通。"}], "explanations": {"初步": "正确答案。“初步了解”指只有开始阶段的了解，与“只有”的限定语气相符。", "全部": "语义：“全部”表示完全，与“只有”的限定语气相矛盾。", "大量": "搭配：“大量”修饰数量，不能直接修饰“了解”。", "无限": "语义：“无限”表示没有界限，与“只有”的限定意思相反，句意不通。"}, "sentence_index": 0, "correct_answer": "初步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山初步很高，要爬两天。", "explanation": "这里应该删去〈初步〉。“初步”指开始阶段，不能修饰山的高度这类固有属性，直接说“这座山很高”即可。"}, {"text": "他初步忘记了那件事。", "explanation": "这里应该用〈彻底〉。“忘记”是一次性完成的结果，不能用“初步”来限定程度。"}, {"text": "这些书初步卖完了。", "explanation": "这里应该用〈全部〉。“卖完”表示全部售出，与“初步”的未完成义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初步", "is_correct": true, "explanation": "正确答案。“专家初步认为”表示初步的判断，与后半句“原因是天气太冷”相符。"}, {"text": "吃着", "is_correct": false, "explanation": "语义：“吃着”与“认为”不能同时进行，句意不通。"}, {"text": "睡着", "is_correct": false, "explanation": "语义：“睡着”与“认为”是互不相容的动作，句意不通。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：“大声认为”不是常见搭配，“认为”一般不用“大声”修饰。"}], "explanations": {"初步": "正确答案。“专家初步认为”表示初步的判断，与后半句“原因是天气太冷”相符。", "吃着": "语义：“吃着”与“认为”不能同时进行，句意不通。", "睡着": "语义：“睡着”与“认为”是互不相容的动作，句意不通。", "大声": "搭配：“大声认为”不是常见搭配，“认为”一般不用“大声”修饰。"}, "sentence_index": 6, "correct_answer": "初步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天初步下雨了，大家都跑回家。", "explanation": "这里应该用〈突然〉。“初步”不能描述下雨这种突然发生的变化，要说“突然下雨”。"}, {"text": "他初步就到。", "explanation": "这里应该用〈马上〉。“初步”不表示时间即将发生，表示很快要做某事要用“马上”。"}, {"text": "我初步忘了。", "explanation": "这里应该用〈一下子〉。“忘了”是瞬间的结果，不能用“初步”限定，要说“一下子忘了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们很初步讨论了方案。", "corrected_sentence": "我们初步讨论了方案。", "error_description": "错误形式是“很初步讨论”，在作状语的“初步”前加了“很”。“初步”表示“处在开始阶段”，不能受程度副词“很”修饰，应说“初步讨论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们很初步检查了一下。", "corrected_sentence": "我们初步检查了一下。", "error_description": "错误：程度副词“很”不能修饰作状语的“初步”，应删去“很”。正确：“我们初步检查了一下。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93565, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
