INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93573, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扶贫是帮助很穷的人，让他们过上好日子。", "primary_collocate": null, "pronunciation": "fú pín", "ipa": "fu˧˥ pʰin˧˥", "syllable_count": 2, "sentences": [{"text": "政府在山区扶贫已经十年了。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用自己的钱去扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派人到农村扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的老师去山里扶贫了。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家很重视扶贫，想让大家都过上好日子。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扶贫的目的是让穷人过好日子。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学毕业后，回家乡扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扶贫要先帮农民找到工作。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老板每年都出钱扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人都说，扶贫让他们的生活好多了。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扶贫工作", "label": "复合"}, {"form": "精准扶贫", "label": "复合"}], "register": "通用", "sense_fingerprint": "帮助穷人过上好日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08cebff2-181f-4f57-a972-8a5dfd43b209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”的主体须是人，政府不能结婚，与句子主语冲突。"}, {"text": "扶贫", "is_correct": true, "explanation": "扶贫：政府在山区帮助贫困人口摆脱贫困，与“已经十年了”的持续义相合。"}, {"text": "减肥", "is_correct": false, "explanation": "体貌：“减肥”针对人的体形，政府没有体形可减。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”的动作主体须是人或动物，政府不会在山区睡觉十年。"}], "explanations": {"结婚": "语义：“结婚”的主体须是人，政府不能结婚，与句子主语冲突。", "扶贫": "扶贫：政府在山区帮助贫困人口摆脱贫困，与“已经十年了”的持续义相合。", "减肥": "体貌：“减肥”针对人的体形，政府没有体形可减。", "睡觉": "语义：“睡觉”的动作主体须是人或动物，政府不会在山区睡觉十年。"}, "sentence_index": 0, "correct_answer": "扶贫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村去年靠种茶叶，终于扶贫了。", "explanation": "这里应该用〈脱贫〉。脱贫指贫困者自己摆脱贫困；“扶贫”是别人帮助穷人，不能说村子自己扶贫。"}, {"text": "春节前，工厂扶贫了一批新机器。", "explanation": "这里应该用〈购置〉。买进设备说购置；“扶贫”的对象是人或地区，不用于机器。"}, {"text": "地震后，救援人员扶贫了很多被困的人。", "explanation": "这里应该用〈救助〉。紧急抢救被困者说救助；“扶贫”不用于应急救险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退休", "is_correct": false, "explanation": "语义：刚大学毕业的人不可能退休，与“大学毕业后”矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”发生在毕业之前，不能说毕业后回乡出生。"}, {"text": "怀孕", "is_correct": false, "explanation": "体貌：“怀孕”是女性的身体状况，句子主语“他”不能怀孕。"}, {"text": "扶贫", "is_correct": true, "explanation": "扶贫：大学毕业后回家乡帮助贫困人口脱贫，语义通顺。"}], "explanations": {"退休": "语义：刚大学毕业的人不可能退休，与“大学毕业后”矛盾。", "出生": "语义：“出生”发生在毕业之前，不能说毕业后回乡出生。", "怀孕": "体貌：“怀孕”是女性的身体状况，句子主语“他”不能怀孕。", "扶贫": "扶贫：大学毕业后回家乡帮助贫困人口脱贫，语义通顺。"}, "sentence_index": 6, "correct_answer": "扶贫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要扶贫这片荒地。", "explanation": "这里应该用〈开发〉。开发用于土地和资源；“扶贫”的对象须是贫困的人或地区，不能用于荒地。"}, {"text": "这家企业下个月扶贫一款新饮料。", "explanation": "这里应该用〈推出〉。新产品面世说推出；“扶贫”的对象是贫困的人或地区，不用于产品。"}, {"text": "市里正在扶贫这条污染严重的河。", "explanation": "这里应该用〈治理〉。河流污染要说治理；“扶贫”的对象是人，不用于河流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "县里的干部明年去农村扶贫了。", "corrected_sentence": "县里的干部明年去农村扶贫。", "error_description": "错误在“扶贫”后的“了”：“明年”指将来，动作尚未发生，不能用“了”，应为“明年去农村扶贫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家企业明年还要扶贫过这个村。", "corrected_sentence": "这家企业明年还要扶贫这个村。", "error_description": "了／过错用：“明年”指将来，动作尚未发生，“过”表示已有的经历，不能用于将来；应去掉“过”，说“明年还要扶贫这个村”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
