INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扶助贫困地区或贫困人口，帮助其摆脱贫困。", "primary_collocate": null, "pronunciation": "fú pín", "ipa": "fu˧˥ pʰin˧˥", "syllable_count": 2, "sentences": [{"text": "政府在贫困地区长期扶贫，成效明显。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县扶贫多年，村民的收入明显提高了。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业到贫困地区扶贫，帮农民发展产业。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家扶贫的目标是让贫困人口摆脱贫困。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在贫困山区扶贫三年，村里变化很大。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些干部每个月都到村里扶贫，看看村民的情况。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生们利用假期到农村扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔资金要用于扶贫，不能浪费。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生都在为扶贫奔走。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司通过网上卖货来扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扶贫工作", "label": "复合"}, {"form": "精准扶贫", "label": "复合"}], "register": "正式", "sense_fingerprint": "扶助贫困地区或人口摆脱贫困", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08cebff2-181f-4f57-a972-8a5dfd43b209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”指说假话，政府不会“长期撒谎”换来“成效明显”，搭配不通。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“吵架”是争执的行为，不能用在“长期……，成效明显”这类做事的语境中。"}, {"text": "扶贫", "is_correct": true, "explanation": "扶贫：政府在贫困地区长期帮助贫困人口脱贫，与“成效明显”相合。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”不是政府的工作方式，“长期哭，成效明显”说不通。"}], "explanations": {"撒谎": "语义：“撒谎”指说假话，政府不会“长期撒谎”换来“成效明显”，搭配不通。", "吵架": "语义：“吵架”是争执的行为，不能用在“长期……，成效明显”这类做事的语境中。", "扶贫": "扶贫：政府在贫困地区长期帮助贫困人口脱贫，与“成效明显”相合。", "哭": "语义：“哭”不是政府的工作方式，“长期哭，成效明显”说不通。"}, "sentence_index": 0, "correct_answer": "扶贫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府扶贫新兴产业的发展。", "explanation": "这里应该用〈扶持〉。扶持指支持产业发展；“扶贫”的对象是贫困地区或贫困人口，不用于产业。"}, {"text": "矿井坍塌后，救援队扶贫了被困的矿工。", "explanation": "这里应该用〈救助〉。紧急抢救被困者说救助；“扶贫”指长期帮助脱贫，不用于应急救险。"}, {"text": "那位农民靠自己的努力终于扶贫了。", "explanation": "这里应该用〈脱贫〉。脱贫指贫困者自己摆脱贫困；“扶贫”是外力帮助，不能用于自己脱贫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退休", "is_correct": false, "explanation": "语义：大学生不可能退休，与“利用假期”的语境不合。"}, {"text": "扶贫", "is_correct": true, "explanation": "扶贫：大学生利用假期到农村帮助贫困人口脱贫，语义通顺。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”不是人能主动完成的动作，与“利用假期”矛盾。"}, {"text": "降落", "is_correct": false, "explanation": "搭配：“降落”多指飞机等落地，不说人降落到农村。"}], "explanations": {"退休": "语义：大学生不可能退休，与“利用假期”的语境不合。", "扶贫": "扶贫：大学生利用假期到农村帮助贫困人口脱贫，语义通顺。", "出生": "语义：“出生”不是人能主动完成的动作，与“利用假期”矛盾。", "降落": "搭配：“降落”多指飞机等落地，不说人降落到农村。"}, "sentence_index": 6, "correct_answer": "扶贫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春节期间，领导去医院扶贫病人。", "explanation": "这里应该用〈慰问〉。看望表示关心要说慰问；“扶贫”指帮助穷人脱贫，不用于看望病人。"}, {"text": "学校扶贫了这次比赛的经费。", "explanation": "这里应该用〈资助〉。资助经费、项目要说资助；“扶贫”的对象是人或贫困地区。"}, {"text": "市里要扶贫这片脏乱的街区。", "explanation": "这里应该用〈整治〉。脏乱的环境、街区要说整治；“扶贫”的对象是贫困的人或地区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老板不扶贫过山区。", "corrected_sentence": "那位老板从没扶贫过山区。", "error_description": "否定词错用：“扶贫过”表示有过的经历，否定应用“没”（从没……过），不能用“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每个假期都回村里扶贫着。", "corrected_sentence": "她每个假期都回村里扶贫。", "error_description": "体标错用：“每个假期”指经常性的动作，不能用表示持续状态的“着”，应去掉“着”，说“回村里扶贫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
