INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93578, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "汉字六书之一，用象征性符号表示抽象意义，如“上”“下”。", "primary_collocate": null, "pronunciation": "zhǐ shì", "ipa": "ʈʂʅ˨˩˦ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "指事是汉字六书之一。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“上”和“下”都是用指事造的字。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天讲了指事。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "六书里有象形、指事、会意和形声。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指事用符号表示抽象的意思。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学过指事，也学过象形。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“本”字是在木上加一点，属于指事。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指事和象形不一样，指事不是画出东西。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说出一个指事的例子吗？", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说“刃”的造字办法是指事。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指事字", "label": "复合"}], "register": "书面", "sense_fingerprint": "汉字六书之一，用符号表示抽象意义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1016e2b9-ce54-4dd3-a2ce-4913bc82850b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93578, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指事", "is_correct": true, "explanation": "正确。指事是汉字六书之一，读 zhǐ shì。"}, {"text": "直视", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，直视的意思是直接看、正视，不是指事。"}, {"text": "指使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，指使的意思是支使别人做事。"}, {"text": "制式", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，制式指规定的样式。"}, {"text": "指实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，指实的意思是明确指出。"}], "explanations": {"指事": "正确。指事是汉字六书之一，读 zhǐ shì。", "直视": "zhí（第二声）与 zhǐ（第三声）声调不同，直视的意思是直接看、正视，不是指事。", "指使": "shǐ（第三声）与 shì（第四声）声调不同，指使的意思是支使别人做事。", "制式": "zhì（第四声）与 zhǐ（第三声）声调不同，制式指规定的样式。", "指实": "shí（第二声）与 shì（第四声）声调不同，指实的意思是明确指出。"}, "sentence_index": null, "correct_answer": "指事"}, "level_3": {"options": [{"text": "指事", "is_correct": true, "explanation": "正确。指事是汉字六书之一。"}, {"text": "偏旁", "is_correct": false, "explanation": "语义：偏旁是构成汉字的部件，不是六书的类别，“偏旁是汉字六书之一”不成立。"}, {"text": "笔顺", "is_correct": false, "explanation": "语义：笔顺是书写笔画的先后次序，不属于六书。"}, {"text": "拼音", "is_correct": false, "explanation": "搭配：拼音是给字注音的系统，不能与“汉字六书之一”搭配。"}], "explanations": {"指事": "正确。指事是汉字六书之一。", "偏旁": "语义：偏旁是构成汉字的部件，不是六书的类别，“偏旁是汉字六书之一”不成立。", "笔顺": "语义：笔顺是书写笔画的先后次序，不属于六书。", "拼音": "搭配：拼音是给字注音的系统，不能与“汉字六书之一”搭配。"}, "sentence_index": 0, "correct_answer": "指事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“日”字是画出太阳的样子，属于指事。", "explanation": "这里应该用〈象形〉。“日”是画出太阳样子的字，属于象形；指事是用符号表示抽象意思，不画具体事物。"}, {"text": "“林”字是两个“木”合在一起，属于指事。", "explanation": "这里应该用〈会意〉。“林”由两个“木”合成，表示树林，属于会意；指事是用符号表示抽象意思。"}, {"text": "“河”字一边表示意思，一边表示读音，属于指事。", "explanation": "这里应该用〈形声〉。“河”一边表示意思、一边表示读音，属于形声；指事不用来表示读音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93578, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "指事", "is_correct": true, "explanation": "正确。指事是汉字六书之一，读 zhǐ shì。"}, {"text": "史事", "is_correct": false, "explanation": "shǐ（第三声）与 zhǐ（第三声）声母不同（sh 与 zh），史事指历史上的事情。"}, {"text": "执事", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，执事指旧时办事的人或从事某种职务。"}, {"text": "志士", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，志士指有远大志向的人。"}, {"text": "知事", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，知事指旧时的地方官。"}], "explanations": {"指事": "正确。指事是汉字六书之一，读 zhǐ shì。", "史事": "shǐ（第三声）与 zhǐ（第三声）声母不同（sh 与 zh），史事指历史上的事情。", "执事": "zhí（第二声）与 zhǐ（第三声）声调不同，执事指旧时办事的人或从事某种职务。", "志士": "zhì（第四声）与 zhǐ（第三声）声调不同，志士指有远大志向的人。", "知事": "zhī（第一声）与 zhǐ（第三声）声调不同，知事指旧时的地方官。"}, "sentence_index": null, "correct_answer": "指事"}, "level_3": {"options": [{"text": "指事", "is_correct": true, "explanation": "正确。“本”字在木上加一点表示抽象意思，属于指事。"}, {"text": "部首", "is_correct": false, "explanation": "语义：部首是归类用的偏旁，“在木上加一点”说的是造字方式，不是部首。"}, {"text": "声旁", "is_correct": false, "explanation": "语义：声旁只表示读音，“在木上加一点”并不是用来标注读音的。"}, {"text": "注音", "is_correct": false, "explanation": "搭配：“属于”后面要接造字的类别，注音是给字标读音，二者不能搭配。"}], "explanations": {"指事": "正确。“本”字在木上加一点表示抽象意思，属于指事。", "部首": "语义：部首是归类用的偏旁，“在木上加一点”说的是造字方式，不是部首。", "声旁": "语义：声旁只表示读音，“在木上加一点”并不是用来标注读音的。", "注音": "搭配：“属于”后面要接造字的类别，注音是给字标读音，二者不能搭配。"}, "sentence_index": 6, "correct_answer": "指事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“然”字本来是燃烧的意思，后来借来表示“然后”，属于指事。", "explanation": "这里应该用〈假借〉。“然”借来表示“然后”，属于假借；指事是用符号表示抽象意思。"}, {"text": "“考”和“老”意思相近，互相解释，属于指事。", "explanation": "这里应该用〈转注〉。“考”和“老”互相解释，属于转注；指事是用符号表示抽象意思的造字法。"}, {"text": "和平鸽是和平的指事。", "explanation": "这里应该用〈象征〉。和平鸽是和平的象征；“指事”是造字的方法，不能用来指一种事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“一”字属于一只指事。", "corrected_sentence": "“一”字属于指事。", "error_description": "量词错误：“只”用于动物等，指事是造字的方法，不能用“只”来数。正确的说法是“属于指事”，不加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“下”字是把指事造出来的。", "corrected_sentence": "“下”字是用指事造出来的。", "error_description": "介词错误：引出造字办法要用“用”，应说“用指事造出来的”。“把”只能引出被处置的对象，“指事”是造字办法，不能被“造出来”，所以“把指事造出来”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
