INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93579, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地产是地和地上盖的房子，是可以买卖的。", "primary_collocate": null, "pronunciation": "dì chǎn", "ipa": "ti˥˩ tʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在城里买了一块地产。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门做地产生意。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷留给我一份地产。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地产的价格每年都在涨。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠卖地产赚了很多钱。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片地产可以买，也可以卖。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把地产卖给朋友。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请人帮忙卖掉了地产。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家有不少地产。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在买地产要先看位置。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "房地产", "label": "复合"}, {"form": "地产商", "label": "复合"}], "register": "通用", "sense_fingerprint": "可以买卖的土地和地上的房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19fac6ab-9a37-4f78-9dc1-d6d821e02fc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93579, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地产", "is_correct": true, "explanation": "正确。“地产”指可以买卖的土地和房屋，量词“块”可用于一块土地，句意通顺。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车的量词是“辆”，不说“一块汽车”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能买，句中的“买了”与之冲突。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：歌曲的量词是“首”，不说“一块歌曲”。"}], "explanations": {"地产": "正确。“地产”指可以买卖的土地和房屋，量词“块”可用于一块土地，句意通顺。", "汽车": "搭配：汽车的量词是“辆”，不说“一块汽车”。", "空气": "语义：空气不能买，句中的“买了”与之冲突。", "歌曲": "搭配：歌曲的量词是“首”，不说“一块歌曲”。"}, "sentence_index": 0, "correct_answer": "地产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔地产包括存款和股票。", "explanation": "这里应该用〈财产〉。地产只指土地和房屋，不包括存款和股票这类财产。"}, {"text": "这家工厂生产的地产很受欢迎。", "explanation": "这里应该用〈产品〉。地产是土地和房屋，不是工厂生产出来的东西。"}, {"text": "他把地产存进了银行。", "explanation": "这里应该用〈现金〉。地产是不动产，不能存进银行，存进去的是〈现金〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bce51fc-b7c3-4ba9-b3a8-30d9cbf7843c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93579, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地产", "is_correct": true, "explanation": "正确。“卖给朋友”的对象是可以买卖的土地和房屋，符合句意。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸无法买卖，与“卖给朋友”冲突。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“卖”不搭配“体温”，体温一般说“量”。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的投影，不能拿来卖给别人。"}], "explanations": {"地产": "正确。“卖给朋友”的对象是可以买卖的土地和房屋，符合句意。", "呼吸": "语义：呼吸无法买卖，与“卖给朋友”冲突。", "体温": "搭配：“卖”不搭配“体温”，体温一般说“量”。", "影子": "语义：影子是光线形成的投影，不能拿来卖给别人。"}, "sentence_index": 6, "correct_answer": "地产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的地产每个月都要交学费。", "explanation": "这里应该用〈钱〉。地产是土地和房屋，不能用来交学费，交学费要用〈钱〉。"}, {"text": "他的地产每年的利息很高。", "explanation": "这里应该用〈存款〉或〈债券〉。地产是土地和房屋，不会产生利息，能产生利息的是存款或债券。"}, {"text": "这次研究的地产让大家很满意。", "explanation": "这里应该用〈成果〉。地产指土地和房屋，不指研究的成果，研究成果应说〈成果〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bce51fc-b7c3-4ba9-b3a8-30d9cbf7843c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只地产靠近地铁站。", "corrected_sentence": "这块地产靠近地铁站。", "error_description": "量词错误：“地产”的量词应为“块”。写成“这只地产”错用了动物量词“只”。正确形式：这块地产靠近地铁站。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bce51fc-b7c3-4ba9-b3a8-30d9cbf7843c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年卖了掉一块地产。", "corrected_sentence": "他去年卖掉了一块地产。", "error_description": "结果补语位置错误：“卖掉”中的“掉”是结果补语，应紧接动词“卖”，不能插在“了”之后。写成“卖了掉”是错误的。正确形式：他去年卖掉了一块地产。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bce51fc-b7c3-4ba9-b3a8-30d9cbf7843c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
