INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93583, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93583, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女的是女人或女孩。", "primary_collocate": null, "pronunciation": "nǚ de", "ipa": "ny˨˩˦ tɤ", "syllable_count": 2, "sentences": [{"text": "门口站着一个女的。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女的是我的新同事。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天遇到一个女的，她说认识你。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚才有个女的找你。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见一个女的在等公共汽车。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女的手里拿着一本书。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面走的那个女的是我姐姐。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在我旁边的女的很安静。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女的长得很高。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来了一个女的，说找王经理。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "指某个具体的女人或女孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab46821f-b651-4563-9f21-fba4344ba828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93583, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女的", "is_correct": true, "explanation": "“女的”指女人或女孩，符合“门口站着一个”的句意。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“站着”的主语要是人或动物，桌子不能站立。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，与“站着”不搭，句意不通。"}, {"text": "箱子", "is_correct": false, "explanation": "配价：“站着”要求有生命的主语，箱子不能站立。"}], "explanations": {"女的": "“女的”指女人或女孩，符合“门口站着一个”的句意。", "桌子": "配价：“站着”的主语要是人或动物，桌子不能站立。", "石头": "语义：石头是无生命的物体，与“站着”不搭，句意不通。", "箱子": "配价：“站着”要求有生命的主语，箱子不能站立。"}, "sentence_index": 0, "correct_answer": "女的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的女的今年七岁了。", "explanation": "这里应该用〈女儿〉。“女的”是泛称，不表示亲子关系，指自己的女儿要说“女儿”。"}, {"text": "院子里那棵树是女的，开的花很香。", "explanation": "这里应该用〈雌〉。“女的”只指人，不用于植物，雌性的树要说“雌”。"}, {"text": "这只鸡是女的，每天能下两个蛋。", "explanation": "这里应该用〈母〉。“女的”只指人，指动物的性别要用“母”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女的", "is_correct": true, "explanation": "“女的”指女人或女孩，与“我姐姐”的性别一致，句意通顺。"}, {"text": "男的", "is_correct": false, "explanation": "语义：“男的”与“我姐姐”的性别矛盾，句意不通。"}, {"text": "猫", "is_correct": false, "explanation": "配价：“是……姐姐”要求人作主语，猫不能是我姐姐。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不会走路，也不能是我姐姐，句意不通。"}], "explanations": {"女的": "“女的”指女人或女孩，与“我姐姐”的性别一致，句意通顺。", "男的": "语义：“男的”与“我姐姐”的性别矛盾，句意不通。", "猫": "配价：“是……姐姐”要求人作主语，猫不能是我姐姐。", "花": "语义：花不会走路，也不能是我姐姐，句意不通。"}, "sentence_index": 6, "correct_answer": "女的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车是女的，开起来很快。", "explanation": "这里不能用“女的”。“女的”指女性，只用于人，车辆没有性别，应直接说“开起来很快”。"}, {"text": "这块石头是女的，颜色很漂亮。", "explanation": "这里不能用“女的”。“女的”只指人，石头没有性别，应直接说“这块石头”。"}, {"text": "这把椅子是女的，坐起来很舒服。", "explanation": "这里不能用“女的”。“女的”只指人，椅子没有性别，应直接说“这把椅子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前台那只女的很热心。", "corrected_sentence": "前台那个女的很热心。", "error_description": "量词错误：“女的”指人，量词应用“个”；“只”多用于动物，不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刚进来一只女的，问你在不在。", "corrected_sentence": "刚进来一个女的，问你在不在。", "error_description": "量词错误：“女的”指人，量词应用“个”；“只”多用于动物，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
