INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93584, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93584, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女性（口语）。", "primary_collocate": null, "pronunciation": "nǚ de", "ipa": "ny˨˩˦ tɤ", "syllable_count": 2, "sentences": [{"text": "我们班男的多，女的少。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男的坐左边，女的坐右边。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛，男的女的都能参加。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司女的比男的多。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这家店的客人大多是女的。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车上有一个男的和一个女的。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们那儿男的做饭，女的上班。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏女的玩得比男的多。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队男的五个，女的六个。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场里买衣服的大多是女的。", "target_word": "女的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "与男的相对，泛指女性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab46821f-b651-4563-9f21-fba4344ba828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女的", "is_correct": true, "explanation": "“女的”指女性，与前句的“男的”相对，句意通顺。"}, {"text": "男的", "is_correct": false, "explanation": "语义：前半句已说“男的多”，后半句又说“男的少”，自相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“多”“少”在此比较人数，桌子不是人，无法与“男的多”形成人数对比，句意不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是人，不能与“男的多”形成人数上的对比。"}], "explanations": {"女的": "“女的”指女性，与前句的“男的”相对，句意通顺。", "男的": "语义：前半句已说“男的多”，后半句又说“男的少”，自相矛盾。", "桌子": "语义：“多”“少”在此比较人数，桌子不是人，无法与“男的多”形成人数对比，句意不通。", "书": "语义：书不是人，不能与“男的多”形成人数上的对比。"}, "sentence_index": 0, "correct_answer": "女的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天是三八女的节。", "explanation": "这里应该用〈妇女〉。“妇女节”是固定说法，“女的”不能用于节日名称。"}, {"text": "我们班养的鸟大多是女的。", "explanation": "这里应该用〈母〉。“女的”只指人，指动物的性别要用“母”，鸟应说“母的”。"}, {"text": "门口那棵大树是女的，开的花很香。", "explanation": "这里应该用〈雌〉。“女的”只指人，不用于植物，雌性的树要说“雌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女的", "is_correct": true, "explanation": "“女的”指女性，与前句的“男的做饭”形成对比，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“上班”要求人作主语，石头不能上班。"}, {"text": "孩子", "is_correct": false, "explanation": "配价：“上班”要求成年人作主语，孩子不能上班。"}, {"text": "狗", "is_correct": false, "explanation": "配价：“上班”的主语须是人，狗不能上班。"}], "explanations": {"女的": "“女的”指女性，与前句的“男的做饭”形成对比，句意通顺。", "石头": "配价：“上班”要求人作主语，石头不能上班。", "孩子": "配价：“上班”要求成年人作主语，孩子不能上班。", "狗": "配价：“上班”的主语须是人，狗不能上班。"}, "sentence_index": 6, "correct_answer": "女的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商场里的货架大多是女的。", "explanation": "这里不能用“女的”。“女的”只指人，货架没有性别，应直接说“商场里的货架”。"}, {"text": "商场里的沙发大多是女的。", "explanation": "这里不能用“女的”。“女的”只指人，沙发没有性别，应直接说“商场里的沙发”。"}, {"text": "商场里的电梯大多是女的。", "explanation": "这里不能用“女的”。“女的”只指人，电梯没有性别，应直接说“商场里的电梯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛，一只女的也能参加。", "corrected_sentence": "这次比赛，一个女的也能参加。", "error_description": "量词错误：“女的”指人，量词应用“个”；“只”多用于动物，不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店进来了一只女的。", "corrected_sentence": "这家店进来了一个女的。", "error_description": "量词错误：“女的”指人，量词应用“个”；“只”多用于动物，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
