INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93594, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对国家政治制度、体制和管理方式进行的改变和革新。", "primary_collocate": null, "pronunciation": "zhèng zhì gǎi gé", "ipa": "ʈʂɤŋ˥˩ ʈʂʅ˥˩ kaɪ˨˩˦ kɤ˧˥", "syllable_count": 4, "sentences": [{"text": "这次政治改革改变了国家的管理方式。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治改革会改变国家的政治制度。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究过那个国家的政治改革。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的政治改革开始于二十年前。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治改革是对体制的一种革新。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有很多关于政治改革的文章。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治改革并不容易，需要大家支持。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府宣布了新的政治改革方案。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场政治改革把旧制度改成了新制度。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者们正在讨论政治改革的方向。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}], "register": "书面", "sense_fingerprint": "对国家政治制度、体制和管理方式的革新", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1016e2b9-ce54-4dd3-a2ce-4913bc82850b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93594, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政治改革", "is_correct": true, "explanation": "正确。这次改变国家管理方式的正是政治改革。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能改变国家的管理方式。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球比赛不会改变国家的管理方式。"}, {"text": "花卉", "is_correct": false, "explanation": "搭配：“改变国家的管理方式”的主语需要是事件或制度，花卉不能作主语。"}], "explanations": {"政治改革": "正确。这次改变国家管理方式的正是政治改革。", "天气": "语义：天气不能改变国家的管理方式。", "足球": "语义：足球比赛不会改变国家的管理方式。", "花卉": "搭配：“改变国家的管理方式”的主语需要是事件或制度，花卉不能作主语。"}, "sentence_index": 0, "correct_answer": "政治改革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政治改革在电视上回答了观众的提问。", "explanation": "这里应该用〈候选人〉。能回答观众提问的是人，“政治改革”不能回答问题。"}, {"text": "政治改革在考试中得了满分。", "explanation": "这里应该用〈学生〉。能参加考试、得满分的是学生，“政治改革”是事件，不能参加考试。"}, {"text": "政治改革在会议上发表了演讲。", "explanation": "这里应该用〈议员〉。议员在会议上发表演讲，“政治改革”是事件，不会发表演讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政治改革", "is_correct": true, "explanation": "正确。“政治改革”本身就是需要大家支持的事情。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是图，不是需要大家支持才能完成的事情。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是“并不容易，需要大家支持”描述的事。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“并不容易，需要大家支持”描述要做的事，冰箱不能作这样的主语。"}], "explanations": {"政治改革": "正确。“政治改革”本身就是需要大家支持的事情。", "地图": "语义：地图是图，不是需要大家支持才能完成的事情。", "桌子": "语义：桌子是家具，不是“并不容易，需要大家支持”描述的事。", "冰箱": "搭配：“并不容易，需要大家支持”描述要做的事，冰箱不能作这样的主语。"}, "sentence_index": 6, "correct_answer": "政治改革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政治改革正在采访总统。", "explanation": "这里应该用〈记者〉。采访的是记者，“政治改革”是事件，不能去采访人。"}, {"text": "选民把政治改革投进了箱子。", "explanation": "这里应该用〈选票〉。投进箱子的是选票，“政治改革”不是可以投进箱子的东西。"}, {"text": "这个政治改革赢得了大多数席位。", "explanation": "这里应该用〈政党〉。席位是政党通过选举赢得的，“政治改革”不能赢得席位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座政治改革给人民带来了很多变化。", "corrected_sentence": "这次政治改革给人民带来了很多变化。", "error_description": "量词错误：“座”用于山、桥、建筑等，“政治改革”是事件，应该用“次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些国家也举行了政治改革。", "corrected_sentence": "这些国家也进行了政治改革。", "error_description": "搭配错误：“政治改革”通常与“进行”搭配，说“进行了政治改革”；“举行”多用于会议、仪式、比赛等活动，不能说“举行政治改革”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb151e1-566d-44d1-b4c0-54fa7e581ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
