INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93595, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学员是在一个班里学东西的人。", "primary_collocate": null, "pronunciation": "xué yuán", "ipa": "ɕɥe˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "驾校的学员正在练习开车。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈班有二十多个学员。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳班的学员都很小。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练让学员先热身。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学员跳舞跳得很好。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学员们跟着老师学做蛋糕。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画班的学员周末要交作业。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新学员下周一来报名。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学员每周来上两次课。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学员们在教室里练习写毛笔字。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "學員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在驾校、舞蹈班等班里学一门技能的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bdf063c-4c7f-4fb1-bb18-7cd2426d705d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93595, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学员", "is_correct": true, "explanation": "学员（xué yuán）指在班里学东西的人，是听到的正确词语。"}, {"text": "学院", "is_correct": false, "explanation": "学院（xué yuàn）第四声，与学员的 yuán（第二声）声调不同，意思是大学的一个学部。"}, {"text": "雪原", "is_correct": false, "explanation": "雪原（xuě yuán）的首音节是第三声，与学员的 xué（第二声）声调不同，意思是覆盖着雪的大片平原。"}, {"text": "血缘", "is_correct": false, "explanation": "血缘（xuè yuán）的首音节是第四声，与学员的 xué（第二声）声调不同，意思是血统上的联系。"}], "explanations": {"学员": "学员（xué yuán）指在班里学东西的人，是听到的正确词语。", "学院": "学院（xué yuàn）第四声，与学员的 yuán（第二声）声调不同，意思是大学的一个学部。", "雪原": "雪原（xuě yuán）的首音节是第三声，与学员的 xué（第二声）声调不同，意思是覆盖着雪的大片平原。", "血缘": "血缘（xuè yuán）的首音节是第四声，与学员的 xué（第二声）声调不同，意思是血统上的联系。"}, "sentence_index": null, "correct_answer": "学员"}, "level_3": {"options": [{"text": "学员", "is_correct": true, "explanation": "正确：学员指在驾校学车的人，与“练习开车”相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是乘车的人，不会在驾校练习开车。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来游览的人，与驾校练车无关。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“练习开车”的主语应是人，教室不能练车。"}], "explanations": {"学员": "正确：学员指在驾校学车的人，与“练习开车”相符。", "乘客": "语义：乘客是乘车的人，不会在驾校练习开车。", "游客": "语义：游客是来游览的人，与驾校练车无关。", "教室": "搭配：“练习开车”的主语应是人，教室不能练车。"}, "sentence_index": 0, "correct_answer": "学员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在超市里买了一名学员。", "explanation": "这里应该用〈商品〉。学员指在班里学东西的人，超市里买的东西叫商品，不能说学员。"}, {"text": "工地上堆着很多学员。", "explanation": "这里应该用〈砖〉。学员指在班里学东西的人，工地上堆着的建材是砖。"}, {"text": "我在厨房里煮了三个学员。", "explanation": "这里应该用〈鸡蛋〉。学员指在班里学东西的人，厨房里煮的是鸡蛋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学员", "is_correct": true, "explanation": "正确：学员指在班里学东西的人，周末要交作业，符合句意。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师负责批改作业，不用自己交作业。"}, {"text": "画笔", "is_correct": false, "explanation": "语义：画笔是工具，不能交作业。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：“交作业”的主语应是人，颜料不能交作业。"}], "explanations": {"学员": "正确：学员指在班里学东西的人，周末要交作业，符合句意。", "老师": "语义：老师负责批改作业，不用自己交作业。", "画笔": "语义：画笔是工具，不能交作业。", "颜料": "搭配：“交作业”的主语应是人，颜料不能交作业。"}, "sentence_index": 6, "correct_answer": "学员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "驾校门口的冰箱里放着很多学员。", "explanation": "这里应该用〈饮料〉。学员指在班里学东西的人，冰箱里放着、可以喝的是饮料。"}, {"text": "驾校的柜子上摆满了学员。", "explanation": "这里应该用〈书〉。学员指在班里学东西的人，柜子上摆着、可以借阅的是书。"}, {"text": "驾校的院子里种满了学员。", "explanation": "这里应该用〈树〉。学员指在班里学东西的人，院子里种的是树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "驾校里有两辆学员在等教练。", "corrected_sentence": "驾校里有两名学员在等教练。", "error_description": "错误：量词“辆”；正确：“名”。“辆”用于车辆，学员是人，应用“名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张学员下午要去练车。", "corrected_sentence": "这名学员下午要去练车。", "error_description": "错误：量词“张”；正确：“名”。“张”用于平面的东西，学员是人，应用“名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
