INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参加培训或学习班的学习者。", "primary_collocate": null, "pronunciation": "xué yuán", "ipa": "ɕɥe˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "参加培训的学员已经到齐了。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次培训班有三十名学员。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学员们每天早上八点上课。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给学员发了新的材料。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学员学习很认真。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "培训结束后，学员都拿到了证书。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请专家给新学员讲课。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学员可以在网上问老师问题。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些学员来自不同的城市。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "培训班的学员今天去工厂参观。", "target_word": "学员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "學員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "参加培训班、接受培训的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bdf063c-4c7f-4fb1-bb18-7cd2426d705d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93596, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学员", "is_correct": true, "explanation": "学员（xué yuán）指参加培训班的人，是听到的正确词语。"}, {"text": "学院", "is_correct": false, "explanation": "学院（xué yuàn）第四声，与学员的 yuán（第二声）声调不同，意思是大学的一个学部。"}, {"text": "雪原", "is_correct": false, "explanation": "雪原（xuě yuán）的首音节是第三声，与学员的 xué（第二声）声调不同，意思是覆盖着雪的大片平原。"}, {"text": "血缘", "is_correct": false, "explanation": "血缘（xuè yuán）的首音节是第四声，与学员的 xué（第二声）声调不同，意思是血统上的联系。"}], "explanations": {"学员": "学员（xué yuán）指参加培训班的人，是听到的正确词语。", "学院": "学院（xué yuàn）第四声，与学员的 yuán（第二声）声调不同，意思是大学的一个学部。", "雪原": "雪原（xuě yuán）的首音节是第三声，与学员的 xué（第二声）声调不同，意思是覆盖着雪的大片平原。", "血缘": "血缘（xuè yuán）的首音节是第四声，与学员的 xué（第二声）声调不同，意思是血统上的联系。"}, "sentence_index": null, "correct_answer": "学员"}, "level_3": {"options": [{"text": "学员", "is_correct": true, "explanation": "正确：学员指参加培训的人，与“参加培训的”及句意相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来旅游的人，与参加培训不相干。"}, {"text": "车辆", "is_correct": false, "explanation": "搭配：“参加”的对象应是人，车辆不能参加培训。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是搭乘交通工具的人，与培训班无关。"}], "explanations": {"学员": "正确：学员指参加培训的人，与“参加培训的”及句意相符。", "游客": "语义：游客是来旅游的人，与参加培训不相干。", "车辆": "搭配：“参加”的对象应是人，车辆不能参加培训。", "乘客": "语义：乘客是搭乘交通工具的人，与培训班无关。"}, "sentence_index": 0, "correct_answer": "学员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的女儿是小学学员。", "explanation": "这里应该用〈学生〉。学员指参加培训班的人，在学校读书的孩子叫学生。"}, {"text": "这家医院每天有三千名学员来看病。", "explanation": "这里应该用〈病人〉。学员指参加培训的人，来医院看病的人叫病人。"}, {"text": "今天给我们上课的学员很有经验。", "explanation": "这里应该用〈老师〉。学员是接受培训的人，负责上课、讲课的人叫老师，学员不能给别人讲课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学员", "is_correct": true, "explanation": "正确：学员指接受培训的人，专家给他们讲课，符合句意。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是看病的人，公司请专家讲课的对象不会是病人。"}, {"text": "马路", "is_correct": false, "explanation": "搭配：“讲课”的对象应是人，马路不能听课。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能听课，与“讲课”的对象矛盾。"}], "explanations": {"学员": "正确：学员指接受培训的人，专家给他们讲课，符合句意。", "病人": "语义：病人是看病的人，公司请专家讲课的对象不会是病人。", "马路": "搭配：“讲课”的对象应是人，马路不能听课。", "书": "语义：书不能听课，与“讲课”的对象矛盾。"}, "sentence_index": 6, "correct_answer": "学员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店每天卖出三百名学员。", "explanation": "这里应该用〈水果〉。学员指参加培训的人，店里卖出去的是水果，不能说学员。"}, {"text": "我在院子里种了一名学员。", "explanation": "这里应该用〈花〉。学员指参加培训的人，院子里种的是花，不能说学员。"}, {"text": "仓库里堆满了学员。", "explanation": "这里应该用〈货物〉。学员指参加培训的人，仓库里堆的是货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里有二十只学员正在上课。", "corrected_sentence": "班里有二十名学员正在上课。", "error_description": "错误：量词“只”；正确：“名”。“只”多用于动物等，学员是人，应用量词“名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这五辆学员都通过了考核。", "corrected_sentence": "这五名学员都通过了考核。", "error_description": "错误：量词“辆”；正确：“名”。“辆”用于车辆，学员是人，应用“名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
