INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93599, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "岗位是一个人在工作时站的地方，也是他要做的事。", "primary_collocate": null, "pronunciation": "gǎng wèi", "ipa": "kɑŋ˨˩˦ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "警察一直坚守在岗位上。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在岗位上工作了一夜。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安不能随便离开岗位。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回到自己的岗位，继续工作。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，战士还站在岗位上。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，护士都在各自的岗位上。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，上班时不要离开岗位。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在岗位上站了八个小时。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都要守好自己的岗位。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家很快回到了各自的岗位。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "崗位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工作时所守的位置和负责的事，常与坚守、离开搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bdf063c-4c7f-4fb1-bb18-7cd2426d705d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93599, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "岗位", "is_correct": true, "explanation": "正确：岗位指工作时守的地方，“坚守在……上”的对象正是岗位。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“坚守”要守住工作地点，课本不是工作地点。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被坚守，句子不通。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：“坚守在……上”要求工作场所，篮球不是。"}], "explanations": {"岗位": "正确：岗位指工作时守的地方，“坚守在……上”的对象正是岗位。", "课本": "语义：“坚守”要守住工作地点，课本不是工作地点。", "天空": "语义：天空不能被坚守，句子不通。", "篮球": "搭配：“坚守在……上”要求工作场所，篮球不是。"}, "sentence_index": 0, "correct_answer": "岗位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "超市的货架上摆着很多岗位，可以随便挑。", "explanation": "这里应该用〈商品〉。岗位指工作时站守的地方，货架上摆着、可以挑选的是商品。"}, {"text": "我在河边钓到了一个岗位。", "explanation": "这里应该用〈鱼〉。岗位指工作时站守的地方，河边钓上来的是鱼。"}, {"text": "我们在厨房里切了一个岗位。", "explanation": "这里应该用〈菜〉。岗位指工作时站守的地方，厨房里切的是菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "岗位", "is_correct": true, "explanation": "正确：岗位指工作时的位置，“离开岗位”符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是工作场所，上班时不能说离开空气。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不是可以离开的工作地点，句子不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“离开”的宾语应是地方或人，不能说离开歌曲。"}], "explanations": {"岗位": "正确：岗位指工作时的位置，“离开岗位”符合句意。", "空气": "语义：空气不是工作场所，上班时不能说离开空气。", "眼睛": "语义：眼睛不是可以离开的工作地点，句子不通。", "歌曲": "搭配：“离开”的宾语应是地方或人，不能说离开歌曲。"}, "sentence_index": 6, "correct_answer": "岗位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在文具店买了三个岗位，回家慢慢看。", "explanation": "这里应该用〈书〉。岗位指工作时站守的地方，买回家慢慢看的是书。"}, {"text": "学校门口种着很多岗位，每年春天都会开花。", "explanation": "这里应该用〈树〉。岗位指工作时站守的地方，门口种着、春天会开花的是树。"}, {"text": "医院门口摆着很多岗位，可以免费喝。", "explanation": "这里应该用〈饮料〉。岗位指工作时站守的地方，门口摆着、可以免费喝的是饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士一夜守在这辆岗位上。", "corrected_sentence": "护士一夜守在这个岗位上。", "error_description": "错误：量词“辆”；正确：“个”。“辆”用于车辆，岗位应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都回到了各自地岗位。", "corrected_sentence": "大家都回到了各自的岗位。", "error_description": "错误：“各自地岗位”中用了状语助词“地”。“各自”后修饰名词要用定语助词“的”，应说“各自的岗位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a578e366-c264-4846-adaf-cdc57226b974') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
