INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93603, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "感动是心里热热的，觉得很暖，想要哭。", "primary_collocate": null, "pronunciation": "gǎn dòng", "ipa": "kan˨˩˦ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我看着这封信，心里热热的，真感动。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这首歌，我感动得想哭。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子给我倒了一杯热水，我感动极了。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在雨里等我，我心里很暖，特别感动。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到爸爸写的信，我感动得流泪了。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友记得我的生日，我心里暖暖的，真感动。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶煮了一碗热面给我，我很感动。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她感动得想哭，一句话也说不出来。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸我了，我心里暖暖的，很感动。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都来看我，我感动得哭了。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感动了", "label": "体标"}, {"form": "感动过", "label": "体标"}], "register": "中性", "sense_fingerprint": "感动·动词·心里发热发暖、想要哭的感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19fac6ab-9a37-4f78-9dc1-d6d821e02fc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93603, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感动", "is_correct": true, "explanation": "正确。“真感动”表示心里发热、想哭的感受，与“心里热热的”一致。"}, {"text": "发抖", "is_correct": false, "explanation": "语义：心里热热的，不会发抖，与句中的感受冲突。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“热热的”与“结冰”相反，心里不会结冰。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”只用于金属等物体，不用于形容人的心情。"}], "explanations": {"感动": "正确。“真感动”表示心里发热、想哭的感受，与“心里热热的”一致。", "发抖": "语义：心里热热的，不会发抖，与句中的感受冲突。", "结冰": "语义：“热热的”与“结冰”相反，心里不会结冰。", "生锈": "搭配：“生锈”只用于金属等物体，不用于形容人的心情。"}, "sentence_index": 0, "correct_answer": "感动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜里路很黑，我很感动。", "explanation": "这里应该用〈害怕〉。感动表示心里发暖、想哭，不表示害怕。"}, {"text": "他误会了我，我很感动。", "explanation": "这里应该用〈委屈〉。感动表示心里发热，不表示被误会后的委屈。"}, {"text": "他骗了我，我很感动。", "explanation": "这里应该用〈生气〉。感动是心里发暖的感受，不表示被欺骗后的愤怒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bce51fc-b7c3-4ba9-b3a8-30d9cbf7843c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感动", "is_correct": true, "explanation": "正确。“我很感动”表示心里暖暖的，与奶奶煮面给我的情境相符。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：奶奶煮面给我是出于关心，“怀疑”与句中情境冲突。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：奶奶的关心不应被“嫌弃”，与句意冲突。"}, {"text": "发愁", "is_correct": false, "explanation": "搭配：“发愁”多指为某事犯愁，不用来形容接受关心时的感受。"}], "explanations": {"感动": "正确。“我很感动”表示心里暖暖的，与奶奶煮面给我的情境相符。", "怀疑": "语义：奶奶煮面给我是出于关心，“怀疑”与句中情境冲突。", "嫌弃": "语义：奶奶的关心不应被“嫌弃”，与句意冲突。", "发愁": "搭配：“发愁”多指为某事犯愁，不用来形容接受关心时的感受。"}, "sentence_index": 6, "correct_answer": "感动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试前我很感动。", "explanation": "这里应该用〈紧张〉。感动表示心里发热，不表示考试前的不安。"}, {"text": "周末在家，我很感动。", "explanation": "这里应该用〈无聊〉。感动表示心里发热，不表示闲着没事的感受。"}, {"text": "当众出丑，我很感动。", "explanation": "这里应该用〈尴尬〉。感动表示心里发热，不表示出丑时的窘迫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bce51fc-b7c3-4ba9-b3a8-30d9cbf7843c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份礼物让我特地感动。", "corrected_sentence": "这份礼物让我特别感动。", "error_description": "程度副词错误：“感动”前应用程度副词“特别”，“特地”表示专门、有意，不能修饰“感动”。正确形式：这份礼物让我特别感动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bce51fc-b7c3-4ba9-b3a8-30d9cbf7843c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈的话让我感动说不出话。", "corrected_sentence": "妈妈的话让我感动得说不出话。", "error_description": "程度补语漏掉“得”：“感动”后要用“得”引出结果补语，不能省略。正确形式：妈妈的话让我感动得说不出话。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bce51fc-b7c3-4ba9-b3a8-30d9cbf7843c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
