INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93621, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "标准组织是制定大家要共同遵守的规格的团体。", "primary_collocate": null, "pronunciation": "biāo zhǔn zǔ zhī", "ipa": "piɑʊ˥ ʈʂuən˨˩˦ tsu˨˩˦ ʈʂɨ˥", "syllable_count": 4, "sentences": [{"text": "标准组织定的规格，大家都要遵守。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂必须按标准组织的要求做产品。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标准组织为手机充电口定了统一的规格。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有标准组织，每家公司的规格都会不一样。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准组织请各个公司派人来一起开会。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的产品通过了标准组织的检查。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标准组织的人正在讨论新的规格。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道哪个标准组织管这种电池。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准组织把新规格寄给了所有工厂。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王是这个标准组织的老成员。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "標準組織", "label": "繁体"}], "register": "正式", "sense_fingerprint": "制定大家共同遵守的规格的团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '086a2607-6390-45a4-bc25-eb84138f39a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93621, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能制定规格。"}, {"text": "标准组织", "is_correct": true, "explanation": "制定大家共同遵守的规格的团体，填“标准组织”。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能制定规格。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“定的规格”一般由机构制定，不说“冰箱定的规格”。"}], "explanations": {"天气": "语义：天气不能制定规格。", "标准组织": "制定大家共同遵守的规格的团体，填“标准组织”。", "小猫": "语义：小猫是动物，不能制定规格。", "冰箱": "搭配：“定的规格”一般由机构制定，不说“冰箱定的规格”。"}, "sentence_index": 0, "correct_answer": "标准组织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个标准组织是三年前定的。", "explanation": "这里应该用〈标准〉。标准组织是团体，“定的”指的是标准文件。"}, {"text": "这个标准组织每天都生产很多零件。", "explanation": "这里应该用〈工厂〉。标准组织制定规格，不生产零件，生产零件的应是工厂。"}, {"text": "这种标准组织的电池很常见。", "explanation": "这里应该用〈规格〉。应说“这种规格的电池”，标准组织是团体，不是规格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是机构，没有“人”在讨论规格。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能讨论规格。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“讨论规格”的主语应是机构或人群，不说“小说的人”。"}, {"text": "标准组织", "is_correct": true, "explanation": "制定规格的团体，其中的人才会讨论新规格，填“标准组织”。"}], "explanations": {"海洋": "语义：海洋不是机构，没有“人”在讨论规格。", "饼干": "语义：饼干是食品，不能讨论规格。", "小说": "搭配：“讨论规格”的主语应是机构或人群，不说“小说的人”。", "标准组织": "制定规格的团体，其中的人才会讨论新规格，填“标准组织”。"}, "sentence_index": 6, "correct_answer": "标准组织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家标准组织每个月都给客户发很多贷款。", "explanation": "这里应该用〈银行〉。标准组织不发放贷款，发放贷款的应是银行。"}, {"text": "这家标准组织每年招一千个新学生。", "explanation": "这里应该用〈学校〉。标准组织不招学生，招新生的应是学校。"}, {"text": "这家标准组织每天都有很多病人看病。", "explanation": "这里应该用〈医院〉。标准组织不看病，有病人看病的应是医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只标准组织对产品要求很严格。", "corrected_sentence": "这家标准组织对产品要求很严格。", "error_description": "量词错误：“只”用于动物，机构应用“家”或“个”，应为“这家标准组织”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们想找一所能认证的标准组织。", "corrected_sentence": "我们想找一家能认证的标准组织。", "error_description": "量词错误：“所”用于学校、医院等，标准组织应用“家”或“个”，应为“一家能认证的标准组织”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
