INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93622, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责制定和发布标准、规范的机构或团体。", "primary_collocate": null, "pronunciation": "biāo zhǔn zǔ zhī", "ipa": "piɑʊ˥ ʈʂuən˨˩˦ tsu˨˩˦ ʈʂɨ˥", "syllable_count": 4, "sentences": [{"text": "这个标准组织每年都会发布新的规范。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标准组织的总部在日内瓦。", "target_word": "标准组织", "complexity_tier": "T3", "furigana": "zhè ge biāo zhǔn zǔ zhī de zǒng bù zài Rì nèi wǎ", "sentence_source": "generated"}, {"text": "他在一个标准组织里做研究工作。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准组织已经把新的规定发给各国公司了。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多公司都想加入这个标准组织。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标准组织负责制定电子产品的标准。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准组织开了三天会，终于定下了新方案。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在一家标准组织工作过。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准组织的网站上能找到这些文件。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标准组织成立于很多年以前。", "target_word": "标准组织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "標準組織", "label": "繁体"}], "register": "正式", "sense_fingerprint": "制定并发布标准规范的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '086a2607-6390-45a4-bc25-eb84138f39a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机不是机构，不能“发布规范”。"}, {"text": "标准组织", "is_correct": true, "explanation": "能“发布新的规范”的机构，填“标准组织”。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是作品，不能制定或发布规范。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“发布规范”的主语应是机构，不说“考试发布规范”。"}], "explanations": {"手机": "语义：手机不是机构，不能“发布规范”。", "标准组织": "能“发布新的规范”的机构，填“标准组织”。", "电影": "语义：电影是作品，不能制定或发布规范。", "考试": "搭配：“发布规范”的主语应是机构，不说“考试发布规范”。"}, "sentence_index": 0, "correct_answer": "标准组织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "标准组织每年都会推出新款手机。", "explanation": "这里应该用〈公司〉。标准组织负责制定规范，不生产手机，新款手机应由公司推出。"}, {"text": "标准组织每年都招收很多新学生。", "explanation": "这里应该用〈学校〉。标准组织制定规范，不招收学生，招收新生的应是学校。"}, {"text": "标准组织每天都为游客安排导游。", "explanation": "这里应该用〈旅行社〉。标准组织不安排导游，为游客安排导游的应是旅行社。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海豚", "is_correct": false, "explanation": "语义：海豚不是机构，不会开会。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能开会或定方案。"}, {"text": "西瓜", "is_correct": false, "explanation": "搭配：“开会”的主语应是人或机构，不说“西瓜开会”。"}, {"text": "标准组织", "is_correct": true, "explanation": "能“开会、定下方案”的机构，填“标准组织”。"}], "explanations": {"海豚": "语义：海豚不是机构，不会开会。", "冰箱": "语义：冰箱是家电，不能开会或定方案。", "西瓜": "搭配：“开会”的主语应是人或机构，不说“西瓜开会”。", "标准组织": "能“开会、定下方案”的机构，填“标准组织”。"}, "sentence_index": 6, "correct_answer": "标准组织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个标准组织每天都做很多好吃的菜。", "explanation": "这里应该用〈饭店〉。标准组织不做菜，做菜的应是饭店。"}, {"text": "这家标准组织每天都抓很多小偷。", "explanation": "这里应该用〈警察局〉。标准组织不抓小偷，抓小偷的应是警察局。"}, {"text": "这个标准组织每年都治好很多病人。", "explanation": "这里应该用〈医院〉。标准组织不治病，治病的应是医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只标准组织去年新定了三项规范。", "corrected_sentence": "这家标准组织去年新定了三项规范。", "error_description": "量词错误：“只”用于动物，机构应用“家”或“个”，应为“这家标准组织”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位标准组织的会议下周召开。", "corrected_sentence": "这家标准组织的会议下周召开。", "error_description": "量词错误：“位”用于人，标准组织是机构，应用“家”或“个”，应为“这家标准组织”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
