INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93623, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93623, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "果然是事情真的和你想的一样。", "primary_collocate": null, "pronunciation": "guǒ rán", "ipa": "kuo˨˩˦ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "天气预报说今天有雨，下午果然下雨了。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早就觉得他会来，他果然来了。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这家饭馆很好吃，我去吃了，果然不错。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这本书好看，我读了，果然好看。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说明天会早到，第二天他果然七点就到了。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我猜妈妈在厨房，一看，妈妈果然在做饭。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说多休息就会好，我休息了三天，果然好了。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来很累，一问，果然是一夜没睡。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西很便宜，买回家一用，果然很好用。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王说他会赢，比赛结束后，他果然赢了。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情的结果与先前的预料或说法相符", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c64dac-31c4-43a0-9af4-743730ddc3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果然", "is_correct": true, "explanation": "果然：表示事情与预料相符，符合“天气预报说今天有雨”。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词连用，不能直接用于肯定的“下雨了”。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”要与否定词或习惯性说法连用，不能用于“下雨了”这样的一次性事件。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”指过去有过的经历，与“下午这一次下雨”的预料应验之义不合。"}], "explanations": {"果然": "果然：表示事情与预料相符，符合“天气预报说今天有雨”。", "根本": "搭配：“根本”通常与否定词连用，不能直接用于肯定的“下雨了”。", "从来": "搭配：“从来”要与否定词或习惯性说法连用，不能用于“下雨了”这样的一次性事件。", "曾经": "体貌：“曾经”指过去有过的经历，与“下午这一次下雨”的预料应验之义不合。"}, "sentence_index": 0, "correct_answer": "果然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "没想到他果然会唱歌。", "explanation": "这里应该用〈居然〉。“没想到”表示意外，果然表示与预料相符，两者语气矛盾。"}, {"text": "我以为他不会赢，结果他果然赢了。", "explanation": "这里应该用〈竟然〉。前文是“以为他不会赢”，结果出乎意料，要用竟然；果然只用于与预料相符的结果。"}, {"text": "他平时总做不对这种题，这次却果然全都做对了。", "explanation": "这里应该用〈居然〉。前文说他平时总做不对，“却”引出出乎意料的结果，要用居然；果然表示结果与预料相符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果然", "is_correct": true, "explanation": "果然：表示医生所说的“多休息就会好”真的应验了。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示付出没有收获，与“好了”这个好结果相反。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”表示长期如此的状况，与休息三天后的变化不合。"}, {"text": "永远", "is_correct": false, "explanation": "搭配：“永远”要与持续的状态连用，不能与“好了”这种变化搭配。"}], "explanations": {"果然": "果然：表示医生所说的“多休息就会好”真的应验了。", "白白": "语义：“白白”表示付出没有收获，与“好了”这个好结果相反。", "一向": "语义：“一向”表示长期如此的状况，与休息三天后的变化不合。", "永远": "搭配：“永远”要与持续的状态连用，不能与“好了”这种变化搭配。"}, "sentence_index": 6, "correct_answer": "果然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我真希望他果然能来。", "explanation": "这里应该用〈真的〉。果然只说已经证实的事，“希望”说的是还没发生的愿望，应说“希望他真的能来”。"}, {"text": "请你果然按时到达。", "explanation": "这里应该用〈一定〉。果然只说已经证实的事，“请你……”是对未来的要求，要用〈一定〉：请你一定按时到达。"}, {"text": "果然别哭了！", "explanation": "这里应该用〈快〉。果然表示事情已经发生或被证实，不能用于劝阻；劝人别哭要用〈快〉这类催促的词，如：快别哭了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐说路上会堵车，我们果然果然堵车了。", "corrected_sentence": "姐姐说路上会堵车，我们果然堵车了。", "error_description": "错误：“果然”重复出现，属于多余的重复。应写成“我们果然堵车了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说多练习能进步，我练了一个月，果然地进步了。", "corrected_sentence": "老师说多练习能进步，我练了一个月，果然进步了。", "error_description": "错误：“果然”是副词，后面不能加“地”。正确的说法是“果然进步了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
