INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93624, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "确实；果真如先前所料。", "primary_collocate": null, "pronunciation": "guǒ rán", "ipa": "kuo˨˩˦ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "我以为他会迟到，他果然迟到了。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说北京的秋天很美，我去了，果然很美。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟说他吃不完，最后果然剩了一半。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说这件衣服很合适，我试了试，果然合适。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说今晚会有流星雨，天一黑，天上果然出现了很多星星。", "target_word": "果然", "complexity_tier": "T3", "furigana": "guǒ rán", "sentence_source": "generated"}, {"text": "我猜妈妈把礼物藏在了厨房，我走进去一看，礼物果然在柜子里。", "target_word": "果然", "complexity_tier": "T3", "furigana": "guǒ rán", "sentence_source": "generated"}, {"text": "爸爸说这条路很近，我们走了十分钟，果然到了。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说他很聪明，我和他聊了聊，果然如此。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师昨天说今天要考试，今天果然考试了。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早上看天很黑，中午果然下起了大雨。", "target_word": "果然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "确实如此，果真与先前所料一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c64dac-31c4-43a0-9af4-743730ddc3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果然", "is_correct": true, "explanation": "果然：表示“我以为他会迟到”的预料与结果相符。"}, {"text": "始终", "is_correct": false, "explanation": "体貌：“始终”表示状态从头到尾持续，不能与“迟到了”这样的完成性事件连用。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”要与否定词或习惯性说法连用，不能用于一次性的“迟到了”。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”指过去有过的经历，与“迟到了”的预料应验之义不合。"}], "explanations": {"果然": "果然：表示“我以为他会迟到”的预料与结果相符。", "始终": "体貌：“始终”表示状态从头到尾持续，不能与“迟到了”这样的完成性事件连用。", "从来": "搭配：“从来”要与否定词或习惯性说法连用，不能用于一次性的“迟到了”。", "曾经": "体貌：“曾经”指过去有过的经历，与“迟到了”的预料应验之义不合。"}, "sentence_index": 0, "correct_answer": "果然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "没想到这件衣服果然合适。", "explanation": "这里应该用〈居然〉。“没想到”表示意外，果然表示与预料相符，两者语气矛盾。"}, {"text": "他一向不爱运动，这次却果然跑完了全程。", "explanation": "这里应该用〈偏偏〉。前文说他一向不爱运动，“却”引出出乎意料的结果，要用偏偏；果然表示结果与预料相符。"}, {"text": "你果然别迟到了！", "explanation": "这里应该用〈千万〉。果然表示已经发生或已被证实的事，“别迟到了”是劝阻，要用〈千万〉：千万别迟到了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果然", "is_correct": true, "explanation": "果然：表示走了十分钟后真的到达，符合“这条路很近”的说法。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示动作不经常发生，与这一次到达的情况不合。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示付出没有收获，与“到了”这个结果相反。"}, {"text": "永远", "is_correct": false, "explanation": "搭配：“永远”要与持续的状态连用，不能用于“到了”这种一次性结果。"}], "explanations": {"果然": "果然：表示走了十分钟后真的到达，符合“这条路很近”的说法。", "偶尔": "语义：“偶尔”表示动作不经常发生，与这一次到达的情况不合。", "白白": "语义：“白白”表示付出没有收获，与“到了”这个结果相反。", "永远": "搭配：“永远”要与持续的状态连用，不能用于“到了”这种一次性结果。"}, "sentence_index": 6, "correct_answer": "果然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我本来担心下雨，结果果然天晴了。", "explanation": "这里应该用〈竟然〉。前文是“担心下雨”，结果出乎意料，要用竟然；果然表示与预料相符。"}, {"text": "我真希望明天果然是晴天。", "explanation": "这里应该用〈真的〉。果然只说已经证实的事，“希望”说的是愿望，应说“希望明天真的是晴天”。"}, {"text": "请你果然按时到达。", "explanation": "这里应该用〈一定〉。果然只说已经证实的事，“请你……”是对未来的要求，要用〈一定〉：请你一定按时到达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板说今年会加薪，我们果然果然加薪了。", "corrected_sentence": "老板说今年会加薪，我们果然加薪了。", "error_description": "错误：“果然”重复出现，属于多余的重复。应写成“我们果然加薪了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈说今天会降温，我们穿上外套，果然地变冷了。", "corrected_sentence": "妈妈说今天会降温，我们穿上外套，果然变冷了。", "error_description": "错误：“果然”是副词，后面不能加“地”。正确的说法是“果然变冷了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
