INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93629, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "死路是走到头没有出口的路。", "primary_collocate": null, "pronunciation": "sǐ lù", "ipa": "sɨ˨˩˦ lu˥˩", "syllable_count": 2, "sentences": [{"text": "前面是一条死路，我们回去吧。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小路是死路，车开不过去。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走进了一条死路。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机看到死路，就把车停下来了。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小路的尽头是死路，只有一堵墙。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上说这里是死路。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在死路上跑来跑去，大人很担心。", "target_word": "死路", "complexity_tier": "T3", "furigana": "hái zi men zài sǐ lù shàng pǎo lái pǎo qù, dà rén hěn dān xīn。", "sentence_source": "generated"}, {"text": "这条死路很安静，没有什么人。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开了很久，才发现这是死路。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的死路旁边有一家小店。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "走到头没有出口的实际道路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '086a2607-6390-45a4-bc25-eb84138f39a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93629, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "死路", "is_correct": true, "explanation": "死路（sǐ lù）：走到头没有出口的实际道路。"}, {"text": "思路", "is_correct": false, "explanation": "思路（sī lù）与 sǐ 声调不同（第一声与第三声），意思是思考问题的线索。"}, {"text": "指路", "is_correct": false, "explanation": "指路（zhǐ lù）与 sǐ 声母不同（zh 与 s），意思是给人指引道路。"}, {"text": "此路", "is_correct": false, "explanation": "此路（cǐ lù）与 sǐ 声母不同（c 与 s），意思是这条路。"}], "explanations": {"死路": "死路（sǐ lù）：走到头没有出口的实际道路。", "思路": "思路（sī lù）与 sǐ 声调不同（第一声与第三声），意思是思考问题的线索。", "指路": "指路（zhǐ lù）与 sǐ 声母不同（zh 与 s），意思是给人指引道路。", "此路": "此路（cǐ lù）与 sǐ 声母不同（c 与 s），意思是这条路。"}, "sentence_index": null, "correct_answer": "死路"}, "level_3": {"options": [{"text": "死路", "is_correct": true, "explanation": "“前面是一条死路，我们回去吧”，死路是走不通的道路，所以要回去，符合句意。"}, {"text": "大道", "is_correct": false, "explanation": "语义：“大道”是宽阔可走的道路，与“我们回去吧”的理由相矛盾。"}, {"text": "通路", "is_correct": false, "explanation": "语义：“通路”指能通行的路，与需要回去的语境相反。"}, {"text": "坦途", "is_correct": false, "explanation": "语域：“坦途”是书面语，用在口语提议里不协调，而且平坦的路也不是回去的理由。"}], "explanations": {"死路": "“前面是一条死路，我们回去吧”，死路是走不通的道路，所以要回去，符合句意。", "大道": "语义：“大道”是宽阔可走的道路，与“我们回去吧”的理由相矛盾。", "通路": "语义：“通路”指能通行的路，与需要回去的语境相反。", "坦途": "语域：“坦途”是书面语，用在口语提议里不协调，而且平坦的路也不是回去的理由。"}, "sentence_index": 0, "correct_answer": "死路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着死路一直往前开，很快就到了市中心。", "explanation": "这里应该用〈大道〉。死路走不通，不能说“沿着死路一直往前开”，应该是沿着大道往前开。"}, {"text": "这条死路很长，大家很快就从这里走了出去。", "explanation": "这里应该用〈通道〉。“死路”指走到头没有出口的路，不能说从这里走出去；应说“通道”。"}, {"text": "我们走进了一座死路，车只好掉头。", "explanation": "量词错误：“死路”应配〈条〉，〈座〉用于山、桥、楼房等大型物体，不能用来修饰道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93629, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "死路", "is_correct": true, "explanation": "死路（sǐ lù）：走到头没有出口的实际道路。"}, {"text": "丝路", "is_correct": false, "explanation": "丝路（sī lù）与 sǐ 声调不同，意思是丝绸之路。"}, {"text": "私路", "is_correct": false, "explanation": "私路（sī lù）与 sǐ 声调不同（第一声与第三声），意思是私人修建或使用的道路。"}, {"text": "死力", "is_correct": false, "explanation": "死力（sǐ lì）与 lù 韵母不同（u 与 i），意思是拼尽全力。"}], "explanations": {"死路": "死路（sǐ lù）：走到头没有出口的实际道路。", "丝路": "丝路（sī lù）与 sǐ 声调不同，意思是丝绸之路。", "私路": "私路（sī lù）与 sǐ 声调不同（第一声与第三声），意思是私人修建或使用的道路。", "死力": "死力（sǐ lì）与 lù 韵母不同（u 与 i），意思是拼尽全力。"}, "sentence_index": null, "correct_answer": "死路"}, "level_3": {"options": [{"text": "死路", "is_correct": true, "explanation": "“孩子们在死路上跑来跑去”，死路是可以让人站立奔跑的实际道路，符合句意。"}, {"text": "水面", "is_correct": false, "explanation": "语义：人不能在水面上跑来跑去，与句意不符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：人不能在天空上跑来跑去，句子说不通。"}, {"text": "大门", "is_correct": false, "explanation": "搭配：“在……上跑”接的是可以奔跑的地面，“大门”不能这样跑。"}], "explanations": {"死路": "“孩子们在死路上跑来跑去”，死路是可以让人站立奔跑的实际道路，符合句意。", "水面": "语义：人不能在水面上跑来跑去，与句意不符。", "天空": "语义：人不能在天空上跑来跑去，句子说不通。", "大门": "搭配：“在……上跑”接的是可以奔跑的地面，“大门”不能这样跑。"}, "sentence_index": 6, "correct_answer": "死路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车子穿过死路，开到了山的另一边。", "explanation": "这里应该用〈隧道〉。死路走不通，不能说“穿过死路”；能穿过的是隧道。"}, {"text": "我们在一扇死路前停下了车。", "explanation": "量词错误：“死路”应配〈条〉，〈扇〉用于门窗，不能修饰道路。"}, {"text": "前面的死路路口很热闹，车来车往。", "explanation": "这里应该用〈路口〉。死路是走到头没有出口的路，不会有路口，车也无法从中转向来往。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个死路，我们只能掉头。", "corrected_sentence": "这是一条死路，我们只能掉头。", "error_description": "量词错误：“死路”应配量词“条”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前面的死路停着一辆车。", "corrected_sentence": "前面的死路上停着一辆车。", "error_description": "漏掉方位词“上”：表示车停在某处，要说“死路上停着一辆车”，不能直接说“死路停着一辆车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93630, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出路", "is_correct": true, "explanation": "出路：与“死路”在此义上相对，指有出口、能走通的境地。"}, {"text": "音乐", "is_correct": false, "explanation": "音乐：一种艺术形式，与“死路”没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户：房屋墙上通风透光的开口，与“死路”没有语义上的相对关系。"}, {"text": "办法", "is_correct": false, "explanation": "办法：解决问题的方式，与“死路”没有反义关系，不是相对的概念。"}], "correct_answer": "出路", "explanations": {"出路": "出路：与“死路”在此义上相对，指有出口、能走通的境地。", "音乐": "音乐：一种艺术形式，与“死路”没有反义关系。", "窗户": "窗户：房屋墙上通风透光的开口，与“死路”没有语义上的相对关系。", "办法": "办法：解决问题的方式，与“死路”没有反义关系，不是相对的概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93630, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出路", "is_correct": true, "explanation": "出路：与“死路”在此义上相对，指有出口、能走通的境地。"}, {"text": "音乐", "is_correct": false, "explanation": "音乐：一种艺术形式，与“死路”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头：一种坚硬的岩石，与“死路”没有语义上的相对关系。"}, {"text": "天空", "is_correct": false, "explanation": "天空：指地面上方的空间，与“死路”没有反义关系。"}], "correct_answer": "出路", "explanations": {"出路": "出路：与“死路”在此义上相对，指有出口、能走通的境地。", "音乐": "音乐：一种艺术形式，与“死路”没有反义关系。", "石头": "石头：一种坚硬的岩石，与“死路”没有语义上的相对关系。", "天空": "天空：指地面上方的空间，与“死路”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93630, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "走不通的路；比喻没有出路的境地。", "primary_collocate": null, "pronunciation": "sǐ lù", "ipa": "sɨ˨˩˦ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这样做只会走上死路。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得自己的生意已经走到了死路。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不改变办法，公司只有死路一条。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怕，这件事还不是死路。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以为考试失败就是死路，其实不是。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划是死路，我们换一个吧。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知道怎么办，觉得自己已经走到死路了。", "target_word": "死路", "complexity_tier": "T3", "furigana": "tā bù zhī dào zěn me bàn, jué de zì jǐ yǐ jīng zǒu dào sǐ lù le。", "sentence_source": "generated"}, {"text": "老板说，不做新产品就是死路。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能再往死路上走了。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于明白，骗人是一条死路。", "target_word": "死路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "比喻没有出路的境地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '086a2607-6390-45a4-bc25-eb84138f39a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93630, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "死路", "is_correct": true, "explanation": "死路（sǐ lù）：走不通的路，比喻没有出路的境地。"}, {"text": "思路", "is_correct": false, "explanation": "思路（sī lù）与 sǐ 声调不同（第一声与第三声），意思是思考问题的线索。"}, {"text": "指路", "is_correct": false, "explanation": "指路（zhǐ lù）与 sǐ 声母不同（zh 与 s），意思是给人指引道路。"}, {"text": "此路", "is_correct": false, "explanation": "此路（cǐ lù）与 sǐ 声母不同（c 与 s），意思是这条路。"}], "explanations": {"死路": "死路（sǐ lù）：走不通的路，比喻没有出路的境地。", "思路": "思路（sī lù）与 sǐ 声调不同（第一声与第三声），意思是思考问题的线索。", "指路": "指路（zhǐ lù）与 sǐ 声母不同（zh 与 s），意思是给人指引道路。", "此路": "此路（cǐ lù）与 sǐ 声母不同（c 与 s），意思是这条路。"}, "sentence_index": null, "correct_answer": "死路"}, "level_3": {"options": [{"text": "死路", "is_correct": true, "explanation": "“只会走上死路”，死路指没有出路的境地，符合“只会”所表达的负面结果。"}, {"text": "正路", "is_correct": false, "explanation": "语义：“正路”是正确的道路，与“只会”所表达的负面结果矛盾。"}, {"text": "大门", "is_correct": false, "explanation": "搭配：“走上”接道路、台阶，不接“大门”，应说“走进大门”。"}, {"text": "坦途", "is_correct": false, "explanation": "语域：“坦途”是书面语，口语中这样用不协调，而且与“只会”的负面语气相矛盾。"}], "explanations": {"死路": "“只会走上死路”，死路指没有出路的境地，符合“只会”所表达的负面结果。", "正路": "语义：“正路”是正确的道路，与“只会”所表达的负面结果矛盾。", "大门": "搭配：“走上”接道路、台阶，不接“大门”，应说“走进大门”。", "坦途": "语域：“坦途”是书面语，口语中这样用不协调，而且与“只会”的负面语气相矛盾。"}, "sentence_index": 0, "correct_answer": "死路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "后视镜的死路让司机很难看到后面的车辆。", "explanation": "这里应该用〈死角〉。“死角”指视线看不到、容易被忽视的地方，“死路”指走不通的路，不能用来说后视镜的盲区。"}, {"text": "他的生意已经走到一座死路。", "explanation": "量词错误：“死路”不能用〈座〉，〈座〉多用于山、桥、楼房等大型物体。这里应该说“走到死路”或“走到一条死路”。"}, {"text": "他的死路是怕冷，一到冬天就不出门。", "explanation": "这里应该用〈死穴〉。“死穴”指致命的弱点，“死路”指走不通的路或没有出路的境地，不能用来说一个人的弱点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93630, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "死路", "is_correct": true, "explanation": "死路（sǐ lù）：走不通的路，比喻没有出路的境地。"}, {"text": "丝路", "is_correct": false, "explanation": "丝路（sī lù）与 sǐ 声调不同，意思是丝绸之路。"}, {"text": "四路", "is_correct": false, "explanation": "四路（sì lù）与 sǐ 声调不同（第四声与第三声），意思是四条路。"}, {"text": "死力", "is_correct": false, "explanation": "死力（sǐ lì）与 lù 韵母不同（u 与 i），意思是拼尽全力。"}], "explanations": {"死路": "死路（sǐ lù）：走不通的路，比喻没有出路的境地。", "丝路": "丝路（sī lù）与 sǐ 声调不同，意思是丝绸之路。", "四路": "四路（sì lù）与 sǐ 声调不同（第四声与第三声），意思是四条路。", "死力": "死力（sǐ lì）与 lù 韵母不同（u 与 i），意思是拼尽全力。"}, "sentence_index": null, "correct_answer": "死路"}, "level_3": {"options": [{"text": "死路", "is_correct": true, "explanation": "“走到死路了”，死路指没有出路的境地，与“不知道怎么办”的处境相符。"}, {"text": "出口", "is_correct": false, "explanation": "语义：“走到出口”意味着找到了出路，与“不知道怎么办”的困境相矛盾。"}, {"text": "大路", "is_correct": false, "explanation": "语义：“走到大路”意味着回到了通畅的道路，与“不知道怎么办”的处境矛盾。"}, {"text": "绝望", "is_correct": false, "explanation": "搭配：“走到”接地点或路程，说“走到绝望”不自然，应说“陷入绝望”。"}], "explanations": {"死路": "“走到死路了”，死路指没有出路的境地，与“不知道怎么办”的处境相符。", "出口": "语义：“走到出口”意味着找到了出路，与“不知道怎么办”的困境相矛盾。", "大路": "语义：“走到大路”意味着回到了通畅的道路，与“不知道怎么办”的处境矛盾。", "绝望": "搭配：“走到”接地点或路程，说“走到绝望”不自然，应说“陷入绝望”。"}, "sentence_index": 6, "correct_answer": "死路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在死路中坚持了三年，终于活了下来。", "explanation": "这里应该用〈绝境〉。“在……中”后接的是处境类词语，“死路”是走不通的路，不能说“在死路中”。"}, {"text": "他终于找到了死路，可以离开这里了。", "explanation": "这里应该用〈出路〉。“死路”指没有出路的境地，不能说“找到死路”，找到的应是出路。"}, {"text": "他想出的办法只是一扇死路。", "explanation": "量词错误：“死路”应配〈条〉，〈扇〉用于门窗，不能用来修饰“死路”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不改变办法，我们只能走上一个死路。", "corrected_sentence": "不改变办法，我们只能走上一条死路。", "error_description": "量词错误：“死路”应配量词“条”，不能用“个”。正确的说法是“走上一条死路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直走死路上，没有回头。", "corrected_sentence": "他一直走在死路上，没有回头。", "error_description": "漏掉介词“在”：表示“走在某处”要说“走在死路上”，不能说“走死路上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不正当", "is_correct": true, "explanation": "反义词：“正当”指合理合法，“不正当”指不合理、不合法，二者相对。"}, {"text": "辽阔", "is_correct": false, "explanation": "与“正当”无反义关系：“辽阔”形容空间广大。"}, {"text": "高大", "is_correct": false, "explanation": "与“正当”无反义关系：“高大”形容体形或物体的高度。"}, {"text": "沉重", "is_correct": false, "explanation": "与“正当”无反义关系：“沉重”形容重量或心情的压抑。"}], "correct_answer": "不正当", "explanations": {"不正当": "反义词：“正当”指合理合法，“不正当”指不合理、不合法，二者相对。", "辽阔": "与“正当”无反义关系：“辽阔”形容空间广大。", "高大": "与“正当”无反义关系：“高大”形容体形或物体的高度。", "沉重": "与“正当”无反义关系：“沉重”形容重量或心情的压抑。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不正当", "is_correct": true, "explanation": "反义词：“正当”指合理合法，“不正当”指不合理、不合法，二者相对。"}, {"text": "甜美", "is_correct": false, "explanation": "与“正当”无反义关系：“甜美”形容声音、笑容或味道。"}, {"text": "冷清", "is_correct": false, "explanation": "与“正当”无反义关系：“冷清”形容场所或气氛寂静、少人。"}, {"text": "湿润", "is_correct": false, "explanation": "与“正当”无反义关系：“湿润”形容含水分多的状态。"}], "correct_answer": "不正当", "explanations": {"不正当": "反义词：“正当”指合理合法，“不正当”指不合理、不合法，二者相对。", "甜美": "与“正当”无反义关系：“甜美”形容声音、笑容或味道。", "冷清": "与“正当”无反义关系：“冷清”形容场所或气氛寂静、少人。", "湿润": "与“正当”无反义关系：“湿润”形容含水分多的状态。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "正当是对的，不是坏的，也是没有问题的。", "primary_collocate": null, "pronunciation": "zhèng dàng", "ipa": "ʈʂəŋ˥˩ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他有一份正当的工作，不做坏事。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些钱来路正当，你不用担心。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱看书是正当的爱好，不是坏习惯。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想用正当的方法赚钱，这很好。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生意的做法很正当，大家都放心。", "target_word": "正当", "complexity_tier": "T3", "furigana": "zhè ge shēng yì de zuò fǎ hěn zhèngdàng, dà jiā dōu fàng xīn.", "sentence_source": "generated"}, {"text": "他做的事都很正当，没有人说他不对。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，用正当的办法学习才有用。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这是正当的生意，不怕别人看。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠正当的劳动养活家人。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我正当的收入，不是偷来的。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不正当", "label": "复合"}, {"form": "正当防卫", "label": "复合"}, {"form": "正當", "label": "繁体"}], "register": "中性", "sense_fingerprint": "正当：做法、收入、爱好等是对的、不坏、没有问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '156c6536-9aaa-4682-9ec7-bdb78ccbc235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。正当（zhèng dàng）指合理合法、没有问题。"}, {"text": "政党", "is_correct": false, "explanation": "dǎng（第三声）与 dàng（第四声）声调不同，意思是政党。"}, {"text": "争当", "is_correct": false, "explanation": "zhēng 与 zhèng 声调不同，dāng 与 dàng 声调也不同，意思是争取担任。"}, {"text": "中档", "is_correct": false, "explanation": "zhōng（第一声）与 zhèng（第四声）韵母和声调都不同，意思是中等档次。"}], "explanations": {"正当": "正确答案。正当（zhèng dàng）指合理合法、没有问题。", "政党": "dǎng（第三声）与 dàng（第四声）声调不同，意思是政党。", "争当": "zhēng 与 zhèng 声调不同，dāng 与 dàng 声调也不同，意思是争取担任。", "中档": "zhōng（第一声）与 zhèng（第四声）韵母和声调都不同，意思是中等档次。"}, "sentence_index": null, "correct_answer": "正当"}, "level_3": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。“正当”指工作合理合法，与后文“不做坏事”一致。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”指残暴、恶劣，与后文“不做坏事”矛盾。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”说明情况或道理是否明白，不能修饰“工作”。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描述人的体形，不能用来形容工作。"}], "explanations": {"正当": "正确答案。“正当”指工作合理合法，与后文“不做坏事”一致。", "凶狠": "语义：“凶狠”指残暴、恶劣，与后文“不做坏事”矛盾。", "清楚": "搭配：“清楚”说明情况或道理是否明白，不能修饰“工作”。", "胖": "体貌：“胖”描述人的体形，不能用来形容工作。"}, "sentence_index": 0, "correct_answer": "正当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的答案很正当。", "explanation": "这里应该用〈正确〉。“正当”说做法、理由合理合法，答案对错要用“正确”。"}, {"text": "孩子的心跳很正当。", "explanation": "这里应该用〈正常〉。“正当”说做法、理由合理合法，心跳是否正常要用“正常”。"}, {"text": "这批零件很正当。", "explanation": "这里应该用〈合格〉。“正当”说做法、理由合理合法，零件质量是否达标要用“合格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。正当（zhèng dàng）指合理合法、没有问题。"}, {"text": "震荡", "is_correct": false, "explanation": "zhèn 与 zhèng 韵尾不同（n 与 ng），意思是震动、动荡。"}, {"text": "整党", "is_correct": false, "explanation": "zhěng 与 zhèng 声调不同，dǎng 与 dàng 声调也不同，意思是整顿党组织。"}, {"text": "真当", "is_correct": false, "explanation": "zhēn 与 zhèng 韵尾与声调都不同，意思是真的当作。"}], "explanations": {"正当": "正确答案。正当（zhèng dàng）指合理合法、没有问题。", "震荡": "zhèn 与 zhèng 韵尾不同（n 与 ng），意思是震动、动荡。", "整党": "zhěng 与 zhèng 声调不同，dǎng 与 dàng 声调也不同，意思是整顿党组织。", "真当": "zhēn 与 zhèng 韵尾与声调都不同，意思是真的当作。"}, "sentence_index": null, "correct_answer": "正当"}, "level_3": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。“正当”指办法合理，与“学习才有用”相符。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人或物的体形，不能修饰“办法”。"}, {"text": "残暴", "is_correct": false, "explanation": "语义：“残暴”形容凶恶狠毒，修饰“办法”语义不通，与“学习才有用”无关。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人的年龄，不能修饰“办法”。"}], "explanations": {"正当": "正确答案。“正当”指办法合理，与“学习才有用”相符。", "矮小": "体貌：“矮小”形容人或物的体形，不能修饰“办法”。", "残暴": "语义：“残暴”形容凶恶狠毒，修饰“办法”语义不通，与“学习才有用”无关。", "年轻": "搭配：“年轻”说人的年龄，不能修饰“办法”。"}, "sentence_index": 6, "correct_answer": "正当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个数字很正当。", "explanation": "这里应该用〈精确〉。“正当”说做法、理由合理合法，数字的准确程度要用“精确”。"}, {"text": "他的发音很正当。", "explanation": "这里应该用〈标准〉。“正当”说做法、理由合理合法，发音是否符合规范要用“标准”。"}, {"text": "字迹很正当。", "explanation": "这里应该用〈清晰〉。“正当”说做法、理由合理合法，字迹的清楚程度要用“清晰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他靠正当地手段还清了债务，大家都很敬佩。", "corrected_sentence": "他靠正当的手段还清了债务，大家都很敬佩。", "error_description": "结构助词错误：“正当”修饰名词“手段”时要用“的”，不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做的是正当得生意，不怕别人查。", "corrected_sentence": "他做的是正当的生意，不怕别人查。", "error_description": "助词错误：“正当”修饰名词时要用“的”，不用“得”，应说“正当的生意”，不说“正当得生意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93632, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不正当", "is_correct": true, "explanation": "反义词：“正当”指合理合法，“不正当”指不合理、不合法，二者相对。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“正当”无反义关系：“陡峭”形容地势高低落差大。"}, {"text": "狭窄", "is_correct": false, "explanation": "与“正当”无反义关系：“狭窄”形容空间小、不宽阔。"}, {"text": "嘹亮", "is_correct": false, "explanation": "与“正当”无反义关系：“嘹亮”形容声音高亮清晰。"}], "correct_answer": "不正当", "explanations": {"不正当": "反义词：“正当”指合理合法，“不正当”指不合理、不合法，二者相对。", "陡峭": "与“正当”无反义关系：“陡峭”形容地势高低落差大。", "狭窄": "与“正当”无反义关系：“狭窄”形容空间小、不宽阔。", "嘹亮": "与“正当”无反义关系：“嘹亮”形容声音高亮清晰。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
