EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93632, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。正当（zhèng dàng）指合理合法、合乎道理。"}, {"text": "政党", "is_correct": false, "explanation": "dǎng（第三声）与 dàng（第四声）声调不同，意思是政党。"}, {"text": "争当", "is_correct": false, "explanation": "zhēng 与 zhèng 声调不同，dāng 与 dàng 声调也不同，意思是争取担任。"}, {"text": "中档", "is_correct": false, "explanation": "zhōng（第一声）与 zhèng（第四声）韵母和声调都不同，意思是中等档次。"}], "explanations": {"正当": "正确答案。正当（zhèng dàng）指合理合法、合乎道理。", "政党": "dǎng（第三声）与 dàng（第四声）声调不同，意思是政党。", "争当": "zhēng 与 zhèng 声调不同，dāng 与 dàng 声调也不同，意思是争取担任。", "中档": "zhōng（第一声）与 zhèng（第四声）韵母和声调都不同，意思是中等档次。"}, "sentence_index": null, "correct_answer": "正当"}, "level_3": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。“正当理由”指合乎道理，与“不能不来上班”的语境相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，不能修饰“理由”。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多形容声音、笑容，不能修饰“理由”。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”指残暴，修饰“理由”语义不通，与“不能不来上班”无关。"}], "explanations": {"正当": "正确答案。“正当理由”指合乎道理，与“不能不来上班”的语境相符。", "高大": "体貌：“高大”形容人或物的体形，不能修饰“理由”。", "甜美": "搭配：“甜美”多形容声音、笑容，不能修饰“理由”。", "凶狠": "语义：“凶狠”指残暴，修饰“理由”语义不通，与“不能不来上班”无关。"}, "sentence_index": 0, "correct_answer": "正当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的血压很正当。", "explanation": "这里应该用〈正常〉。“正当”说做法、理由合理合法，血压等身体指标要用“正常”。"}, {"text": "他的字迹很正当。", "explanation": "这里应该用〈清晰〉。“正当”说做法、理由合理合法，字迹的清楚程度要用“清晰”。"}, {"text": "他的发音很正当。", "explanation": "这里应该用〈标准〉。“正当”说做法、理由合理合法，发音是否符合规范要用“标准”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93632, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。正当（zhèng dàng）指合理合法、合乎道理。"}, {"text": "震荡", "is_correct": false, "explanation": "zhèn 与 zhèng 韵尾不同（n 与 ng），意思是震动、动荡。"}, {"text": "整党", "is_correct": false, "explanation": "zhěng 与 zhèng 声调不同，dǎng 与 dàng 声调也不同，意思是整顿党组织。"}, {"text": "真当", "is_correct": false, "explanation": "zhēn 与 zhèng 韵尾与声调都不同，意思是真的当作。"}], "explanations": {"正当": "正确答案。正当（zhèng dàng）指合理合法、合乎道理。", "震荡": "zhèn 与 zhèng 韵尾不同（n 与 ng），意思是震动、动荡。", "整党": "zhěng 与 zhèng 声调不同，dǎng 与 dàng 声调也不同，意思是整顿党组织。", "真当": "zhēn 与 zhèng 韵尾与声调都不同，意思是真的当作。"}, "sentence_index": null, "correct_answer": "正当"}, "level_3": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。“正当理由”指合理合法的请假原因，与“老板同意了”相呼应。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”形容残暴，不能用来说明请假理由是否合乎道理。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容体形，不能修饰“理由”。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人的年龄，不能修饰“理由”。"}], "explanations": {"正当": "正确答案。“正当理由”指合理合法的请假原因，与“老板同意了”相呼应。", "凶狠": "语义：“凶狠”形容残暴，不能用来说明请假理由是否合乎道理。", "矮小": "体貌：“矮小”形容体形，不能修饰“理由”。", "年轻": "搭配：“年轻”说人的年龄，不能修饰“理由”。"}, "sentence_index": 6, "correct_answer": "正当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器很正当。", "explanation": "这里应该用〈合格〉。“正当”说做法、理由合理合法，机器质量是否达标要用“合格”。"}, {"text": "这次测量很正当。", "explanation": "这里应该用〈精确〉。“正当”说做法、理由合理合法，测量的准确程度要用“精确”。"}, {"text": "这份文件的格式很正当。", "explanation": "这里应该用〈规范〉。“正当”说做法、理由合理合法，格式是否符合要求要用“规范”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有了正当地工作机会，就去面试了。", "corrected_sentence": "他有了正当的工作机会，就去面试了。", "error_description": "结构助词错误：“正当”修饰名词“机会”时要用“的”，不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人为了争取正当得待遇，去找经理谈。", "corrected_sentence": "工人为了争取正当的待遇，去找经理谈。", "error_description": "助词错误：“正当”修饰名词时要用“的”，不用“得”，应说“正当的待遇”，不说“正当得待遇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
